import{a as e}from"./jsx-runtime-Bzw2jH9X.js";var t=e({default:()=>n}),n=JSON.parse(`[{"id":"qx-f-001","clusterId":"F","werkstueckRef":"F.0","stufe":1,"question":"Ein Forschungsteam testet eine kühne, noch unbewiesene Hypothese. Der entscheidende Versuch fällt negativ aus. Woran erkennst du, dass das Team trotz der gewagten Idee ehrlich wissenschaftlich arbeitet und nicht nur den Anschein davon erzeugt?","options":["Es beschreibt den Versuch in sorgfältiger Fachsprache mit Formeln und Fachbegriffen.","Es besteht aus Fachleuten anerkannter Universitäten, die akademische Titel tragen.","Es erkennt das Scheitern des Tests an und passt die Hypothese an oder gibt sie ganz auf.","Es betont die Kühnheit der Hypothese, denn große Entdeckungen standen oft gegen die Lehrmeinung."],"correctIndex":2,"explanation":"Eine kühne Hypothese ist noch kein Warnsignal: Spekulation ist legitim, solange sie prüfbar bleibt. Entscheidend ist der Umgang mit dem Scheitern: In ehrlicher Forschung an der Grenze des Wissens wird ein gescheiterter Test anerkannt und führt dazu, dass die Hypothese angepasst oder aufgegeben wird. In der Pseudowissenschaft werden widersprechende Befunde dagegen oft ignoriert, wegerklärt oder umgedeutet. Wer ein negatives Ergebnis ernst nimmt, zeigt, dass die Idee an der Wirklichkeit scheitern kann, und genau das unterscheidet ehrliche Forschung von bloßer Imitation. Die anderen Merkmale klingen nach Wissenschaft, lassen sich aber nachahmen: Fachsprache und Formeln sagen nichts darüber, ob ein Team eine Widerlegung akzeptiert. Titel und Universitäten schützen nicht vor Selbsttäuschung. Und Kühnheit allein ist weder ein Beleg für noch ein Warnzeichen gegen ehrliche Forschung.","coreRule":"⚡ Eine Idee darf kühn sein und scheitern; verdächtig wird sie, wenn jedes Scheitern wegerklärt wird.","beleg":"Werkstück F.0 (Kontext & Tiefe, Abschnitte II und III)","status":"entwurf","kurz":"Entscheidend ist der Umgang mit dem Scheitern: Wer einen negativen Test anerkennt und die Hypothese anpasst oder aufgibt, zeigt, dass sie an der Wirklichkeit scheitern kann. Fachsprache, Titel und Kühnheit lassen sich dagegen leicht nachahmen.","prueffrage":"Welches Ergebnis hätte das Team vorab als Scheitern seiner Hypothese gelten lassen, und gilt das jetzt noch?","rueckmeldung":[{"option":0,"text":"Sorgfältige Fachsprache mit Formeln wirkt seriös und gehört oft zu echter Forschung. Sie lässt sich aber ebenso gut nachahmen und verrät nicht, ob das Team eine Widerlegung tatsächlich akzeptiert."},{"option":1,"text":"Akademische Titel und renommierte Universitäten sprechen oft für Kompetenz. Sie schützen aber nicht vor Selbsttäuschung und zeigen nicht, wie das Team auf ein negatives Ergebnis reagiert."},{"option":3,"text":"Dass große Entdeckungen mitunter gegen die Lehrmeinung standen, stimmt. Kühnheit allein ist aber weder Beleg noch Warnzeichen, und sie ersetzt nicht den ehrlichen Umgang mit dem gescheiterten Test."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: „Science and Pseudo-Science“","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschn. 5.1","abruf":"2026-10-12"},{"typ":"url","kurz":"Feynman, R. P. (1974): „Cargo Cult Science“, Engineering and Science 37(7), Caltech-Scan","oeffentlich":true,"url":"https://calteches.library.caltech.edu/51/2/CargoCult.pdf","seite":"S. 11","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"627c62cb83700b2e"}},{"id":"qx-f-002","clusterId":"F","werkstueckRef":"F.0","stufe":2,"question":"Was ist an dieser Reaktion auf die Pressemitteilung der Denkfehler?","scenario":"Eine Pressemitteilung meldet ein unerwartetes Signal im Detektor: „Es könnte auf neue Physik hindeuten. Messfehler können wir noch nicht ausschließen, deshalb planen wir unabhängige Wiederholungen.“ Ein Kollege winkt ab: „Unbewiesen heißt unwissenschaftlich. Das ist doch genauso Quatsch wie Astrologie.“","options":["Er setzt „noch nicht bewiesen“ mit „unwissenschaftlich“ gleich, obwohl die Mitteilung Unsicherheiten benennt und prüfbare Wiederholungen ankündigt.","Er beruft sich auf die Mehrheitsmeinung: Weil die meisten Fachleute keine neue Physik erwarten, gilt das Signal für ihn schon als widerlegt.","Er kehrt die Beweislast um: Nicht die Forschenden, sondern die Skeptiker müssten zeigen, dass das Signal kein Messfehler ist, bevor man es ernst nimmt.","Er lässt sich von seiner Erwartung leiten: Er sucht nur Gründe gegen neue Physik und übersieht dabei die Belege, die es bereits dafür gibt."],"correctIndex":0,"explanation":"„Nicht bewiesen“ und „widerlegt“ sind verschiedene Zustände. Eine spekulative, aber prüfbare Hypothese, deren Urheber ihre Unsicherheit offen benennen und weitere Tests planen, verhält sich methodisch wie seriöse Forschung am Rand des Wissens, nicht wie Pseudowissenschaft. Was Pseudowissenschaft (etwa Astrologie) auszeichnet, ist nicht, dass sie unbewiesen wäre, sondern dass sie widersprüchliche Beweise ignoriert oder wegerklärt und die Beweislast systematisch umkehrt. Entscheidend ist die Methode, nicht die Seltsamkeit oder der noch ausstehende Beweis. Wer jede unbestätigte Idee pauschal als Pseudowissenschaft ablehnt, riskiert, potenziell revolutionäre, aber noch unbewiesene Konzepte zu verpassen. Umgekehrt gibt es auch die Falle des Naiven, der jede als „alternativ“ dargestellte Idee für legitime Grenzwissenschaft hält. Die anderen Fehlermuster gibt es, sie liegen hier aber nicht vor: Der Kollege beruft sich nicht auf eine Mehrheit der Fachwelt, sondern auf den fehlenden Beweis. Er verschiebt auch keine Beweislast auf Skeptiker, sondern lehnt das Signal von vornherein ab. Und von Belegen, die er übersehen könnte, ist im Szenario keine Rede, denn die Mitteilung selbst spricht von einem noch ungeklärten Signal.","coreRule":"⚡ Maßstab ist die Methode, nicht die Seltsamkeit: „noch nicht bewiesen“ ist nicht „widerlegt“.","beleg":"Werkstück F.0 (Anwendung & Relevanz; Red Flags; Werkbank-Frage)","status":"entwurf","kurz":"„Noch nicht bewiesen“ heißt nicht „unwissenschaftlich“: Die Mitteilung benennt Unsicherheit offen und kündigt prüfbare Wiederholungen an, so arbeitet seriöse Forschung. Pseudowissenschaft erkennt man an der Methode, nicht am ausstehenden Beweis.","prueffrage":"Was haben das Signal im Detektor und die Astrologie gemeinsam, und worin unterscheiden sie sich?","rueckmeldung":[{"option":1,"text":"Skepsis gegenüber einem unerwarteten Signal wirkt vernünftig. Der Kollege nennt aber keine Fachmehrheit, sondern verweist darauf, dass etwas unbewiesen ist. Dass etwas nicht bewiesen ist, heißt zudem nicht, dass es widerlegt wäre."},{"option":2,"text":"Beweislastumkehr ist ein echtes Fehlermuster. Hier verlangt der Kollege aber nichts von Skeptikern, er lehnt das Signal von vornherein ab. Die Mitteilung nennt den möglichen Messfehler selbst und kündigt Wiederholungen an."},{"option":3,"text":"Wer nur nach Gründen gegen eine Idee sucht, lässt sich tatsächlich von seiner Erwartung leiten. Im Szenario gibt es aber noch keine Belege für neue Physik, die er übersehen könnte: Die Mitteilung spricht von einem ungeklärten Signal, nicht von gesicherten Hinweisen."}],"familie":"wissenschaft-abgrenzen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: „Science and Pseudo-Science“","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschn. 4.5, 5.1","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"948ab12fd2ae5ef9"}},{"id":"qx-f-003","clusterId":"F","werkstueckRef":"F.0","stufe":3,"question":"Eine Anbieterin wirbt für ihre Lehre als „mutige Grenzwissenschaft, die von der dogmatischen Schulwissenschaft unterdrückt wird“. Du willst herausfinden, ob die Lehre ernsthafte Forschung am Rand des Wissens oder Pseudowissenschaft ist. Welche Prüfung bringt dich am sichersten weiter?","options":["Du fragst, wie viele Menschen berichten, dass ihnen die Lehre geholfen hat, denn viele übereinstimmende Erfahrungen sprechen für ihre Wirksamkeit.","Du fragst, welchen Test die Anbieterin vorschlägt und was für sie als Scheitern der Idee gälte, denn daran zeigt sich, ob sie sich überprüfen lässt.","Du prüfst, welche Ausbildung und welche Titel die Anbieterin hat, denn wer fachlich ausgewiesen ist, vertritt eher ernsthafte Forschung.","Du fragst, wie lange die Lehre schon besteht, denn was sich über viele Jahre gehalten hat, hat sich in der Regel bewährt."],"correctIndex":1,"explanation":"Ob eine Idee ernsthafte Erkundung oder Pseudowissenschaft ist, entscheidet sich an der Methode, nicht am Etikett und nicht an der Reaktion der anderen. Wer ehrlich am Rand des Wissens forscht, legt offen, wie man seine Idee testen kann, und akzeptiert, dass ein Scheitern des Tests die Idee widerlegt. Die Kombination aus Selbstlob als „mutig“ und dem Vorwurf, unterdrückt zu werden, ist dagegen ein Warnsignal: Sie erklärt Kritik im Voraus zum Beweis für die eigene Richtigkeit und macht die Lehre damit unangreifbar. Die anderen Prüfungen klingen vernünftig, entscheiden aber nichts: Erfolgsberichte Einzelner sind keine kontrollierten Belege und lassen sich für fast jede Lehre finden. Titel und Ausbildung sagen nichts über die Methode, denn auch Ausgewiesene können Unprüfbares vertreten. Und das Alter einer Lehre belegt keine Bewährung, denn Beständigkeit kann auch heißen, dass sie sich nie einem Test gestellt hat.","coreRule":"⚡ Frag nicht „Wie seltsam?“, sondern „Wo ist der Test, und was gälte als Scheitern?“","quote":"","quoteLabel":"","beleg":"Werkstück F.0 (Red Flags; Anwendung & Relevanz; Das Härten im Feuer, Aktivierungs-Frage)","status":"entwurf","scenario":"","kurz":"Entscheidend ist, ob die Anbieterin offenlegt, wie man ihre Idee testen kann und was sie widerlegen würde. Der Fehler wäre, dem Etikett „mutig“ oder der Opferrolle zu glauben, denn damit wird Kritik im Voraus zum Beweis umgedeutet.","prueffrage":"Was weißt du über die Lehre selbst, nachdem die Anbieterin sie „mutig“ und „unterdrückt“ genannt hat?","rueckmeldung":[{"option":0,"text":"Viele Berichte wirken wie ein Beleg, weil sie sich häufen. Sie sind aber keine kontrollierten Vergleiche und lassen sich für fast jede Lehre finden, ob sie nun trägt oder nicht."},{"option":2,"text":"Eine fachliche Ausbildung ist nicht belanglos, sagt aber nichts über die Methode. Auch Ausgewiesene können Unprüfbares vertreten, deshalb muss die Idee selbst auf den Prüfstand."},{"option":3,"text":"Ein langes Bestehen erweckt Vertrauen, weil es nach Bewährung aussieht. Es kann aber auch heißen, dass sich die Lehre nie einem Test gestellt hat, und dann belegt die Dauer nichts."}],"familie":"wissenschaft-abgrenzen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: „Science and Pseudo-Science“","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschn. 4.3, 5.1","abruf":"2026-10-12"},{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","seite":"Einträge „Appeal to Ignorance“, „Misplaced Burden of Proof“","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"1fca36c3dd4fc052"}},{"id":"qx-f-004","clusterId":"F","werkstueckRef":"F.0","stufe":4,"question":"Ein Bekannter wirft Skeptikern vor: „Ihr lehnt einfach alles Neue ab. Früher hat man auch über Ideen gelacht, die später stimmten.“ Welche Antwort geht auf den Einwand am besten ein?","options":["Bei neuen Behauptungen lohnt der Blick auf Geldgeber und Interessen, denn wer von einer Idee profitiert, urteilt selten neutral, und das trifft Außenseiter wie Etablierte.","Bei neuen Ideen sollte man zuerst fragen, wie ausgewiesen die Kritiker im jeweiligen Fach sind, denn ein Urteil aus einem fremden Fachgebiet hat nur geringes Gewicht.","Zuerst sollte geklärt werden, was mit „neu“ und was mit „Skeptiker“ gemeint ist, denn ohne genaue Begriffe redet man aneinander vorbei und kann dem Vorwurf nicht sachlich begegnen.","Neues ist willkommen, wenn es sich prüfen lässt, doch die meisten solcher Ideen scheitern am Test, und nur wenige setzen sich am Ende als gesichertes Wissen durch."],"correctIndex":3,"explanation":"Der Einwand verwechselt zwei Dinge: ob eine Idee neu oder ungewöhnlich ist und ob sie sich prüfen lässt. Entscheidend ist die Methode, nicht die Seltsamkeit der Behauptung. Zwei Fallen liegen nah. In die Falle des Dogmatikers tappt, wer jede neue, seltsam klingende Idee pauschal ablehnt und so potenziell revolutionäre Konzepte verpasst. In die Falle des Naiven tappt, wer jede als „alternativ“ oder „unterdrückt“ dargestellte Idee für legitim hält und so Scharlatanen auf den Leim geht. Die angemessene Haltung gegenüber spekulativen Ideen ist offene, aber kritische Neugier („Wie können wir sie testen?“). Ob eine Idee sich lohnt, zeigt der Test: Die meisten Ideen am Rand des gesicherten Wissens scheitern und verschwinden, nur wenige entwickeln sich zu etablierter Wissenschaft. Geldgeber und Interessen zu prüfen ist sinnvoll, wenn jemand etwas verkauft oder finanziert, doch der Vorwurf lautet hier nicht, dass jemand Interessen verfolgt, sondern dass Neues pauschal abgelehnt werde. Die Fachkenntnis von Kritikern zu hinterfragen hilft, wenn ein Urteil strittig ist, beantwortet aber nicht den Verdacht, Neues werde grundsätzlich abgewiesen. Begriffe zu klären ist nützlich bei unklaren Aussagen, doch der Einwand ist verständlich genug, um in der Sache beantwortet zu werden.","coreRule":"⚡ Offen für Neues, aber nur nach Methode: Prüfbarkeit zählt, nicht Außenseiterstatus. Die meisten Randideen scheitern, einige wenige werden Wissen.","beleg":"Werkstück F.0 (Anwendung & Relevanz: Falle des Dogmatikers und des Naiven; Kontext & Tiefe, Abschnitt II „Fortschritt“)","status":"entwurf","kurz":"Der Einwand verwechselt „neu“ mit „prüfbar“: Entscheidend ist, ob sich eine Idee testen lässt. Wer alles Neue ablehnt, verpasst Gutes, wer alles Neue glaubt, fällt auf Scharlatane herein, denn die meisten Randideen scheitern am Test.","prueffrage":"Wie viele der Ideen, über die früher gelacht wurde, stellten sich später als richtig heraus, und wie viele nicht?","rueckmeldung":[{"option":0,"text":"Geldgeber und Interessen zu prüfen ist sinnvoll, wenn jemand etwas verkauft oder finanziert. Der Vorwurf lautet hier aber nicht, dass jemand Interessen verfolgt, sondern dass Neues pauschal abgelehnt werde, und darauf gibt der Blick auf Geld keine Antwort."},{"option":1,"text":"Wie fachkundig Kritiker sind, ist bei strittigen Urteilen eine berechtigte Frage. Den Verdacht, Neues werde grundsätzlich abgewiesen, räumt das aber nicht aus, denn es sagt nichts darüber, ob sich die Idee prüfen lässt."},{"option":2,"text":"Begriffsklärung hilft bei unklaren Aussagen, doch dieser Einwand ist verständlich genug, um in der Sache beantwortet zu werden. Wer erst über Wörter streitet, weicht der eigentlichen Frage aus, wie sich die neue Idee testen lässt."}],"familie":"wissenschaft-abgrenzen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: „Science and Pseudo-Science“","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschn. 4.5, 5.1","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"5f706dd34b6c090e"}},{"id":"qx-f-005","clusterId":"F","werkstueckRef":"F.1.1","stufe":1,"question":"Eine Prüferin stellt bei einer Heilmethode fest: Die Beweislast wird umgekehrt, die Aussagen sind nicht widerlegbar, es gibt fast nur Erfolgsgeschichten statt kontrollierter Studien, kritische Studien werden ignoriert, die Grundlehre ist seit Jahrhunderten unverändert und mit der Methode lassen sich teure Seminare verkaufen. Was darfst du daraus am vernünftigsten schließen?","options":["Die Methode imitiert sehr wahrscheinlich nur den Anschein von Wissenschaft, auch wenn nicht jedes denkbare Warnzeichen vorliegt.","Die Methode ist ein bewusster Schwindel, denn wer teure Seminare verkauft, täuscht seine Kundschaft vorsätzlich.","Das Muster betrifft nur die Haltung der Anbieter; ob es Pseudowissenschaft ist, entscheidet die Prüfung jeder Einzelbehauptung.","Ein einzelnes Warnzeichen genügt nie für ein Urteil; aus dieser Liste lässt sich daher nichts über die Methode ableiten."],"correctIndex":0,"explanation":"Die Warnzeichen betreffen Methode und Verhalten, nicht den Inhalt jeder Einzelbehauptung. Eine Disziplin muss nicht alle denkbaren Kriterien erfüllen, damit das Muster aussagekräftig ist: Je mehr davon zutreffen, desto wahrscheinlicher ist es, dass nur die äußere Form von Wissenschaft nachgeahmt wird, ohne ihre Prinzipien (Prüfbarkeit, Selbstkorrektur, Offenheit für Gegenbeweise) zu befolgen. Das ist ein Wahrscheinlichkeitsurteil über die Methode, kein Beweis gegen jede einzelne Aussage. Die anderen Schlüsse klingen vorsichtig oder entschieden, tragen aber nicht: Dass ein einzelnes Warnzeichen nicht reicht, stimmt, hier liegen aber mehrere zugleich vor, und gerade ihr Zusammentreffen ist aussagekräftig. Ob das Muster erkennbar ist, hängt nicht davon ab, jede Einzelbehauptung zu prüfen. Und aus dem Verkauf teurer Seminare allein folgt noch keine Täuschungsabsicht, denn Gewinnstreben ist kein Beweis für Vorsatz.","coreRule":"⚡ Methodische Warnzeichen sind ein Scanner für Verhalten: Je mehr Treffer, desto wahrscheinlicher Imitation von Wissenschaft, aber nie ein Beweis.","beleg":"Werkstück F.1.1 (Kontext & Tiefe: 10-Punkte-Checkliste, Schlusssatz)","status":"entwurf","scenario":"","kurz":"Mehrere Warnzeichen zugleich machen es wahrscheinlich, dass hier nur die Form von Wissenschaft nachgeahmt wird, ohne Prüfbarkeit und Selbstkorrektur. Es ist ein Urteil über die Methode, kein Beweis gegen jede Einzelaussage und keine Aussage über Absichten.","prueffrage":"Wie viele der aufgezählten Auffälligkeiten treffen bei dieser Heilmethode zugleich zu?","rueckmeldung":[{"option":1,"text":"Seminare bringen den Anbietern Geld, und zur Methode passt das schlecht. Aber Gewinnstreben ist kein Beweis für Vorsatz: Die Anbieter können selbst an ihre Lehre glauben. Geurteilt wird hier über die Methode, nicht über Absichten."},{"option":2,"text":"Daran stimmt: Das Urteil bleibt eine Wahrscheinlichkeitsaussage und beweist nichts gegen jede Einzelbehauptung. Die Warnzeichen betreffen aber Methode und Verhalten, und das Muster ist erkennbar, ohne jede Einzelaussage zu prüfen."},{"option":3,"text":"Ein einzelnes Warnzeichen reicht tatsächlich nicht für ein Urteil. Hier liegen aber mehrere zugleich vor, und gerade dieses Zusammentreffen ist aussagekräftig. Aus der Liste lässt sich daher durchaus etwas ableiten, wenn auch nur mit Wahrscheinlichkeit."}],"familie":"wissenschaft-abgrenzen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: „Science and Pseudo-Science“","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschn. 5.1, 5.2","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"f53a641c6a4ec062"}},{"id":"qx-f-006","clusterId":"F","werkstueckRef":"F.1.1","stufe":2,"question":"Was ist an dieser Aussage aus Sicht der wissenschaftlichen Methode das Kernproblem?","scenario":"In einem Reiki-Kurs sagt der Leiter: „Wenn die Energieheilung bei dir nicht gewirkt hat, hat deine Skepsis den Energiefluss blockiert.“","options":["Sie verlangt vom Skeptiker, die Nichtexistenz der Energie zu beweisen, statt selbst Belege zu liefern.","Sie macht die Behauptung unwiderlegbar, weil jedes Scheitern dem Prüfenden angelastet werden kann.","Sie stützt sich auf einzelne Erfolgsgeschichten, statt auf kontrollierte Studien zu verweisen.","Sie greift nur die günstigen Ergebnisse heraus und übergeht die Studien, die dagegensprechen."],"correctIndex":1,"explanation":"Eine Behauptung, die jedes Scheitern auf den Prüfenden abwälzt, kann durch kein Experiment widerlegt werden: Wirkt die Behandlung, gilt sie als bestätigt; wirkt sie nicht, war der Zweifler schuld. Eine Aussage, die mit keinem denkbaren Ergebnis unvereinbar ist, sagt nichts Prüfbares über die Welt. Die anderen drei Fehler gibt es zwar, sie kommen in der Aussage aber nicht vor: Der Leiter verlangt keinen Gegenbeweis, beruft sich auf keine Einzelfälle und wählt keine Studien aus.","coreRule":"⚡ Wenn der Zweifler am Misserfolg schuld sein soll, ist die Behauptung nicht mehr prüfbar.","beleg":"Werkstück F.1.1 (Checkliste Punkt 2, mit Beispiel zur Energieheilung)","status":"entwurf","kurz":"Die Aussage lässt sich nie widerlegen: Wirkt die Behandlung, gilt sie als bestätigt, wirkt sie nicht, war der Zweifler schuld. Eine Behauptung, die mit keinem denkbaren Ergebnis unvereinbar ist, sagt nichts Prüfbares über die Welt.","prueffrage":"Welche Belege, Einzelfälle oder Studien führt der Leiter in seinem Satz überhaupt an?","rueckmeldung":[{"option":0,"text":"Die Umkehr der Beweislast ist ein bekannter Fehler und wirkt hier naheliegend. Der Leiter verlangt aber von niemandem einen Gegenbeweis, sondern erklärt im Nachhinein, warum ein Misserfolg nichts gegen seine Behauptung zeigt."},{"option":2,"text":"Einzelne Erfolgsgeschichten sind tatsächlich ein schwacher Beleg und bei Heilversprechen häufig. Im Satz des Leiters kommen aber weder Erfolgsgeschichten noch Studien vor, er beruft sich auf gar keine Fälle."},{"option":3,"text":"Das Herauspicken günstiger Studien ist ein echter Denkfehler und passt zu vielen Heilversprechen. Der Leiter nennt hier jedoch überhaupt keine Studien, weder günstige noch ungünstige. Sein Problem liegt in der Konstruktion des Satzes selbst."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: „Science and Pseudo-Science“","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschn. 4.3, 5.1","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"78c438c3ce185fe5"}},{"id":"qx-f-007","clusterId":"F","werkstueckRef":"F.1.1","stufe":3,"question":"Woran würdest du erkennen, dass aus dieser Hypothese eine Pseudowissenschaft geworden ist?","options":["Sie stützt sich auf Einzelberichte und Zeugenaussagen statt auf kontrollierte Experimente, sodass nie wirklich geprüft wird.","Sie arbeitet mit Fachbegriffen, die nur Eingeweihte verstehen, sodass Außenstehende sie nicht nachvollziehen können.","Sie ist nicht mehr testbar und bestätigt sich selbst, weil jedes denkbare Ergebnis zu ihren Gunsten ausgelegt wird.","Sie beruft sich auf berühmte Namen statt auf Daten, sodass das Ansehen einzelner Personen die Belege ersetzt."],"correctIndex":2,"explanation":"Spekulative, seltsame oder lange unbestätigte Ideen können Wissenschaft bleiben, solange ein Test sie widerlegen könnte. Kippen tut sie, wenn sie sich der Prüfung entzieht: Wer Fehlschläge mit Ausreden auffängt und jedes Ergebnis als Bestätigung liest, hat aus der Hypothese ein Glaubenssystem gemacht, das nichts mehr widerlegen kann. Entscheidend ist die Prüfbarkeit selbst. Einzelberichte statt Experimente wären ein bekanntes Warnzeichen, doch die Forscherin hat experimentell geprüft. Schwer verständliche Fachsprache erschwert das Nachvollziehen, sagt aber nichts darüber, ob ein Ergebnis die Hypothese noch widerlegen dürfte. Der Verweis auf berühmte Namen ersetzt Belege, kommt im Fall der Forscherin aber nicht vor.","coreRule":"⚡ Nicht die Dauer oder die Seltsamkeit entscheidet, sondern ob die Idee noch scheitern darf.","beleg":"Werkstück F.1.1 (Der Kipppunkt)","status":"entwurf","scenario":"Eine Forscherin vertritt seit 20 Jahren eine ungewöhnliche Hypothese, die bisher niemand bestätigen konnte. In den vergangenen Jahren sind mehrere Experimente zur Hypothese gescheitert. Ihre Reaktion: Die Experimente seien nicht empfindlich genug gewesen, denn die Wirkung zeige sich nur, wenn niemand sie zu messen versucht. Jedes weitere Ergebnis deutet sie als Bestätigung.","kurz":"Eine Hypothese kippt in Pseudowissenschaft, wenn kein denkbares Ergebnis sie mehr widerlegen könnte. Dass sie seltsam oder lange unbestätigt ist, genügt nicht; entscheidend ist, dass Fehlschläge durch Ausreden aufgefangen und jedes Ergebnis als Bestätigung gelesen wird.","prueffrage":"Wie viele Experimente sind bisher gescheitert, und was folgerte die Forscherin jeweils daraus?","rueckmeldung":[{"option":0,"text":"Einzelberichte statt Experimente sind ein bekanntes Warnzeichen für fehlende Prüfung. Die Forscherin hat aber experimentell geprüft; ihr Problem liegt darin, wie sie mit den Fehlschlägen umgeht."},{"option":1,"text":"Schwer verständliche Fachsprache macht es mühsam, eine Behauptung nachzuvollziehen. Sie sagt aber nicht, ob ein Ergebnis die Hypothese noch widerlegen dürfte, und im Fall der Forscherin geht es genau darum."},{"option":3,"text":"Sich auf Ansehen statt auf Daten zu berufen, wäre tatsächlich ein Warnzeichen. Im Szenario kommt das aber nicht vor: Die Forscherin beruft sich auf keine Namen, sondern erklärt jedes Ergebnis zu ihren Gunsten."}],"familie":"wissenschaft-abgrenzen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: „Science and Pseudo-Science“","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschn. 3.6, 4.3, 5.1","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"b2590210db023a1d"}},{"id":"qx-f-008","clusterId":"F","werkstueckRef":"F.1.1","stufe":4,"question":"Wie solltest du auf dieses Seminarversprechen reagieren, wenn du seine Stichhaltigkeit prüfen willst?","options":["Du fragst, was „Quantenheilung“ und „biologische Schwingung“ genau bedeuten und wie man ihre Wirkung testen könnte. Bleibt die Antwort vage, ist der Anspruch nicht prüfbar.","Du prüfst bei den angeführten Studien, ob Stichprobengröße und Kontrollgruppe ausreichen. Zu kleine Stichproben ohne Vergleichsgruppe machen Ergebnisse unzuverlässig.","Du lässt dir die Qualifikation der Seminarleitung nachweisen. Ein anerkannter Abschluss ist ein Hinweis darauf, dass jemand in seinem Fach kompetent ist.","Du wägst den möglichen Nutzen und das Risiko des Seminars gegeneinander ab. Bei Heilversprechen kommt es auch darauf an, ob die Teilnahme einem Menschen schaden kann."],"correctIndex":0,"explanation":"Wissenschaftlich klingende Wörter beweisen nichts; entscheidend ist, ob eine Behauptung etwas Bestimmtes aussagt, das sich testen lässt. „Quantenheilung“ und „biologische Schwingung“ klingen nach Physik, ohne eine nachprüfbare Bedeutung zu haben, und der Verweis auf „Ganzheitlichkeit“ verlegt den Anspruch dorthin, wo ihn angeblich keine Prüfung erreicht. Die Rückfrage nach Bedeutung und Prüfbarkeit deckt genau das auf. Stichprobe und Kontrollgruppe sind sinnvolle Kriterien, setzen aber Studien voraus, und die werden hier gar nicht genannt. Eine Qualifikation sagt etwas über die Person, nicht darüber, ob die Behauptung überhaupt prüfbar ist. Die Abwägung von Nutzen und Risiko beantwortet eine andere Frage als die nach der Stichhaltigkeit.","coreRule":"⚡ Klingt eine Behauptung wissenschaftlich und beruft sich auf „Ganzheitlichkeit“, frag zuerst nach Bedeutung und Prüfbarkeit, bevor du Belege würdigst.","beleg":"Werkstück F.1.1 (Checkliste Punkte 8 und 9)","status":"entwurf","scenario":"Ein Seminar verspricht „Quantenheilung durch biologische Schwingung“. Auf Nachfrage heißt es, das sei „ganzheitlicher“, als es die „reduktionistische“ Wissenschaft je erfassen könne. Studien oder Messwerte werden nicht genannt.","kurz":"Wissenschaftlich klingende Wörter beweisen nichts; es zählt, ob die Behauptung etwas Bestimmtes aussagt, das sich testen lässt. Die Rückfrage nach Bedeutung und Prüfbarkeit zeigt, dass „Quantenheilung“ und „Ganzheitlichkeit“ genau dem Test ausweichen.","prueffrage":"Was genau soll bei Teilnehmenden nach dem Seminar anders sein als vorher?","rueckmeldung":[{"option":1,"text":"Stichprobengröße und Vergleichsgruppe sind gute Kriterien, wenn es Studien gibt. Das Seminar nennt aber keine, daher läuft die Prüfung ins Leere; zuerst muss klar sein, was überhaupt behauptet wird und testbar wäre."},{"option":2,"text":"Ein anerkannter Abschluss spricht meist für Fachkompetenz. Er sagt aber etwas über die Person und nicht darüber, ob die Behauptung eine prüfbare Bedeutung hat; dafür müsste man an der Aussage selbst ansetzen."},{"option":3,"text":"Nutzen und Risiko abzuwägen ist bei Heilversprechen sinnvoll, schon weil die Teilnahme schaden kann. Gefragt war aber, ob das Versprechen stichhaltig ist, und das beantwortet die Abwägung nicht."}],"familie":"wissenschaft-abgrenzen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","seite":"Einträge „Appeal to Ignorance“, „Misplaced Burden of Proof“","abruf":"2026-10-12"},{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: „Science and Pseudo-Science“","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschn. 4.3, 5.1","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"c755847ca27ee25f"}},{"id":"qx-f-009","clusterId":"F","werkstueckRef":"F.1.2","stufe":1,"question":"Ein Sportler trägt seit Jahren vor jedem Spiel seine Glückssocken, obwohl er weiß, dass sie nichts bewirken. Ein Kollege fragt ihn: „Warum machst du das dann?“ Welche Antwort ist die sinnvollste Erklärung für sein Verhalten?","options":["Das Ritual kann bestehen bleiben, weil ein Bestätigungsfehler ihn Siege mit den Socken behalten und Niederlagen übersehen lässt.","Das Ritual kann seine Anspannung dämpfen und ihm ein Gefühl von Kontrolle geben, auch wenn offen bleibt, ob er dadurch besser spielt.","Das Ritual kann bestehen bleiben, weil der Sunk-Cost-Effekt ihn drängt, nach all den Jahren nicht aufzugeben, was er investiert hat.","Das Ritual kann bestehen bleiben, weil eine selbsterfüllende Prophezeiung ihn tatsächlich besser spielen lässt, sobald er die Socken trägt."],"correctIndex":1,"explanation":"Wer sich einer Situation mit unsicherem Ausgang gegenübersieht, kann durch ein Ritual das Gefühl gewinnen, den Ausgang irgendwie zu beeinflussen. Dieses Gefühl von Kontrolle kann Angst dämpfen, auch wenn der Sportler rational weiß, dass die Socken nichts bewirken. Ein Feldexperiment mit religiösen Tempelritualen (Lang, Krátký und Xygalatas, 2020) deutet auf weniger berichtete Angst und weniger körperliche Anspannung nach einer Stressaufgabe hin (nach Angabe der Autoren erste, nicht laborgenau kontrollierte Belege); ob dasselbe für private Glücksrituale gilt, ist damit nicht gezeigt. Ob ein solches Ritual die Leistung wirklich verbessert, bleibt offen: Ein vielzitierter Leistungsbefund ließ sich in größeren Wiederholungen nicht bestätigen. Ein Bestätigungsfehler setzt voraus, dass er Siege den Socken zuschreibt, doch er weiß, dass sie nichts bewirken. Der Sunk-Cost-Effekt braucht einen echten Aufwand, der verloren ginge, und das Anziehen der Socken kostet kaum etwas. Eine selbsterfüllende Prophezeiung entsteht nur, wenn er auf ihre Wirkung vertraut.","coreRule":"⚡ Ein Ritual kann beruhigen, ohne das Ergebnis zu beeinflussen: Trenne das Gefühl von Kontrolle von der tatsächlichen Wirkung.","beleg":"Werkstück F.1.2 (Kontext & Tiefe; Fn. gl-f-ritual-angst: Lang, Krátký, Xygalatas 2020, Abschn. 3 und 4)","status":"entwurf","scenario":"","kurz":"Ein Ritual kann Anspannung dämpfen und das Gefühl geben, etwas beeinflussen zu können, auch ohne Glauben an seine Wirkung. Der naheliegende Fehler: nach einem Wahrnehmungs- oder Glaubensfehler zu suchen, obwohl er weiß, dass die Socken nichts bewirken.","prueffrage":"Was ließe sich beim Sportler vor einem Spiel mit und ohne Socken tatsächlich beobachten oder messen?","rueckmeldung":[{"option":0,"text":"Rituale können sich tatsächlich durch selektive Wahrnehmung halten. Hier fehlt aber die Voraussetzung: Der Sportler weiß, dass die Socken nichts bewirken, und führt Siege deshalb gar nicht auf sie zurück."},{"option":2,"text":"Wer viel investiert hat, hält oft zu lange an etwas fest. Das Anziehen von Socken kostet aber kaum etwas, sodass auch nichts verloren ginge, wenn er das Ritual ließe. Das Szenario nennt keinen solchen Aufwand."},{"option":3,"text":"Selbsterfüllende Prophezeiungen gibt es wirklich, sie brauchen aber Vertrauen in die Wirkung. Der Sportler glaubt nicht daran. Ob solche Rituale die Leistung heben, ist zudem offen und nicht gesichert."}],"familie":"was-waere-ohne","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Lang, M.; Krátký, J.; Xygalatas, D. (2020): „The role of ritual behaviour in anxiety reduction“, Philosophical Transactions of the Royal Society B 375(1805)","oeffentlich":true,"doi":"10.1098/rstb.2019.0431","abruf":"2026-10-12"},{"typ":"doi","kurz":"Calin-Jageman, R. J.; Caldwell, T. L. (2014): „Replication of the Superstition and Performance Study by Damisch, Stoberock, and Mussweiler (2010)“, Social Psychology 45(3)","oeffentlich":false,"doi":"10.1027/1864-9335/a000190"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"869b405a63fd2f2c"}},{"id":"qx-f-010","clusterId":"F","werkstueckRef":"F.1.2","stufe":2,"question":"Was ist an dieser Deutung das eigentliche Problem?","scenario":"Dein Kollege trägt zur Prüfung immer dieselbe Glückskette. Besteht er, sagt er: „Siehst du, sie wirkt.“ Fällt er durch, sagt er: „Ich habe sie zu spät angezogen.“","options":["Er stützt sich nur auf wenige Prüfungen mit der Kette; so kann der Zufall eine Wirkung vortäuschen, die es nicht gibt.","Er zählt nur die bestandenen Prüfungen und lässt die durchgefallenen weg; so gehen nur Erfolge in seine Bilanz ein.","Er verlässt sich auf Berichte anderer über die Kette statt auf eigene Erfahrung; so trägt bloßes Hörensagen sein Urteil.","Er wertet Erfolg als Beweis für die Kette und Misserfolg als eigenen Fehler; so kann nichts die Kette widerlegen."],"correctIndex":3,"explanation":"Entscheidend ist die ungleiche Auswertung: Ein Treffer bestätigt das Ritual, ein Fehlschlag wird dem Anwender angelastet. Damit gibt es kein denkbares Ergebnis, das gegen die Kette sprechen würde, die Behauptung ist nicht widerlegbar und sagt deshalb auch nichts aus. Ob ein Ritual wirkt, ließe sich nur in einem kontrollierten Vergleich mit und ohne Ritual prüfen. Wenige Prüfungen lassen dem Zufall Raum, doch auch viele Durchgänge änderten nichts, solange jedes Ergebnis in dieselbe Richtung gedeutet wird. Dass er nur Erfolge zählt, trifft nicht zu, denn er deutet die durchgefallenen Prüfungen ja ebenfalls, nur einseitig. Und er beruft sich auf sein eigenes Erleben, nicht auf Berichte anderer.","coreRule":"⚡ Wenn nur Erfolge dem Ritual zählen und Misserfolge dem Menschen, ist das Ritual immun gegen Widerlegung.","beleg":"Werkstück F.1.2 (Red Flags: asymmetrische Erklärung; Der Kipppunkt)","status":"entwurf","kurz":"Wenn jeder Erfolg die Kette bestätigt und jeder Misserfolg auf eigenes Versagen zurückgeht, kann kein Ergebnis gegen sie sprechen. Eine Behauptung, die nicht widerlegbar ist, sagt deshalb nichts aus.","prueffrage":"Was würde sich an seiner Deutung ändern, wenn er die Kette noch zwanzig weitere Prüfungen lang trägt?","rueckmeldung":[{"option":0,"text":"Wenige Prüfungen lassen dem Zufall tatsächlich viel Raum. Doch auch viele Durchgänge änderten nichts, solange jedes Ergebnis in dieselbe Richtung gedeutet wird. Das Problem liegt in der Auswertung, nicht in der Menge."},{"option":1,"text":"Dass nur Erfolge zählen, wirkt plausibel, trifft hier aber nicht zu: Er lässt die durchgefallenen Prüfungen nicht weg, sondern deutet sie, nur zu seinen Gunsten. Die einseitige Deutung ist das Problem, nicht eine lückenhafte Zählung."},{"option":2,"text":"Hörensagen wäre eine schwache Grundlage, doch hier passt es nicht: Er trägt die Kette selbst und beruft sich auf sein eigenes Erleben. Wie er dieses Erleben deutet, ist das Problem, nicht woher es stammt."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Skinner, B. F. (1948): „'Superstition' in the Pigeon“, Journal of Experimental Psychology 38 (Nachdruck Classics in the History of Psychology)","oeffentlich":true,"url":"https://psychclassics.yorku.ca/Skinner/Pigeon/","abruf":"2026-10-12"},{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: „Science and Pseudo-Science“","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschn. 4.3, 5.1","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"60c50d2a84ad19b3"}},{"id":"qx-f-011","clusterId":"F","werkstueckRef":"F.1.2","stufe":3,"question":"Bei welcher Person ist die Grenze vom harmlosen Ritual zum echten Problem überschritten?","options":["Ein Händler nimmt von zwei gleich guten Angeboten das mit seiner Glückszahl im Preis, prüft beide aber vorher gründlich.","Eine Torfrau zieht vor jedem Spiel zuerst den linken Handschuh an, weil es sie beruhigt, und trainiert sonst wie geplant.","Eine Unternehmerin sagt eine gut vorbereitete Geschäftsentscheidung ab, weil ihr Tageshoroskop davon abrät.","Eine Familie verlegt ihren Ausflug vom Freitag, dem 13., auf den Samstag, obwohl beide Tage gleich gut passen."],"correctIndex":2,"explanation":"Ein Aberglaube ist dann ein Problem, wenn er echte, kostspielige Entscheidungen steuert, wenn er zwanghaft wird, wenn er wirksames Handeln ersetzt oder wenn er bei Misserfolg zu Selbstvorwürfen führt. Ein Horoskop, das darüber entscheidet, ob eine wichtige Geschäftsentscheidung fällt, hat mit dem Erfolg des Geschäfts nichts zu tun, kann aber viel Geld kosten. Die anderen drei Rituale sind klein und werden bewusst gehandhabt. Die Glückszahl entscheidet beim Händler nur zwischen zwei Angeboten, die er vorher geprüft hat und die gleich gut sind. Der Handschuh beruhigt die Torfrau und ersetzt keine Vorbereitung. Die Verlegung des Ausflugs kostet die Familie nichts, weil beide Tage gleich gut passen.","coreRule":"⚡ Harmlos ist das Ritual, das beruhigt; gefährlich wird es, wenn es Entscheidungen steuert.","beleg":"Werkstück F.1.2 (Der Kipppunkt, Punkt 1 bis 4)","status":"entwurf","scenario":"Vier Personen pflegen jeweils einen kleinen Aberglauben. Alle vier wissen, dass ihr Ritual keine nachweisbare Wirkung hat; es geht darum, was das Ritual im Alltag tatsächlich anrichtet.","kurz":"Entscheidend ist, was das Ritual kostet. Das Horoskop hat mit dem Erfolg des Geschäfts nichts zu tun, bestimmt aber, ob eine gut vorbereitete Entscheidung fällt. Bei den anderen entscheidet es nichts, was nicht ohnehin offen oder gleichwertig wäre.","prueffrage":"Welche der vier Personen ändert wegen ihres Rituals überhaupt etwas an einer Entscheidung?","rueckmeldung":[{"option":0,"text":"Eine Glückszahl im Preis wirkt wie ein Eingriff in eine Geldentscheidung. Doch der Händler hat beide Angebote geprüft, sie sind gleich gut, und das Ritual gibt nur den Ausschlag, wo ohnehin nichts zu verlieren ist."},{"option":1,"text":"Ein Ritual vor jedem Spiel kann nach Zwang aussehen. Hier beruhigt es nur, und die Torfrau trainiert sonst wie geplant. Es ersetzt also keine Vorbereitung und verdrängt nichts Wirksames."},{"option":3,"text":"Der Freitag, der 13., gilt als Unglückstag, und seinetwegen wird ein Plan geändert. Das ist aber nur eine Terminwahl: Beide Tage passen gleich gut, die Familie verliert dadurch weder Geld noch Chancen."}],"familie":"ergaenzen-oder-ersetzen","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Lang, M.; Krátký, J.; Xygalatas, D. (2020): „The role of ritual behaviour in anxiety reduction“, Philosophical Transactions of the Royal Society B 375(1805)","oeffentlich":true,"doi":"10.1098/rstb.2019.0431","abruf":"2026-10-12"},{"typ":"doi","kurz":"Carlson, S. (1985): „A double-blind test of astrology“, Nature 318","oeffentlich":false,"doi":"10.1038/318419a0"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"487015e754bb8579"}},{"id":"qx-f-012","clusterId":"F","werkstueckRef":"F.1.2","stufe":4,"question":"Eine Freundin zündet eine Kerze an, um „Reichtum anzuziehen“, und bekommt drei Wochen später eine Gehaltserhöhung. Sie sagt: „Siehst du, es hat funktioniert!“ Warum ist das noch kein Beleg dafür, dass die Kerze gewirkt hat?","options":["Dass etwas danach geschah, zeigt nicht, dass es deswegen geschah; erst der Vergleich mit und ohne Kerze würde eine Wirkung zeigen.","Ursache und Wirkung sind vertauscht; die Gehaltserhöhung hat die Freundin erst dazu gebracht, die Kerze anzuzünden.","Sie erinnert sich vor allem an erfolgreiche Kerzenrituale und vergisst die übrigen; so entsteht ein Überlebensfehler.","Sie überschätzt, wie oft Gehaltserhöhungen vorkommen, weil ihr der lebhafte Einzelfall deutlicher vor Augen steht als der Alltag."],"correctIndex":0,"explanation":"Die Kerze steht vor der Gehaltserhöhung, aber zeitliche Abfolge ist keine Ursache. Das ist der Fehlschluss „danach, also deswegen“. Es gibt keine plausible Verbindung zwischen einer brennenden Kerze und dem Gehalt, und ein einzelner Treffer ist mit Zufall bestens erklärbar: Gehaltserhöhungen kommen auch ohne Kerzen vor. Erst ein Vergleich würde zeigen, ob Menschen mit Kerze häufiger eine Erhöhung bekommen als Menschen ohne. Eine Umkehrung von Ursache und Wirkung scheidet aus, weil die Kerze drei Wochen vor der Erhöhung brannte. Von weiteren Kerzenritualen, die sie vergessen hätte, ist keine Rede; es geht um einen einzelnen Fall. Und wie häufig Gehaltserhöhungen sind, ist nicht der Punkt, sondern ob die Kerze überhaupt etwas dazu beiträgt.","coreRule":"⚡ Wer von „danach“ auf „deswegen“ schließt, braucht einen Vergleich mit und ohne die vermutete Ursache; die bloße Reihenfolge reicht nie.","beleg":"Werkstück F.1.2 (Kontext & Tiefe: Post hoc; Anwendung & Relevanz: In der Esoterik & New Age)","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Die Kerze brannte vor der Erhöhung, doch „danach“ heißt nicht „deswegen“. Erhöhungen kommen auch ohne Kerzen vor, ein Treffer lässt sich mit Zufall erklären. Erst der Vergleich von Menschen mit und ohne Kerze zeigt, ob sie etwas bewirkt.","prueffrage":"Was ist in den drei Wochen zwischen Kerze und Gehaltserhöhung sonst noch geschehen, etwa bei ihrer Arbeit oder im Betrieb?","rueckmeldung":[{"option":1,"text":"Eine mögliche Vertauschung von Ursache und Wirkung ist bei Zusammenhängen immer einen Blick wert. Hier ist die Reihenfolge aber klar: Die Kerze brannte drei Wochen vor der Erhöhung, also kann die Erhöhung sie nicht ausgelöst haben."},{"option":2,"text":"Selektive Erinnerung gibt es tatsächlich, nur steht im Szenario nichts von weiteren, vergessenen Ritualen. Es geht um einen einzelnen Fall, und dessen Aussagekraft ist das Problem, nicht eine verzerrte Erinnerung."},{"option":3,"text":"Daran stimmt, dass Erhöhungen auch ohne Kerzen vorkommen. Doch ob die Freundin ihre Häufigkeit über- oder unterschätzt, ist nicht der Punkt. Offen bleibt, ob die Kerze überhaupt etwas zur Erhöhung beiträgt."}],"familie":"was-waere-ohne","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","seite":"Eintrag „Post Hoc“","abruf":"2026-10-12"},{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: „Science and Pseudo-Science“","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschn. 4.3, 5.1","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"66619d676c62a521"}},{"id":"qx-f-013","clusterId":"F","werkstueckRef":"F.1.3","stufe":1,"question":"Ein Online-Beitrag behauptet: „Eine geheime Elite steuert seit Jahrzehnten die Weltpolitik, ohne dass je ein Mitwisser geplaudert hat. Dass sie ständig verräterische Symbole in Filmen und Logos versteckt, beweist: Sie ist so sicher, dass sie sich nicht verstecken muss.“ Welcher Widerspruch macht diese Erzählung unglaubwürdig?","options":["Dieselbe Gruppe soll so umsichtig sein, dass sie ein Geheimnis jahrzehntelang perfekt wahrt, und so nachlässig, dass jeder Hobbydetektiv ihre Spuren findet.","Dieselbe Gruppe soll im Verborgenen sehr klein sein und zugleich in ihrer Wirkung weltumspannend, obwohl kleine Gruppen immer nur lokal wirken können.","Dieselbe Gruppe soll böswillig handeln und trotzdem von ihren Opfern ausdrücklich gelobt werden, weil sie deren Interessen vertritt.","Dieselbe Gruppe soll allmächtig sein und wird dennoch von den Verfassern der Erzählung nicht ernsthaft bekämpft, sondern nur beschrieben."],"correctIndex":0,"explanation":"Die Erzählung braucht einen Feind, der zwei Dinge zugleich sein muss: übermenschlich kompetent (er hält eine globale Verschwörung jahrzehntelang geheim) und unfassbar dumm (er hinterlässt „Hinweise“, die jeder YouTube-Detektiv finden kann). Beides gleichzeitig ist kaum plausibel. Wenn eine Erklärung nur funktioniert, indem sie ihrem Feind widersprüchliche Eigenschaften zuschreibt, ist das ein Warnsignal.","coreRule":"⚡ Allmächtig und doch schlampig: Wenn der Feind beides zugleich sein muss, trägt die Erzählung nicht.","beleg":"Werkstück F.1.3 (Kontext & Tiefe, Anatomie, Punkt 1: Ein allmächtiger, böswilliger Feind)","status":"entwurf","scenario":"","kurz":"Die Gruppe soll zugleich so perfekt sein, dass nie jemand plaudert, und so nachlässig, dass jeder ihre Symbole findet. Wenn ein Feind widersprüchliche Eigenschaften braucht, damit die Erzählung aufgeht, ist das ein Warnsignal.","prueffrage":"Wie erklärt der Beitrag, dass die angeblichen Symbole offen in Filmen und Logos zu sehen sind?","rueckmeldung":[{"option":1,"text":"Dass die Gruppe klein, aber weltumspannend wirken soll, hat man oft bei solchen Erzählungen im Ohr. Der Beitrag sagt über ihre Größe aber nichts, und kleine Gruppen können durchaus weit wirken. Der Widerspruch liegt woanders."},{"option":2,"text":"Ein Widerspruch zwischen Absicht und Wirkung klingt plausibel, doch von einem Lob durch die Opfer ist im Beitrag keine Rede. Die Unstimmigkeit steckt in den Eigenschaften, die der Gruppe selbst zugeschrieben werden."},{"option":3,"text":"Was die Verfasser selbst tun, sagt etwas über sie, aber nichts über die innere Stimmigkeit ihrer Behauptung. Der Widerspruch steckt in dem, was der Beitrag der Gruppe zuschreibt, nicht darin, wie die Verfasser auf sie reagieren."}],"familie":"verschwoerung-pruefen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Grimes, D. R. (2016): „On the Viability of Conspiratorial Beliefs“, PLOS ONE 11(1), e0147905","oeffentlich":true,"doi":"10.1371/journal.pone.0147905","abruf":"2026-10-12"},{"typ":"url","kurz":"Lewandowsky, S.; Cook, J. (2020): The Conspiracy Theory Handbook","oeffentlich":true,"url":"https://skepticalscience.com/docs/ConspiracyTheoryHandbook.pdf","seite":"Abschnitt CONSPIR, „Contradictory“","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"9543a874e86a7240"}},{"id":"qx-f-014","clusterId":"F","werkstueckRef":"F.1.3","stufe":2,"question":"Wie erklärst du am besten, dass dir die Saboteur-Geschichte verführerischer vorkommt, obwohl sie kaum belegt ist?","scenario":"In deinem Haus zeigen sich Risse in der Wand, und die Tür klemmt. Ein Gutachter nennt instabilen Baugrund: ein komplexes, teures Problem, das ein aufwendiges Stabilisieren des Fundaments verlangt. Dein Nachbar flüstert dagegen, eine geheime Immobilien-Lobby wolle das Viertel billig aufkaufen und schlage nachts mit dem Hammer gegen dein Fundament. Der klemmende Türrahmen sei der Beweis.","options":["Sie wurde als Erste genannt und setzt damit einen Anker; alle weiteren Erklärungen werden an ihr gemessen, obwohl sie nicht mehr Belege liefert.","Sie ist einfach und dramatisch und bietet einen Feind, gegen den man kämpfen kann; sie erfüllt das Bedürfnis nach Sinn und Kontrolle, ohne mehr Belege zu liefern.","Sie wird von vielen Menschen geteilt, und die Zustimmung der Gruppe wirkt wie ein Beleg (sozialer Beweis); man schließt sich der Mehrheit an, ohne selbst zu prüfen.","Sie stammt von einem Nachbarn, den du magst, und die Sympathie für den Überbringer färbt deine Bewertung der Aussage selbst, obwohl sie kaum Belege hat."],"correctIndex":1,"explanation":"Wie verführerisch eine Erklärung wirkt, sagt nichts darüber, wie gut sie belegt ist. Die Saboteur-Geschichte bietet einen klaren Bösewicht, einen einfachen Plan und das Gefühl, Bescheid zu wissen und handeln zu können. Die Erklärung des Gutachters ist dagegen kompliziert, beängstigend und teuer, obwohl sie die Risse und die klemmende Tür ebenfalls erklärt. Dass eine Geschichte emotional befriedigt, ist kein Beleg für ihre Wahrheit. Die Forschung zu Verschwörungsglauben zeigt außerdem: Er wird von Bedürfnissen nach Sinn, Kontrolle und Zugehörigkeit getrieben, erfüllt sie aber meist nicht. Ein Ankereffekt scheidet aus, weil der Gutachter seine Erklärung zuerst nannte. Sozialer Beweis setzt voraus, dass viele die Geschichte teilen, hier flüstert aber nur ein Nachbar. Ob du den Nachbarn magst, steht nirgends und erklärt nicht, warum gerade diese Geschichte so anziehend wirkt.","coreRule":"⚡ Eine Erklärung kann sich gut anfühlen und trotzdem schlecht belegt sein: Prüfe Belege, nicht den Gefühlswert.","beleg":"Werkstück F.1.3 (Das rissige Fundament; Kernidee; Anatomie, Punkt 2: Apophenie)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Wie anziehend eine Erklärung wirkt, sagt nichts über ihre Belege. Die Saboteur-Geschichte liefert einen Feind, einen einfachen Plan und das Gefühl, handeln zu können. Der Denkfehler: Befriedigung wird mit Wahrheit verwechselt.","prueffrage":"Was bietet die Geschichte des Nachbarn dem Hausbesitzer, das ihm das Gutachten nicht bietet?","rueckmeldung":[{"option":0,"text":"Wer zuerst etwas sagt, prägt oft die Maßstäbe. Hier war es aber umgekehrt: Der Gutachter nannte seine Erklärung zuerst, der Nachbar kam danach. Ein Anker kann die Anziehungskraft der Saboteur-Geschichte also nicht erklären."},{"option":2,"text":"Zustimmung der Mehrheit kann tatsächlich wie ein Beleg wirken. Dafür müssten aber viele die Geschichte teilen, und im Szenario flüstert nur ein einzelner Nachbar. Der Mechanismus ist real, passt hier aber nicht zur Lage."},{"option":3,"text":"Sympathie für den Überbringer kann die Bewertung einer Aussage durchaus färben. Im Szenario steht aber nirgends, dass du den Nachbarn magst. Und selbst dann bliebe offen, warum gerade diese Geschichte so anziehend wirkt."}],"familie":"verschwoerung-pruefen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Douglas, K. M.; Sutton, R. M.; Cichocka, A. (2017): „The Psychology of Conspiracy Theories“, Current Directions in Psychological Science 26(6)","oeffentlich":true,"doi":"10.1177/0963721417718261","abruf":"2026-10-12"},{"typ":"url","kurz":"Lewandowsky, S.; Cook, J. (2020): The Conspiracy Theory Handbook","oeffentlich":true,"url":"https://skepticalscience.com/docs/ConspiracyTheoryHandbook.pdf","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"2ad2fc8a83329c90"}},{"id":"qx-f-015","clusterId":"F","werkstueckRef":"F.1.3","stufe":3,"question":"Er sagt: „Seit ich die Verschwörung durchschaue, habe ich endlich Kontrolle in einer chaotischen Welt.“ Wie solltest du diese Aussage einordnen?","options":["Das Gefühl ist verständlich, denn Sinn und Kontrolle sind genau die Motive, die solchen Glauben antreiben. Dass er sie auch erfüllt, ist aber unbelegt; in Experimenten schwächte schon das Lesen solcher Erzählungen das Kontrollgefühl.","Das Gefühl ist verständlich, denn Sinn und Kontrolle sind genau die Motive, die solchen Glauben antreiben. Dass er sie auch erfüllt, gilt als gesichert; Anhänger berichten durchweg von mehr Kontrolle und Zuversicht als vorher.","Das Gefühl ist verständlich, denn Sinn und Kontrolle sind genau die Motive, die solchen Glauben antreiben. Erfüllt werden sie meist tatsächlich, nur das Bedürfnis nach Gemeinschaft bleibt offen, weil sich Anhänger zurückziehen.","Das Gefühl ist verständlich, denn Sinn und Kontrolle sind genau die Motive, die solchen Glauben antreiben. Ob der Glaube sie erfüllt, lässt sich nicht beurteilen, weil das bisher nie untersucht oder gemessen wurde."],"correctIndex":0,"explanation":"Es ist wichtig, zwei Fragen zu trennen: Warum glaubt jemand? Und: Bekommt er, was er sich davon verspricht? Die Forschung (Douglas, Sutton und Cichocka 2017) führt den Glauben auf epistemische, existenzielle und soziale Motive zurück, etwa das Bedürfnis nach Sinn, Kontrolle und Zugehörigkeit. Einen Beleg, dass der Glaube diese Bedürfnisse erfüllt, gibt es aber nicht. In Experimenten schwächte schon das Lesen von Verschwörungserzählungen das Gefühl von Kontrolle. Das Gefühl deines Freundes ist real, belegt aber nicht, dass die Erzählung ihm tatsächlich Kontrolle verschafft. Die Aussage „Es fühlt sich nach Kontrolle an“ ist etwas anderes als „Ich habe Kontrolle“.","coreRule":"⚡ Wer fragt, ob ein Glaube ein Bedürfnis erfüllt, darf das Versprechen nicht mit dem Befund verwechseln: Verschwörungsglaube verspricht Halt, löst ihn aber meist nicht ein.","beleg":"Werkstück F.1.3 (Das Adaptive Talent); Fn. gl-f-douglas (Douglas, Sutton, Cichocka 2017, S. 538 f.)","status":"entwurf","scenario":"Ein Freund beschäftigt sich seit Monaten mit einer Verschwörungserzählung. Du erinnerst dich an psychologische Experimente, in denen untersucht wurde, wie sich das Lesen von Verschwörungserzählungen auf das Gefühl von Kontrolle auswirkt.","kurz":"Warum jemand glaubt, und ob der Glaube ihm gibt, was er sucht, sind zwei verschiedene Fragen. Dass es sich nach Kontrolle anfühlt, belegt keine Kontrolle; in Experimenten schwächte schon das Lesen solcher Erzählungen das Kontrollgefühl.","prueffrage":"Wie ließe sich beobachten, ob sich sein Kontrollgefühl im Alltag tatsächlich verändert hat, seit er sich damit beschäftigt?","rueckmeldung":[{"option":1,"text":"Dass sich dein Freund sicherer fühlt, glaubt man ihm gern. Mit „durchweg“ und „gesichert“ geht die Aussage aber zu weit: Ein Beleg für mehr Kontrolle fehlt, und in Experimenten schwächte schon das Lesen solcher Erzählungen das Kontrollgefühl."},{"option":2,"text":"Der Hinweis auf Rückzug und fehlende Gemeinschaft wirkt wie eine ausgewogene Einschränkung. Doch schon die Annahme, Sinn und Kontrolle würden meist erfüllt, ist unbelegt: Das Kontrollgefühl sank in Experimenten schon beim Lesen solcher Erzählungen."},{"option":3,"text":"Vorsicht ist angebracht, denn dass der Glaube das Bedürfnis erfüllt, ist nicht belegt. „Nie untersucht“ stimmt aber nicht: Es gibt Experimente zu dieser Frage, und sie sprechen eher gegen einen Gewinn an Kontrolle."}],"familie":"wohlwollend-verstehen","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Douglas, K. M.; Sutton, R. M.; Cichocka, A. (2017): „The Psychology of Conspiracy Theories“, Current Directions in Psychological Science 26(6)","oeffentlich":true,"doi":"10.1177/0963721417718261","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"3d1b09d96d614097"}},{"id":"qx-f-016","clusterId":"F","werkstueckRef":"F.1.3","stufe":4,"question":"Welcher der beiden Beiträge gibt mehr Grund zur Sorge, und warum?","scenario":"Zwei Beiträge kursieren im Netz. Der erste scherzt, die Stadt Bielefeld existiere gar nicht und sei eine Erfindung. Der zweite behauptet, eine bestimmte Bevölkerungsgruppe steuere insgeheim die Wirtschaft und sei an Krisen schuld. Beide Beiträge bekommen viele Likes. Eine Freundin sagt: „Sind doch beides Verschwörungsgeschichten, also gleich harmlos oder gleich schlimm.“","options":["Beide sind gleich zu bewerten, weil beide ohne Beleg auftreten; für die Sorge zählt vor allem, wie gut sich Behauptungen belegen lassen.","Der erste Beitrag ist ernster, weil er eine leicht überprüfbare Tatsache bestreitet und damit die Wirklichkeit offen leugnen kann.","Der zweite Beitrag ist ernster, weil er mehr Zustimmung bekommt, und eine größere Reichweite kann mehr Menschen erreichen.","Der zweite Beitrag ist ernster, weil er reale Menschen zum Feind erklärt und damit Ausgrenzung und Gewalt den Boden bereiten kann."],"correctIndex":3,"explanation":"Beide Beiträge haben die Form einer Verschwörungserzählung: ein verborgener Plan, bei dem Zufall keine Rolle spielt. Den entscheidenden Unterschied macht das Ziel. Ein Scherz über eine Stadt, die es angeblich nicht gibt, bleibt ein Gedankenspiel, das niemandem schadet. Wird dagegen eine reale Gruppe von Menschen zum geheimen Drahtzieher erklärt, entsteht ein Feindbild, und aus Feindbildern können Ausgrenzung, Hass und im schlimmsten Fall Gewalt entstehen. Historisch zeigt das der Vorwurf der Brunnenvergiftung, mit dem 1348 beim Herannahen der Pest jüdische Gemeinden ermordet wurden, oder die gefälschten „Protokolle der Weisen von Zion“, die dem modernen Antisemitismus als angeblicher Beweis dienten. Dass beide ohne Beleg auftreten, haben sie gemeinsam; es trennt sie also nicht, entscheidend ist, wer als Feind benannt wird. Beide Beiträge bekommen viele Likes, sodass auch Zustimmung die Fälle nicht unterscheidet. Und der Bielefeld-Beitrag scherzt erkennbar, er leugnet keine Tatsache im Ernst.","coreRule":"⚡ Gefährlich wird ein Mythos dort, wo er reale Menschen zum Feind erklärt.","beleg":"Werkstück F.1.3 (Der Kipppunkt; Anwendung & Relevanz: Historische Verschwörungsmythen)","status":"entwurf","kurz":"Der zweite Beitrag erklärt reale Menschen zu geheimen Drahtziehern, und aus solchen Feindbildern können Ausgrenzung und Gewalt entstehen. Der Scherz über Bielefeld bleibt ein Gedankenspiel. Gleiche Form heißt also nicht gleiches Gewicht.","prueffrage":"Worin unterscheiden sich die beiden Beiträge bei den Likes, und worin bei dem, was sie behaupten?","rueckmeldung":[{"option":0,"text":"Dass beide ohne Beleg auftreten, stimmt. Gerade deshalb trennt es sie nicht: Beide haben diesen Mangel, und für die Sorge kommt es darauf an, wer als Feind benannt wird."},{"option":1,"text":"Die Existenz Bielefelds lässt sich leicht überprüfen. Der Beitrag scherzt aber erkennbar und leugnet nichts im Ernst. Überprüfbarkeit sagt außerdem noch nichts darüber, wem eine Behauptung schaden kann."},{"option":2,"text":"Mit dem zweiten Beitrag liegst du richtig, die Begründung trägt aber nicht: Beide bekommen viele Likes, Zustimmung unterscheidet sie also nicht. Entscheidend ist, wer als Feind benannt wird."}],"familie":"wir-und-die-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"United States Holocaust Memorial Museum, Holocaust Encyclopedia: „Protocols of the Elders of Zion“","oeffentlich":true,"url":"https://encyclopedia.ushmm.org/content/en/article/protocols-of-the-elders-of-zion","abruf":"2026-10-12"},{"typ":"url","kurz":"Cohn, S. K. (2007): „The Black Death and the Burning of Jews“, Past and Present 196 (Einleitung bei Medievalists.net)","oeffentlich":true,"url":"https://www.medievalists.net/2011/01/the-black-death-and-the-burning-of-jews/","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"3f1429841f3d1e68"}},{"id":"qx-f-017","clusterId":"F","werkstueckRef":"F.1.3.1","stufe":1,"question":"Was ist ein sinnvoller erster Schritt?","options":["Die Argumentationsstruktur prüfen: Wird fehlender Beleg als Beleg gewertet, wird die Beweislast umgekehrt und lässt sich überhaupt etwas denken, das die Behauptung widerlegen würde?","Zunächst jede einzelne Behauptung des Videos gründlich nachrecherchieren, denn ohne vollständige Faktenkenntnis ist keine Einschätzung der Erzählung möglich.","Herausfinden, wie viele Menschen das Video geteilt haben, denn eine große Verbreitung spricht für die Glaubwürdigkeit der Erzählung.","Nach Lücken in der offiziellen Darstellung des Ereignisses suchen, denn jede ungeklärte Stelle macht die alternative Erzählung wahrscheinlicher."],"correctIndex":0,"explanation":"Ob eine Erzählung trägt, zeigt sich oft schon an ihrer Bauweise, noch bevor du ein einziges Detail geprüft hast. Hier gibt es mehrere Alarmzeichen: Das Fehlen von Beweisen wird selbst als Beweis gewertet (Argument aus Unwissenheit), die Beweislast wird umgedreht, und die Erzählung ist unfalsifizierbar, weil jeder Gegenbeweis zur Vertuschung erklärt wird. Eine Behauptung, die durch nichts widerlegt werden kann, ist keine robuste Hypothese, sondern eine uneinnehmbare Festung. Deshalb ist es klüger, zuerst die Struktur zu prüfen, statt endlos die „Fakten“ zu recherchieren. Beliebtheit und Lücken in der offiziellen Darstellung sind keine tragfähigen Belege für die Erzählung.","coreRule":"⚡ Erst die Struktur prüfen, dann die Details: Wird fehlender Beweis als Beweis gewertet, die Beweislast umgekehrt und jeder Gegenbeweis eingemeindet, ist Vorsicht angebracht.","beleg":"Werkstück F.1.3.1 (Kernidee; Die 7 Warnsignale, Nr. 2–4; Werkbank-Frage)","status":"entwurf","scenario":"Eine Freundin schickt dir ein Video über ein Unglück. Es erklärt das chaotische Ereignis zum Werk einer kleinen, mächtigen Gruppe, verbindet viele Einzelheiten zu einer geraden Linie und spricht vor allem Angst und Wut an. Gegenargumente deutet es vorab als Teil der Vertuschung um, und es heißt: „Dass keine Beweise auftauchen, zeigt nur, wie perfekt sie alles vertuscht. Beweise du mir erst mal, dass es nicht stimmt.“ Du kannst die Einzelheiten nicht überprüfen.","kurz":"Schon die Bauweise verrät viel: Fehlende Beweise gelten als Beweis, die Beweislast ist umgedreht, und jeder Einwand wird zur Vertuschung erklärt. Eine so gebaute Behauptung lässt sich nie widerlegen und ist deshalb keine tragfähige Hypothese.","prueffrage":"Wie viele einzelne Behauptungen enthält das Video, und welche davon könntest du heute selbst nachprüfen?","rueckmeldung":[{"option":1,"text":"Nachrecherchieren klingt gründlich, bringt hier aber wenig: Eine Erzählung, die jeden Gegenbeweis zur Vertuschung erklärt, lässt sich mit Fakten kaum erledigen. Ihre Bauweise lässt sich zudem prüfen, bevor alle Einzelheiten bekannt sind."},{"option":2,"text":"Viele Teilungen wirken wie ein Qualitätssiegel, zeigen aber nur, dass der Inhalt Aufmerksamkeit erregt, gerade durch Angst und Wut. Verbreitung sagt nichts darüber, ob die Erzählung stimmt."},{"option":3,"text":"Offene Stellen in der offiziellen Darstellung sind bei chaotischen Ereignissen normal, weil Aufklärung Zeit braucht. Aus einer Lücke folgt nicht, dass die Gegenerzählung stimmt; das wäre dieselbe Schlussweise, mit der das Video selbst arbeitet."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Lewandowsky, S.; Cook, J. (2020): The Conspiracy Theory Handbook","oeffentlich":true,"url":"https://skepticalscience.com/docs/ConspiracyTheoryHandbook.pdf","seite":"Abschnitt CONSPIR","abruf":"2026-10-12"},{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","seite":"Einträge „Appeal to Ignorance“, „Misplaced Burden of Proof“","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"5be8b0cbbaa8ed9e"}},{"id":"qx-f-018","clusterId":"F","werkstueckRef":"F.1.3.1","stufe":2,"question":"In einem Online-Video heißt es: „Wer das noch nicht durchschaut hat, schläft noch. Du gehörst zu den wenigen, die endlich aufgewacht sind und hinter die Kulissen blicken.“ Welche Wirkung hat diese Rahmung auf das Denken des Publikums?","options":["Sie schmeichelt den Zuschauern mit einem Überlegenheitsgefühl; wer sich zu den „Wissenden“ zählt, ist für die Erzählung eingenommen.","Sie legt den Zuschauern die Beweislast auf; wer die Behauptung nicht widerlegen kann, soll sie vorläufig als wahr hinnehmen.","Sie erweckt den Eindruck, die meisten Menschen teilten diese Sicht; wer sich einer Mehrheit anschließen kann, prüft weniger genau.","Sie versetzt die Zuschauer in Angst und Wut über eine Bedrohung; wer sich bedroht fühlt, hinterfragt die Behauptungen nicht mehr."],"correctIndex":0,"explanation":"Die Einteilung in „Erwachte“ und „Schlafschafe“ befriedigt das Bedürfnis nach Überlegenheit: Wer sich zu den Wissenden zählt, fühlt sich den anderen überlegen und wird für die Erzählung eingenommen. Beweislastumkehr, Mitläufereffekt und Gefühlsappell kommen in Verschwörungserzählungen häufig vor, passen aber nicht zu diesem Satz. Er verlangt keinen Gegenbeweis und droht mit nichts. Er nennt „die wenigen“ und beruft sich damit gerade nicht auf eine Mehrheit, sondern schmeichelt dem Selbstbild des Publikums.","coreRule":"⚡ Wo die Welt in Erwachte und Schlafende zerfällt, wirkt das Überlegenheitsgefühl als Bindemittel und ersetzt die Prüfung durch Zugehörigkeit.","beleg":"Werkstück F.1.3.1 (Die 7 Warnsignale, Punkt 7)","status":"entwurf","scenario":"","kurz":"Die Einteilung in „Erwachte“ und „Schlafende“ schmeichelt: Wer sich zu den Wenigen zählt, die hinter die Kulissen blicken, fühlt sich überlegen und ist für die Erzählung eingenommen. Gegenbeweis oder Drohung verlangt der Satz dabei gar nicht.","prueffrage":"Wen teilt der Satz in welche zwei Gruppen ein, und zu welcher soll sich das Publikum zählen?","rueckmeldung":[{"option":1,"text":"Beweislastumkehr tritt in Verschwörungserzählungen oft auf. Hier verlangt der Satz aber gar keinen Gegenbeweis; er benennt keine Behauptung, die man widerlegen müsste, sondern teilt das Publikum in Wissende und Schlafende ein."},{"option":2,"text":"Dass die Zustimmung einer Mehrheit weniger genau prüfen lässt, stimmt als Mechanismus. Der Satz beruft sich aber auf „die wenigen“, die aufgewacht sind, also gerade nicht auf eine Mehrheit, sondern auf eine Auswahl, zu der man sich zählen darf."},{"option":3,"text":"Angst und Wut sind in Verschwörungserzählungen ein häufiges Mittel. In diesem Satz fehlt aber jede Bedrohung; er benennt keine Gefahr, sondern wertet das Selbstbild der Zuschauer auf."}],"familie":"wir-und-die-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Lewandowsky, S.; Cook, J. (2020): The Conspiracy Theory Handbook","oeffentlich":true,"url":"https://skepticalscience.com/docs/ConspiracyTheoryHandbook.pdf","seite":"Abschnitt CONSPIR, „Persecuted victim“","abruf":"2026-10-12"},{"typ":"doi","kurz":"Douglas, K. M.; Sutton, R. M.; Cichocka, A. (2017): „The Psychology of Conspiracy Theories“, Current Directions in Psychological Science 26(6)","oeffentlich":true,"doi":"10.1177/0963721417718261","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"e52b08cda4abe72d"}},{"id":"qx-f-019","clusterId":"F","werkstueckRef":"F.1.3.1","stufe":3,"question":"Wie antwortest du deinem Freund?","options":["Misstrauen kann nützlich sein, solange es sich durch Belege korrigieren lässt; problematisch wird es erst, wenn jeder Gegenbeweis als Teil der Verschwörung umgedeutet wird.","Misstrauen gegenüber Autoritäten ist an sich schon ein Warnsignal; wer Behörden vertraut, ist auf der sicheren Seite und muss nichts mehr prüfen.","Misstrauen ist nur dann nützlich, wenn es sich gegen Medien richtet; Kritik an Behörden oder Wissenschaft gilt dagegen immer als bedenklich.","Jede Kritik an Institutionen führt unweigerlich in einen geschlossenen Denkkreis; deshalb ist es sicherer, grundsätzlich auf Misstrauen zu verzichten."],"correctIndex":0,"explanation":"Entscheidend ist nicht, ob jemand misstraut, sondern was aus dem Misstrauen wird. Ein gesundes Misstrauen gegenüber Autoritäten ist nützlich. Der Kipppunkt ist erreicht, wenn es zu einem geschlossenen Weltbild wird, das keinen Gegenbeweis mehr zulässt: Jeder Widerspruch gilt dann als Teil der Verschwörung. Ein zweites Kriterium kommt hinzu: wenn der Glaube an die Verschwörung wichtiger wird als persönliche Beziehungen und die eigene Sicherheit. Die Antwort „Misstrauen ist per se verdächtig“ verwechselt das Merkmal mit dem Muster und verlangt blindes Vertrauen statt Prüfung.","coreRule":"⚡ Misstrauen darf prüfen; es darf nur nicht jeden Gegenbeweis ausschließen.","beleg":"Werkstück F.1.3.1 (Der Kipppunkt)","status":"entwurf","scenario":"Ein Freund sagt: „Wer Behörden und Institutionen misstraut, steckt doch schon halb im Kaninchenbau. Misstrauen gegenüber Autoritäten ist an sich verdächtig.“ Du kennst Fälle, in denen Skepsis gegenüber Behörden berechtigt war, weil sich Angaben später als falsch herausstellten.","kurz":"Entscheidend ist, was aus dem Misstrauen wird: Es bleibt nützlich, solange Belege es korrigieren können. Der Denkfehler ist, schon das Misstrauen selbst zu verdächtigen, statt auf das Muster zu achten, dass kein Gegenbeweis mehr zählt.","prueffrage":"Wie hätte man in den Fällen, in denen Behördenangaben falsch waren, ohne Misstrauen davon erfahren?","rueckmeldung":[{"option":1,"text":"Dass Misstrauen kippen kann, stimmt. Verdächtig ist aber nicht das Misstrauen selbst, sondern erst ein Muster, in dem kein Gegenbeweis mehr zählt. Und wer nur vertraut, ersetzt Prüfung durch Hoffnung, wie die später widerlegten Angaben zeigen."},{"option":2,"text":"Auch Medien dürfen kritisch geprüft werden, doch eine Trennlinie nach Adressat trägt nicht: Berechtigte Skepsis gab es gerade gegenüber Behörden. Ob Misstrauen gesund ist, hängt davon ab, ob Belege es korrigieren können, nicht davon, wem es gilt."},{"option":3,"text":"Ein geschlossener Denkkreis ist eine echte Gefahr, aber kein unvermeidliches Ziel jeder Kritik. Gesundes Misstrauen bleibt für Belege offen. Wer ganz darauf verzichtet, ist nicht sicherer, sondern vertraut blind, wo Prüfung nötig wäre."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Lewandowsky, S.; Cook, J. (2020): The Conspiracy Theory Handbook","oeffentlich":true,"url":"https://skepticalscience.com/docs/ConspiracyTheoryHandbook.pdf","seite":"Kasten „Conventional vs. Conspiratorial Thinking“; Abschnitt CONSPIR","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"34a43fbac53aed5e"}},{"id":"qx-f-020","clusterId":"F","werkstueckRef":"F.1.3.1","stufe":4,"question":"Welche Antwort wird der Lage am besten gerecht?","scenario":"Ein Bekannter erzählt dir, seine Schwägerin sei „komplett paranoid“, nur weil sie eine bekannte Online-Verschwörungserzählung glaubt. Du hast die Erzählung mit einer Liste typischer Warnsignale geprüft (allmächtiger Feind, Beweislastumkehr, Unfalsifizierbarkeit und weitere) und festgestellt, dass sie mehrere davon erfüllt.","options":["Die Erzählung erfüllt mehrere Warnsignale, aber das ist ein Befund über die Erzählung und ihren Denkstil, nicht über den seelischen Gesundheitszustand der Schwägerin.","Die Warnsignale zeigen nur, dass die Erzählung schlecht prüfbar gebaut ist; ob sie stimmt, entscheidet sich erst, wenn man ihre einzelnen Behauptungen an Quellen überprüft.","Die Warnsignale zeigen, dass die Schwägerin die Erzählung nicht kritisch geprüft hat, denn wer mehrere Warnsignale übersieht, hat sich mit der Erzählung kaum befasst.","Die Herkunft einer Erzählung gehört ebenfalls zu den Prüfpunkten; deshalb solltest du als Nächstes klären, wer sie verbreitet und ob er Belege vorlegt."],"correctIndex":0,"explanation":"Die Warnsignale (allmächtiger Feind, Beweislastumkehr, Unfalsifizierbarkeit und ähnliche) beschreiben Eigenschaften einer Erzählung: Wie ist sie gebaut, und lässt sie sich überhaupt prüfen? Daraus folgt nichts über den Gesundheitszustand eines Menschen, der sie glaubt. Auch die Fachwelt trennt hier: Psychiater müssen Überzeugungen aus Verschwörungserzählungen erst von Wahn und wahnähnlichen Überzeugungen unterscheiden (Holoyda 2022, Journal of the American Academy of Psychiatry and the Law); meist ist Verschwörungsglaube ein Denkstil und kein Wahn, und ob im Einzelfall mehr dahintersteckt, kann nur eine fachliche Untersuchung klären. Wer aus „glaubt eine unbelegbare Geschichte“ auf „ist krank“ schließt, springt von einer Eigenschaft der Erzählung auf eine Eigenschaft der Person und etikettiert, statt zu prüfen. Ob eine Erzählung stimmt, klärt erst die Prüfung ihrer einzelnen Behauptungen, doch der Bekannte urteilt über die Schwägerin und nicht über den Wahrheitsgehalt. Aus der Zahl der Warnsignale folgt auch nicht, dass die Schwägerin sie übersehen hätte, denn sie kann sie gekannt und anders gewichtet haben. Und die Herkunft der Erzählung zu klären ist ein guter weiterer Prüfschritt, beantwortet aber nicht, ob das Etikett „paranoid“ berechtigt ist.","coreRule":"⚡ Wir sezieren die Erzählung und ihren Denkstil, wir stellen keine Diagnosen über Menschen.","beleg":"Werkstück F.1.3.1 (Der Kipppunkt); Fn. gl-f-wahn (Holoyda 2022, JAAPL 50(1), S. 124--135)","status":"entwurf","kurz":"Die Warnsignale beschreiben, wie die Erzählung gebaut ist und ob sie sich prüfen lässt, nicht, ob ihre Anhängerin seelisch gesund ist. Wer von „glaubt Unbelegbares“ auf „ist krank“ schließt, springt von der Erzählung auf die Person.","prueffrage":"Was weißt du über die Schwägerin außer der Tatsache, dass sie diese Erzählung glaubt?","rueckmeldung":[{"option":1,"text":"Das ist richtig: Ob eine Erzählung stimmt, zeigt erst die Prüfung ihrer Behauptungen. Der Bekannte urteilt aber gar nicht über den Wahrheitsgehalt, sondern über die Schwägerin, und genau diese Frage lässt die Antwort offen."},{"option":2,"text":"Viele Warnsignale legen nahe, dass jemand nicht genau hingesehen hat. Das lässt sich aber nicht daraus schließen: Die Schwägerin kann sie gekannt und anders gewichtet haben. Auch das wäre ein Urteil über die Person, das die Warnsignale nicht tragen."},{"option":3,"text":"Die Herkunft einer Erzählung zu klären ist tatsächlich ein sinnvoller weiterer Prüfschritt. Er sagt aber nichts darüber, ob das Wort „paranoid“ für die Schwägerin berechtigt ist, und beantwortet damit nicht die gestellte Frage."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Holoyda, B. J. (2022): „The QAnon Conspiracy Theory and the Assessment of Its Believers“, Journal of the American Academy of Psychiatry and the Law 50(1)","oeffentlich":true,"url":"https://jaapl.org/content/50/1/124","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"850854f439dc6475"}},{"id":"qx-f-021","clusterId":"F","werkstueckRef":"F.1.4","stufe":1,"question":"Ein Freund nennt eine Gruppe einen Kult, weil sie an Engel glaubt. Woran würdest du stattdessen prüfen, ob die Gruppe ihre Mitglieder manipulativ kontrolliert?","options":["Daran, wie die Gruppe mit ihren Mitgliedern umgeht, denn dort zeigt sich, ob sie deren Kontakte, Informationen, Denken und Gefühle steuert.","Daran, ob sich die Glaubenslehre der Gruppe durch Belege stützen lässt, denn das zeigt, ob ihre Aussagen über die Welt zutreffen oder nicht.","Daran, wie viele Mitglieder die Gruppe hat und wie lange es sie schon gibt, denn das zeigt, wie verbreitet und etabliert sie ist.","Daran, woher die Rituale der Gruppe geschichtlich stammen, denn das zeigt, ob ihre Bräuche auf alte Überlieferungen zurückgehen."],"correctIndex":0,"explanation":"Ob eine Gruppe ihre Mitglieder manipulativ kontrolliert, zeigt sich nicht an dem, was sie glaubt, sondern an dem, was sie mit ihren Mitgliedern macht. Geprüft werden Struktur und Verhalten: Wird bestimmt, mit wem man Umgang haben darf? Werden kritische Informationen abgeschnitten? Wird Zweifel bestraft? Werden Angst und Schuld als Druckmittel eingesetzt? Der Glaube an Engel sagt darüber nichts, denn auch viele unbedenkliche Gemeinschaften glauben Dinge, die sich nicht belegen lassen. Und selbst wenn einzelne Merkmale zutreffen, ist nicht jede enge Gemeinschaft ein Kult: Je mehr Kontrollmerkmale in hoher Intensität zusammenkommen, desto eher ist der Einfluss manipulativ. Ob sich eine Lehre belegen lässt, beantwortet die Frage, ob sie stimmt, nicht aber die Frage nach Kontrolle. Größe und Alter zeigen, wie etabliert eine Gruppe ist, doch auch große Gruppen können kontrollieren und kleine fair mit ihren Mitgliedern umgehen. Die Herkunft der Rituale erklärt ihre Geschichte, sagt aber nichts darüber, wie die Mitglieder behandelt werden.","coreRule":"⚡ Nicht was eine Gruppe glaubt, sondern wie sie ihre Mitglieder kontrolliert, entscheidet über den Kultverdacht.","beleg":"Werkstück F.1.4 (Kontext & Tiefe: Das BITE-Modell der Gedankenkontrolle)","status":"entwurf","scenario":"Im Gespräch fällt der Satz: „Die glauben an Engel, das ist doch ein Kult!“ Über das Verhalten der Gruppe gegenüber ihren Mitgliedern weißt du noch nichts.","quote":"","quoteLabel":"","kurz":"Ob eine Gruppe ihre Mitglieder manipulativ kontrolliert, zeigt sich an ihrem Umgang mit ihnen, nicht an ihrem Glauben. Der Fehler ist, Unbelegtes mit Kontrolle gleichzusetzen. Je mehr Kontrollmerkmale in hoher Intensität zusammenkommen, desto eher wird manipuliert.","prueffrage":"Welche anderen, als harmlos geltenden Gemeinschaften glauben ebenfalls an Engel?","rueckmeldung":[{"option":1,"text":"Dass sich eine Lehre belegen lässt oder nicht, ist eine reizvolle Prüfgröße. Sie klärt aber nur, ob die Aussagen stimmen, nicht ob Mitglieder kontrolliert werden. Auch unbedenkliche Gemeinschaften glauben vieles, was sich nicht belegen lässt."},{"option":2,"text":"Größe und Alter lassen sich leicht feststellen und zeigen, wie etabliert eine Gruppe ist. Über den Umgang mit den Mitgliedern sagen sie nichts: Auch große Gruppen können kontrollieren, und kleine können fair mit ihren Mitgliedern umgehen."},{"option":3,"text":"Die Herkunft der Rituale kann spannend sein und erklärt, woher Bräuche stammen. Wie die Mitglieder behandelt werden, ob sie Kontakte, Informationen und Zweifel frei haben, verrät sie aber nicht."}],"familie":"kontrolle-statt-bekenntnis","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Freedom of Mind Resource Center (S. Hassan): „Undoing Undue Influence and the BITE Model of Authoritarian Control“ (Handout)","oeffentlich":true,"url":"https://freedomofmind.com/wp-content/uploads/2024/04/BITE-Model-of-Authoritarian-Control-Handout.pdf","abruf":"2026-10-12"},{"typ":"url","kurz":"Deutscher Bundestag (1998): Endbericht der Enquete-Kommission „Sogenannte Sekten und Psychogruppen“, Drucksache 13/10950","oeffentlich":true,"url":"https://dserver.bundestag.de/btd/13/109/1310950.pdf","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"d1a153fb08eb3e42"}},{"id":"qx-f-022","clusterId":"F","werkstueckRef":"F.1.4","stufe":2,"question":"Was ist an diesem Verhalten der Gruppe das eigentlich Auffällige und Prüfenswerte?","scenario":"Du gehst zu einem Vertriebsevent, weil dich eine Bekannte eingeladen hat. Dort wirst du mit Aufmerksamkeit und Lob überschüttet. Ein paar Wochen später heißt es, deine skeptischen Freunde „gönnen dir deinen Erfolg nicht“, und du solltest den Kontakt zu ihnen herunterfahren.","options":["Die Gruppe bindet dich zuerst mit viel Zuwendung und wertet dann kritische Außenstehende ab, sodass du von deren Einwänden abgeschnitten wirst.","Die Gruppe verlangt früh eine hohe Geldsumme von dir, sodass dir ein späterer Ausstieg wegen des bereits eingesetzten Geldes kaum noch möglich erscheint.","Die Gruppe setzt dir enge Fristen für deine Entscheidung, sodass du kaum Zeit hast, das Angebot zu vergleichen und in Ruhe zu prüfen.","Die Gruppe verspricht dir von Anfang an mit wenig Aufwand hohe Einkünfte, sodass du die Erfolgsaussichten des Geschäfts deutlich überschätzt."],"correctIndex":0,"explanation":"Auffällig ist die Kombination aus „Love Bombing“ und der Isolation von kritischen Freunden: Erst gibt es überschwängliche Zuwendung, dann heißt es „Die gönnen dir deinen Erfolg nicht“. Genau dadurch fehlen dir die Menschen, die Einwände äußern würden. Das ist ein Kontrollmuster, kein Zufall: Wer Bindung durch Zuwendung aufbaut und zugleich Kritiker abwertet, macht dich von der Gruppe abhängig. Ob eine Gruppe dir guttut, erkennst du daran, ob sie dein unabhängiges Denken und deine Beziehungen stärkt oder ob sie verlangt, beides zurückzufahren. Geldforderungen, die den Ausstieg erschweren, sind bei Vertriebsangeboten prüfenswert, werden hier aber nirgends erwähnt. Das Gleiche gilt für Fristen und für Gewinnversprechen. Im Fall geht es um deine Beziehungen, nicht um dein Geld oder deinen Zeitplan.","coreRule":"⚡ Überschwängliche Zuwendung plus Abkopplung von Kritikern ist ein Kontrollmuster, kein Zufall.","beleg":"Werkstück F.1.4 (Anwendung & Relevanz: Kommerzielle Kulte; BITE: Emotional Control)","status":"entwurf","kurz":"Auffällig ist die Abfolge: erst überschwängliche Zuwendung, dann die Abwertung der Kritiker. So fehlen dir genau die Menschen, die Einwände äußern würden, und du wirst von der Gruppe abhängiger. Das ist ein Kontrollmuster, kein Zufall.","prueffrage":"Woher weiß die Gruppe, warum deine Freunde skeptisch sind, und hat sie je mit ihnen gesprochen?","rueckmeldung":[{"option":1,"text":"Früh verlangte, hohe Beträge können Ausstiege tatsächlich erschweren und sind bei Vertriebsangeboten prüfenswert. Im Fall wird aber kein Geld gefordert; es geht um Beziehungen, nicht um bereits eingesetztes Geld."},{"option":2,"text":"Enge Fristen sind ein bekanntes Warnsignal, weil sie ruhiges Prüfen erschweren. Hier wird jedoch keine Frist genannt; die Auffälligkeit liegt darin, wie die Gruppe mit deinen Freunden und deren Einwänden umgeht."},{"option":3,"text":"Gewinnversprechen mit wenig Aufwand sind bei Vertriebsmodellen ein Grund zur Skepsis. Im Fall ist davon aber keine Rede: Es gibt Lob und Aufmerksamkeit, später die Abwertung deiner Freunde, aber keine Einkommenszusagen."}],"familie":"kontrolle-statt-bekenntnis","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Freedom of Mind Resource Center (S. Hassan): „Undoing Undue Influence and the BITE Model of Authoritarian Control“ (Handout)","oeffentlich":true,"url":"https://freedomofmind.com/wp-content/uploads/2024/04/BITE-Model-of-Authoritarian-Control-Handout.pdf","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"152874591b5f5fd5"}},{"id":"qx-f-023","clusterId":"F","werkstueckRef":"F.1.4","stufe":3,"question":"Eine Behörde möchte eine Merkmalsliste, die ein früherer Sektenaussteiger und heutiger Berater entwickelt hat, als verbindliches Messinstrument verwenden, um Gruppen amtlich als manipulativ einzustufen. Die Liste fragt Kontrolle über Verhalten, Information, Gedanken und Gefühle ab. Als Beleg für ihre Zuverlässigkeit führt der Entwickler eine eigene Fragebogenstudie an, nach der die Punkte der Liste in sich stimmig sind. Was spricht am stärksten gegen diesen Plan?","options":["Die Liste wurde nur für religiöse Gruppen entworfen und lässt sich deshalb nicht auf andere Bereiche übertragen.","Eine nützliche Beratungs-Checkliste ist noch kein geprüftes Messinstrument, und eine Studie des Entwicklers ist keine unabhängige Prüfung.","Die Liste wurde von einem Fachgremium geprüft und als wissenschaftlich unhaltbar zurückgewiesen, daher ist sie wertlos.","Die vier Kontrollbereiche treten in der Praxis nie gemeinsam auf, deshalb erfasst die Liste so gut wie keine Gruppe."],"correctIndex":1,"explanation":"Wer ein Instrument selbst entwickelt und selbst prüft, kann Schwächen übersehen; dass die Punkte einer Liste in sich stimmig sind, zeigt nur, dass sie zusammenpassen, nicht dass sie das Gemeinte zuverlässig messen. Dafür braucht es eine unabhängige Prüfung. Hinzu kommt: Ein Teil der beschriebenen Kontrolle gehört unvermeidlich zu jeder Gemeinschaft (so die Enquete-Kommission des Bundestages 1998), entscheidend sind Intensität und Verlust der Selbstbestimmung; ein Ja bei einzelnen Punkten beweist deshalb noch keine Manipulation. Als Orientierungshilfe in der Beratung kann die Liste nützlich sein, als verbindliche amtliche Messlatte reicht sie nicht. Die anderen Antworten verfehlen den Kern: Die abgefragten Kontrollbereiche sind nicht an Religion gebunden, und ein Nie-gemeinsam-Auftreten der Bereiche oder eine eindeutige Widerlegung ist so nicht belegt.","coreRule":"⚡ Als Checkliste brauchbar, als Messlatte ungeeignet: Wer das eigene Instrument selbst prüft, liefert keine unabhängige Prüfung, und entscheidend sind Intensität und Verlust der Selbstbestimmung.","beleg":"Werkstück F.1.4 (Das BITE-Modell); Fn. gl-f-6; Fn. gl-f-enquete (Bundestag 1998, Drucksache 13/10950, S. 77)","status":"entwurf","scenario":"","kurz":"Wer ein Instrument selbst entwickelt und selbst prüft, kann Schwächen übersehen; stimmige Punkte zeigen nur, dass sie zusammenpassen, nicht dass sie das Gemeinte messen. Eine nützliche Beratungshilfe wird so noch keine amtliche Messlatte.","prueffrage":"Würden auch Sportvereine, Klöster oder Firmen bei einzelnen Punkten der Liste ein Ja bekommen, und was hieße das für eine amtliche Einstufung?","rueckmeldung":[{"option":0,"text":"Nach dem Anwendungsbereich zu fragen, ist bei jedem Instrument berechtigt. Kontrolle über Verhalten, Information, Gedanken und Gefühle ist aber nicht an Religion gebunden, und der Kern liegt anderswo: wer die Liste geprüft hat und wie."},{"option":2,"text":"Schwache Belege sind ein berechtigter Einwand. Von einem Gremium, das die Liste verworfen hätte, ist aber nichts bekannt, und „wertlos“ geht zu weit: In der Beratung kann sie nützen, als amtliche Messlatte reicht sie nicht."},{"option":3,"text":"Das trifft ein Problem von der falschen Seite: Ein Teil dieser Kontrolle gehört unvermeidlich zu jeder Gemeinschaft, die Liste fände also eher zu viel als zu wenig. Das eigentliche Problem ist die fehlende unabhängige Prüfung."}],"familie":"kontrolle-statt-bekenntnis","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Deutscher Bundestag (1998): Endbericht der Enquete-Kommission „Sogenannte Sekten und Psychogruppen“, Drucksache 13/10950","oeffentlich":true,"url":"https://dserver.bundestag.de/btd/13/109/1310950.pdf","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Hassan, S. A. (2020): The BITE Model of Authoritarian Control. Diss. Fielding Graduate University","oeffentlich":false}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"79152f03664b7d32"}},{"id":"qx-f-024","clusterId":"F","werkstueckRef":"F.1.4","stufe":4,"question":"Eine Person bestimmt, mit wem ihr Partner Umgang hat, verwaltet dessen Geld allein und macht dessen Freunde schlecht. Eine Bekannte meint: „Kontrolle in dieser Form gibt es nur in Sekten, in einer Zweierbeziehung kann das gar nicht passieren.“ Welche Antwort trifft den Denkfehler am besten?","options":["Sie schließt von der bekanntesten Form auf die einzige: Entscheidend ist nicht die Gruppengröße, sondern ob Umgang, Geld und Information gezielt gelenkt werden, um den anderen abhängig zu machen.","Sie baut einen Strohmann: Sie verzerrt die Position der kontrollierenden Person zu einer Karikatur, damit sie sich leichter widerlegen lässt, und befasst sich nicht mit dem tatsächlichen Verhalten.","Sie unterstellt eine Rutschbahn: Sie nimmt an, dass aus jedem Eingriff in den Umgang zwangsläufig immer schwerere Eingriffe folgen, ohne zu belegen, dass jeder Schritt den nächsten nach sich zieht.","Sie greift die Person an statt das Verhalten: Sie wertet die kontrollierende Person als Mensch ab, anstatt zu prüfen, ob ihr Verhalten tatsächlich andere in Abhängigkeit bringt."],"correctIndex":0,"explanation":"Die Bekannte schließt von der bekanntesten Form (Sekte) auf die einzige Form. Entscheidend ist aber die Struktur: Wer Kontakte einschränkt, finanzielle Abhängigkeit schafft und Freunde abwertet, isoliert den anderen und entzieht ihm andere Informations- und Rückhalt-Quellen. Das sind dieselben Kontrollmechanismen, die man bei manipulativen Gruppen beobachtet, nur im Format einer Zweierbeziehung. Dafür braucht es weder einen Anführer noch eine Gruppe. Dabei gilt: Ein gewisses Maß an Einfluss gehört zu jeder Gemeinschaft, problematisch wird es erst bei systematischer Isolation, Abhängigkeit und Manipulation. Ein Strohmann würde eine fremde Position verzerren, die Bekannte stellt aber eine eigene, überprüfbare Behauptung auf. Eine Rutschbahn braucht eine behauptete Kette von Folgen, die hier nirgends vorkommt. Und einen Angriff auf die Person gibt es nicht: Sie bewertet weder den Menschen noch sein Verhalten, sondern bestreitet nur, dass so etwas außerhalb von Sekten vorkommt.","coreRule":"⚡ Prüfe die Struktur der Kontrolle (Umgang, Geld, Information, Gefühle), nicht die Größe oder das Etikett der Gruppe.","beleg":"Werkstück F.1.4 (Anwendung & Relevanz: Missbräuchliche Beziehungen)","status":"entwurf","scenario":"","kurz":"Aus „die bekannteste Form findet sich in Sekten“ wird „nur dort“. Entscheidend ist aber nicht die Gruppengröße, sondern ob Umgang, Geld und Information gezielt gelenkt werden, um den anderen abhängig zu machen. Das geht auch zu zweit.","prueffrage":"Welcher der drei Schritte, die die Person unternimmt, wäre ohne eine Gruppe im Hintergrund nicht möglich?","rueckmeldung":[{"option":1,"text":"Ein Strohmann würde eine fremde Position verzerren und die Karikatur widerlegen. Die Bekannte stellt aber eine eigene, überprüfbare Behauptung auf, nämlich dass so etwas nur in Sekten vorkomme. Ihr Fehler liegt im Schluss selbst."},{"option":2,"text":"Eine Rutschbahn setzt eine behauptete Kette von Folgen voraus, bei der ein Schritt angeblich den nächsten nach sich zieht. Die Bekannte spricht aber von keiner Eskalation, sondern bestreitet nur, dass solche Kontrolle in Zweierbeziehungen vorkommt."},{"option":3,"text":"Ein Angriff auf die Person wertet den Menschen ab, statt die Sache zu prüfen. Die Bekannte sagt nichts über den Charakter der kontrollierenden Person; sie behauptet nur, wo solche Kontrolle auftreten kann. Das ist ein Fehlschluss über die Sache."}],"familie":"kontrolle-statt-bekenntnis","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Crown Prosecution Service: „Controlling or Coercive Behaviour in an Intimate or Family Relationship“ (Leitlinie, Stand 07.02.2025)","oeffentlich":true,"url":"https://www.cps.gov.uk/legal-guidance/controlling-or-coercive-behaviour-intimate-or-family-relationship","abruf":"2026-10-12"},{"typ":"url","kurz":"Freedom of Mind Resource Center (S. Hassan): „Undoing Undue Influence and the BITE Model of Authoritarian Control“ (Handout)","oeffentlich":true,"url":"https://freedomofmind.com/wp-content/uploads/2024/04/BITE-Model-of-Authoritarian-Control-Handout.pdf","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"b7595bf983718156"}},{"id":"qx-f-025","clusterId":"F","werkstueckRef":"F.1.5","stufe":1,"question":"Welche Frage hilft dir am besten, bei einer beeindruckend aussehenden „Studie“ zu prüfen, ob sie echte Forschung ist oder nur deren äußere Form nachahmt?","options":["Ob die Zahlen im Bericht rechnerisch stimmen und ob die Grafiken sauber beschriftet und nachvollziehbar aufgebaut sind","Ob das Institut ein Impressum mit Adresse hat und ob seine Mitarbeitenden mit Namen und Lebenslauf öffentlich auffindbar sind","Ob der Bericht auch Ergebnisse nennt, die der Behauptung widersprechen, und ob andere Forscher sie wiederholen konnten","Ob die Fachbegriffe im Bericht korrekt verwendet werden und ob der Text durchgehend sachlich und frei von Werbesprache bleibt"],"correctIndex":2,"explanation":"Jargon, Grafiken, Titel und Institutsnamen lassen sich leicht nachahmen, sie sagen nichts darüber, ob die Methode taugt. Entscheidend ist die selbstkritische Redlichkeit: Echte Forschung berichtet auch Belege, die der eigenen Theorie widersprechen, und sucht aktiv nach Wegen, sie zu widerlegen. Ob unabhängige Forscher das Ergebnis wiederholen können, zeigt, ob mehr dahintersteckt als eine schön gebaute Hülle. Der Physiker Richard Feynman nannte dieses Muster „Cargo-Kult-Wissenschaft“: Inselbewohner bauten nach dem Zweiten Weltkrieg Landebahnen, Feuer und Holz-Kopfhörer nach, um Flugzeuge zurückzulocken. Die Form stimmte, das Verständnis fehlte, und die Flugzeuge blieben aus. Rechnerisch stimmige Zahlen und saubere Grafiken lassen sich ebenfalls nachbauen und sagen nichts über die Methode. Ein Impressum und namentlich bekannte Mitarbeitende zeigen, dass es das Institut gibt, nicht dass dort sauber geforscht wird. Und korrekt gebrauchte Fachbegriffe in sachlichem Ton gehören zur äußeren Form, die sich übernehmen lässt.","coreRule":"⚡ Nicht das Aussehen, sondern die Redlichkeit macht Wissenschaft aus: Frag nach Gegenbelegen und Wiederholbarkeit, nicht nach Jargon und Titeln.","beleg":"Werkstück F.1.5 (Kernidee; Kontext & Tiefe); Fn. gl-f-7 (Feynman 1974, Caltech-Rede)","status":"entwurf","scenario":"Ein Institut, das du nicht kennst, veröffentlicht einen Bericht mit Fachjargon, vielen Grafiken und Titeln wie „Dr.“. Der Bericht stützt eine Behauptung, die dir zweifelhaft vorkommt.","kurz":"Echte Forschung nennt auch Belege gegen die eigene These, und unabhängige Forscher können sie wiederholen. Jargon, Grafiken und Titel sind dagegen nur die nachahmbare Hülle, die allein noch nichts über die Methode sagt.","prueffrage":"Welche der Merkmale, die dich an dem Bericht beeindrucken, könnte auch jemand ohne echte Daten herstellen?","rueckmeldung":[{"option":0,"text":"Stimmige Zahlen und saubere Grafiken sprechen für Sorgfalt im Detail. Auch sie gehören aber zur äußeren Form und lassen sich nachbauen. Sie sagen nicht, ob die Methode taugt oder ob Widersprechendes verschwiegen wurde."},{"option":1,"text":"Ein Impressum und auffindbare Mitarbeitende zeigen, dass es das Institut wirklich gibt, und das ist ein sinnvoller erster Schritt. Ob dort sauber geforscht wird, folgt daraus aber nicht."},{"option":3,"text":"Korrekt verwendete Begriffe und ein sachlicher Ton wirken seriös. Beides gehört aber zur Form, die sich leicht übernehmen lässt, ohne die Methode zu verstehen. Es sagt daher nichts darüber, ob geforscht wurde."}],"familie":"wissenschaft-abgrenzen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Feynman, R. P. (1974): „Cargo Cult Science“, Engineering and Science 37(7), Caltech-Scan","oeffentlich":true,"url":"https://calteches.library.caltech.edu/51/2/CargoCult.pdf","seite":"S. 11, 13","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"7ba00f6bccb15528"}},{"id":"qx-f-026","clusterId":"F","werkstueckRef":"F.1.5","stufe":2,"question":"Wie bewertest du das Vorgehen der Gruppe?","scenario":"Eine Forschungsgruppe testet Telepathie in 40 Versuchsreihen. Veröffentlicht werden die drei Reihen mit auffälligem Treffer, die übrigen 37 verschwinden in der Schublade. Ein Kollege sagt: „Drei klare Treffer sind doch ein Ergebnis. Es steht ja alles korrekt in der Veröffentlichung.“","options":["Als Schwäche der Versuchsleitung, denn solange Versuchsleiter wissen, welche Bedingung gerade läuft, können sie die Ergebnisse unbewusst beeinflussen und jede Reihe wird zweifelhaft.","Als Verwechslung von Auffälligkeit und Bedeutung, denn ein statistisch auffälliger Treffer sagt noch nichts darüber, wie groß oder wichtig ein Effekt tatsächlich ist.","Als Nachahmung von Forschung ohne ihren Kern, denn wer nur die Treffer zeigt und die 37 Fehlschläge verschweigt, täuscht ein Ergebnis vor, das die Gesamtlage nicht trägt.","Als Verzerrung durch Selbstauswahl der Teilnehmenden, denn wer sich für begabt hält, meldet sich eher zum Test und verfälscht so die Zusammensetzung der Stichprobe."],"correctIndex":2,"explanation":"Aussagekraft hat erst das Gesamtbild aller Versuche, nicht die herausgepickten Treffer. Wer nur die drei Treffer zeigt und die 37 Fehlschläge verschweigt, erzeugt den Eindruck eines Effekts, den die Daten insgesamt nicht hergeben. Redliche Forschung berichtet auch über alles, was der eigenen Hypothese widerspricht. Fachsprache, Versuchsaufbau und Veröffentlichung können dann perfekt aussehen, und trotzdem fehlt der Kern der Wissenschaft: die Bereitschaft, die eigene Idee scheitern zu sehen. Feynman nannte das Cargo-Kult-Wissenschaft: Die Landebahn steht, aber die Flugzeuge der Erkenntnis landen dort nicht. Die Pflicht, auch widersprechende Ergebnisse zu berichten, besteht unabhängig davon, ob die Gruppe von Beweis spricht. Eine fehlende Verblindung der Versuchsleitung wäre ein berechtigter Einwand gegen Versuche, davon ist im Fall aber nichts zu lesen. Wie groß oder wichtig ein Effekt ist, ist hier nicht die Frage, sondern welche Reihen gezeigt werden. Und eine Selbstauswahl der Teilnehmenden betrifft die Zusammensetzung der Stichprobe, nicht das Weglassen ganzer Reihen.","coreRule":"⚡ Wer Fehlschläge verschweigt, baut nur die Landebahn, aber keine Wissenschaft.","beleg":"Werkstück F.1.5 (Anwendung & Relevanz: In der Parapsychologie)","status":"entwurf","kurz":"Aussagekraft hat nur das Gesamtbild aller 40 Reihen, nicht die drei herausgepickten Treffer. Dass in der Veröffentlichung alles korrekt dasteht, ändert daran nichts: Wer die 37 Fehlschläge verschweigt, täuscht einen Effekt vor, den die Daten insgesamt nicht hergeben.","prueffrage":"Wie viele auffällige Treffer würde man bei 40 Versuchsreihen allein durch Zufall erwarten?","rueckmeldung":[{"option":0,"text":"Fehlende Verblindung wäre bei solchen Versuchen ein berechtigter Einwand. Davon ist im Fall aber nichts zu lesen, und sie erklärt auch nicht, warum 37 von 40 Reihen gar nicht erst gezeigt werden."},{"option":1,"text":"Dass Auffälligkeit nicht Bedeutung heißt, stimmt im Allgemeinen. Hier geht es aber nicht um Größe oder Wichtigkeit eines Effekts, sondern darum, welche Reihen überhaupt gezeigt werden."},{"option":3,"text":"Selbstauswahl kann eine Stichprobe verzerren, doch davon ist im Fall nichts zu lesen. Sie betrifft außerdem, wer teilnimmt, nicht, welche Reihen veröffentlicht werden. Das Problem liegt beim Weglassen der 37 Reihen."}],"familie":"wissenschaft-abgrenzen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Feynman, R. P. (1974): „Cargo Cult Science“, Engineering and Science 37(7), Caltech-Scan","oeffentlich":true,"url":"https://calteches.library.caltech.edu/51/2/CargoCult.pdf","seite":"S. 11–12","abruf":"2026-10-12"},{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: „Science and Pseudo-Science“","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschn. 5.1","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"e8c2589aa8af3fb1"}},{"id":"qx-f-027","clusterId":"F","werkstueckRef":"F.1.5","stufe":3,"question":"Dein Kollege sagt dazu: „Unseriöse Forschung gibt es nur bei Homöopathen und Parapsychologen. Was an einer Hochschule veröffentlicht wird, hat Institut, Fachjargon und Peer-Review, also ist es automatisch Wissenschaft.“ Was ist an diesem Schluss fehlerhaft?","options":["Er schließt von der äußeren Form auf die Qualität: Institut, Jargon und Veröffentlichung sagen nichts darüber, ob die Forschenden ihre eigenen Ideen ernsthaft scheitern lassen wollten.","Er schließt von der Medienaufmerksamkeit auf die Belegtheit: Weil über die Studie eine Schlagzeile erscheint, hält er ihre Behauptung bereits für gesichert, ohne ihre Methode zu kennen.","Er schließt von wenigen Fällen auf alle: Weil er einzelne fehlerhafte Hochschulstudien kennt, hält er die gesamte Hochschulforschung für unseriös und lehnt auch gute Studien pauschal ab.","Er schließt von der Quelle auf die Absicht: Weil Hochschulen Drittmittel einwerben, müssen ihre Studien zwangsläufig im Interesse der Geldgeber verfälscht sein, ganz gleich, wie sorgfältig gearbeitet wurde."],"correctIndex":0,"explanation":"Der Kollege verwechselt die äußere Form der Wissenschaft mit ihrer Substanz. Ob Forschung trägt, entscheidet sich an der selbstkritischen Redlichkeit: Werden Gegenbelege gesucht und berichtet, gibt es Kontrollgruppen, ist das Ergebnis wiederholbar? Das gilt überall, auch an Hochschulen. Richard Feynman nannte in seiner Rede „Cargo Cult Science“ (1974) ausdrücklich auch Studien zu Lesemethoden und Rattenversuche der Psychologie, die die sorgfältigen Kontrollen eines vorbildlichen Vorgängers nicht beachteten, als Beispiele für Forschung, die nur die Form der Wissenschaft wahrt. Die anderen Schlüsse sind für sich bekannte Fehlschlüsse, die der Kollege hier aber nicht zieht: Er nimmt nicht das Medienecho als Beleg für die Studie. Er verwirft auch nicht die Hochschulforschung wegen einzelner Fehler, im Gegenteil. Und von Geldgebern spricht er nicht. Sein Fehler ist, die Form als Beweis der Substanz zu nehmen.","coreRule":"⚡ Ein Titel, ein Institut und Fachjargon beweisen keine Redlichkeit: Prüfe die Methode, nicht das Etikett.","beleg":"Werkstück F.1.5 (Kernidee); Fn. gl-f-7 (Quelle der Feynman-Rede „Cargo Cult Science“, 1974)","status":"entwurf","scenario":"Ihr sprecht über eine Schlagzeile zu einer neuen Studie, die an einer Universität entstanden ist.","kurz":"Institut, Fachjargon und Veröffentlichung sind nur die äußere Form von Wissenschaft. Ob Forschung trägt, zeigt sich daran, ob Gegenbelege gesucht werden und Kontrollen vorhanden sind. Wer die Form für den Beweis hält, übersieht das.","prueffrage":"Ist schon einmal eine Hochschulstudie mit Peer-Review später zurückgezogen worden oder bei der Wiederholung gescheitert?","rueckmeldung":[{"option":1,"text":"Dass eine Schlagzeile nichts über die Methode verrät, stimmt. Der Kollege beruft sich aber nicht auf das Medienecho, sondern auf Institut, Jargon und Peer-Review. Sein Fehler liegt woanders: Er hält diese äußeren Merkmale für den Beweis von Qualität."},{"option":2,"text":"Von wenigen schlechten Fällen auf alle zu schließen wäre tatsächlich ein Fehler. Der Kollege tut aber das Gegenteil: Er hält Hochschulforschung pauschal für Wissenschaft und lässt Einzelfehler außer Acht."},{"option":3,"text":"Interessenkonflikte durch Geldgeber sind real und gehören bei einer Studie geprüft. Der Kollege erwähnt sie aber gar nicht und vertraut der Hochschule eher zu sehr. Und dass Drittmittel Ergebnisse zwangsläufig verfälschen, trifft so ebenfalls nicht zu."}],"familie":"wissenschaft-abgrenzen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Feynman, R. P. (1974): „Cargo Cult Science“, Engineering and Science 37(7), Caltech-Scan","oeffentlich":true,"url":"https://calteches.library.caltech.edu/51/2/CargoCult.pdf","seite":"S. 10, 13","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"ab795d8ac4cd0e48"}},{"id":"qx-f-028","clusterId":"F","werkstueckRef":"F.1.6","stufe":1,"question":"Ein Bekannter sagt: „Meine Schwester ist Ärztin und gewohnt, Behauptungen kritisch zu prüfen. Seit dem Tod ihres Mannes schwört sie auf einen Heiler, der angeblich Kontakt zu Verstorbenen herstellt. Ausgerechnet sie fällt auf so etwas nie herein, da muss etwas dran sein.“ Welcher Schluss ist am besten begründet?","options":["Die einfachste Erklärung ist, dass der Heiler etwas kann, denn nach dem Sparsamkeitsprinzip zählt die Erklärung mit den wenigsten Annahmen.","Ihre Überzeugung beweist wenig, denn auch geübte Skeptiker prüfen Behauptungen nicht mehr, die ein tiefes Bedürfnis berühren.","Solange niemand bewiesen hat, dass der Heiler keinen Kontakt herstellen kann, spricht ihre Erfahrung dafür, dass es möglich ist.","Ihre Überzeugung ist damit widerlegt, denn was aus Trauer und Sehnsucht entstanden ist, kann nach aller Erfahrung nicht wahr sein."],"correctIndex":1,"explanation":"Intelligenz oder Fachkompetenz belegen nicht, dass eine Überzeugung stimmt. Das zeigt der Fall des Schriftstellers Arthur Conan Doyle: Der Schöpfer des kühlen Logikers Sherlock Holmes hielt nach den Verlusten im Ersten Weltkrieg die inszenierten „Cottingley Fairies“-Fotos trotz ihrer Fälschung für Zeugnisse einer unsichtbaren Lebensform, öffentlich vorsichtig als starken ersten Anschein, privat als erwiesen. Kritisches Denken ist keine feste Eigenschaft, sondern eine Praxis, die bewusst angewendet werden muss; niemand ist durch Intelligenz oder Skepsis dauerhaft immun. Ein überwältigendes Bedürfnis nach Trost oder Hoffnung kann sie ausgerechnet bei der eigenen Überzeugung abschalten, und dann dient der Verstand als Anwalt für den Glauben statt als Prüfer. Der Verweis auf ihre Kompetenz hilft also nicht weiter; entscheidend ist, ob die Behauptung selbst einer Prüfung standhält. Das Sparsamkeitsprinzip stützt hier eher die Gegenseite, denn dass Trauer ein Urteil färbt, braucht weniger Annahmen als ein Kontakt zu Verstorbenen. Dass niemand das Gegenteil bewiesen hat, ist kein Beleg, denn wer etwas behauptet, muss es belegen. Und der Ursprung einer Überzeugung in der Trauer widerlegt sie nicht, er erklärt nur, warum sie nicht geprüft wurde.","coreRule":"⚡ Skepsis ist eine Praxis, keine Eigenschaft: Sie muss gerade dort angewendet werden, wo es weh tut.","beleg":"Werkstück F.1.6 (Kernidee; Anwendung & Relevanz)","status":"entwurf","scenario":"Ein Bekannter erzählt dir von seiner Schwester, einer erfahrenen Ärztin. Sie ist es gewohnt, Behauptungen kritisch zu prüfen, glaubt aber seit dem Tod ihres Mannes fest an einen Heiler, der angeblich Kontakt zu Verstorbenen herstellt.","quote":"","quoteLabel":"","kurz":"Fachkompetenz belegt nicht, dass eine Überzeugung stimmt: Ein tiefes Bedürfnis kann Skepsis ausgerechnet bei der eigenen Sache abschalten. Der Fehler ist, von ihrer Kompetenz auf die Wahrheit zu schließen. Maßgeblich ist, ob die Behauptung selbst einer Prüfung standhält.","prueffrage":"Welche Belege für die Fähigkeiten des Heilers gibt es außer der Überzeugung der Ärztin selbst?","rueckmeldung":[{"option":0,"text":"Sparsamkeit zählt tatsächlich, aber hier spricht sie eher für die Gegenseite. Dass Trauer das Urteil färbt, braucht weniger Annahmen als ein Kontakt zu Verstorbenen."},{"option":2,"text":"Dass man etwas nicht ausschließen kann, macht es noch nicht wahrscheinlich. Wer eine Fähigkeit behauptet, muss sie belegen; fehlendes Gegenteil und eine einzelne Erfahrung, die selbst ungeprüft ist, reichen dafür nicht."},{"option":3,"text":"Die Trauer erklärt, warum die Ärztin nicht prüft, aber sie widerlegt ihre Überzeugung nicht. Ob der Heiler etwas kann, entscheidet sich an der Behauptung selbst, nicht an ihrem Entstehungsgrund."}],"familie":"werkzeuge-gegen-sich-selbst","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Doyle, A. C. (1922): The Coming of the Fairies, Kap. II (Strand-Artikel: „strong prima facie case“) und Kap. IV (Brief an Gardner: „You and I needed no confirmation“) (Project Gutenberg Nr. 47506)","oeffentlich":true,"url":"https://www.gutenberg.org/files/47506/47506-0.txt","abruf":"2026-10-12"},{"typ":"url","kurz":"University of Leeds Library, Special Collections: Katalogeintrag Cottingley Fairies","oeffentlich":true,"url":"https://explore.library.leeds.ac.uk/special-collections-explore/8705","abruf":"2026-10-12"},{"typ":"url","kurz":"Internet Encyclopedia of Philosophy: Fallacies, Art. „Appeal to Authority“","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"1a6093775002f1d8"}},{"id":"qx-f-029","clusterId":"F","werkstueckRef":"F.1.6","stufe":2,"question":"Was zeigt dieser Unterschied am ehesten?","options":["Er zweifelt privat stärker als öffentlich und fürchtet insgeheim, dass die Belege gefälscht sind.","Er ist sich öffentlich wie privat gleich sicher und nennt die Belege überall den endgültigen Beweis.","Er hat die Überzeugung längst gefasst und gibt sich nach außen nur vorsichtig, statt die Belege ergebnisoffen zu prüfen.","Er hat die Belege inzwischen gründlich widerlegt und gibt sich nach außen nur aus Höflichkeit vorsichtig."],"correctIndex":2,"explanation":"Die vorsichtige öffentliche Formulierung und die private Gewissheit passen nicht zusammen. Das spricht dafür, dass die Überzeugung innerlich schon feststeht und die Vorsicht nach außen eher Zurückhaltung oder Taktik ist. Die Belege werden dann eher verteidigt als ergebnisoffen geprüft. Hohe Intelligenz schützt davor nicht: Sie liefert dann bloß bessere Argumente für das, was man ohnehin glauben will. Gerade bei Behauptungen, die ein tiefes persönliches Bedürfnis berühren, lohnt es sich daher, genau auf diese Diskrepanz zu achten. Ein Beispiel ist Arthur Conan Doyle, der Schöpfer von Sherlock Holmes: Öffentlich sprach er von einem „starken ersten Anschein“ der Cottingley-Feenfotos (Strand-Artikel vom Dezember 1920), im Brief an seinen Mitstreiter E. L. Gardner vom Oktober 1920 hielt er die Sache dagegen für erwiesen.","coreRule":"⚡ Wer privat schon überzeugt ist, prüft öffentlich nur noch pro forma: Der Wunsch regiert.","beleg":"Werkstück F.1.6 (Der Riss in der Festung); Fn. gl-f-doyle (Doyle 1922, Kap. I, II und IV)","status":"entwurf","scenario":"Ein sehr kluger, öffentlich bekannter Mann verteidigt eine Behauptung, die ihm seit einem schweren Verlust sehr wichtig ist. Der Verlust liegt kurz zurück, die Behauptung verspricht ihm Trost, und die Belege sind dünn. Öffentlich schreibt er, die Belege sprächen für einen „starken ersten Anschein“, mehr nicht; in einem privaten Brief an einen Gleichgesinnten nennt er die Sache längst erwiesen.","kurz":"Wer öffentlich nur von einem „starken ersten Anschein“ spricht, privat aber von „längst erwiesen“, hat sich vermutlich schon festgelegt. Die Vorsicht nach außen ist dann eher Zurückhaltung oder Taktik, und die Belege werden verteidigt statt ergebnisoffen geprüft.","prueffrage":"Wie stark sind die Belege, und welche der beiden Äußerungen geht über das hinaus, was sie hergeben?","rueckmeldung":[{"option":0,"text":"Der Unterschied springt ins Auge, und man liest ihn schnell als verborgenen Zweifel. Der Brief nennt die Sache aber „längst erwiesen“: Das zeigt private Gewissheit, nicht Unsicherheit, und von gefälschten Belegen ist nirgends die Rede."},{"option":1,"text":"Privat ist er tatsächlich sehr sicher. Öffentlich spricht er aber nur von einem „starken ersten Anschein“, mehr nicht. Die beiden Aussagen sind gerade nicht gleich, und genau dieser Unterschied ist das Auffällige."},{"option":3,"text":"Höfliche Zurückhaltung wäre eine freundliche Lesart. Wer die Belege aber widerlegt hätte, würde die Sache privat nicht „längst erwiesen“ nennen. Von einer Widerlegung ist nirgends die Rede, die Belege sind nur dünn."}],"familie":"werkzeuge-gegen-sich-selbst","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Doyle, A. C. (1922): The Coming of the Fairies, Kap. II und IV (Project Gutenberg Nr. 47506)","oeffentlich":true,"url":"https://www.gutenberg.org/files/47506/47506-0.txt","abruf":"2026-10-12"},{"typ":"url","kurz":"Kahan, D. M. u. a. (2013): Motivated Numeracy and Enlightened Self-Government (Working Paper)","oeffentlich":true,"url":"https://scholarsbank.uoregon.edu/items/e034d504-ed17-4e0c-a713-ac3f85a8187a/full","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"d323cc46a3a5e95b"}},{"id":"qx-f-030","clusterId":"F","werkstueckRef":"F.1.6","stufe":3,"question":"Was ändert sich am Wechsel vom Freundeskreis zur Kolumne am stärksten?","options":["Neu ist, dass sie ihren guten Ruf einsetzt, um eine unbewiesene Behauptung zu verbreiten, sodass andere ihr vertrauen, ohne selbst zu prüfen.","Neu ist, dass sie Prüfungen mit immer neuen Ausreden entkräftet, sodass ihre Überzeugung durch keinen Befund mehr widerlegbar ist.","Neu ist, dass der Verlust ihres Bruders ihr Urteil trübt, sodass sie ihre eigene Überzeugung nicht mehr nüchtern prüfen kann.","Neu ist, dass sie in zufälligen Signalen des Geräts Muster erkennt, sodass sie bloßes Rauschen als Botschaft von Verstorbenen deutet."],"correctIndex":0,"explanation":"Ein privater Glaube, der Trost spendet, betrifft vor allem die Person selbst. Problematisch wird es, wenn Ansehen und Reichweite eingesetzt werden, um eine ungeprüfte Behauptung zu verbreiten: Andere vertrauen ihr womöglich, weil der Name der Person dem Unsinn den „Stempel der Genialität“ verleiht, statt selbst zu prüfen (Appell an die falsche Autorität). Genau das tat Arthur Conan Doyle, als er die Cottingley-Feen-Fotos mit seinem Ruf als Denker adelte; sie waren, wie die Mädchen später zugaben, mit Papierfiguren und Nadeln inszeniert. Dass jemand Trost sucht, ist menschlich; zur Gefahr wird es, wenn das Vertrauen in einen Namen an die Stelle der Prüfung tritt und andere in die Irre führt. Die Ausreden gegen Prüfungen und die Trauer, die ihr Urteil trübt, gab es schon vorher im Freundeskreis, sie erklären nicht, was sich durch die Kolumne ändert. Auch das Deuten von Zufälligem als Botschaft betrifft ihren eigenen Glauben, nicht die Wirkung auf andere.","coreRule":"⚡ Privater Trost ist Privatsache; zur Gefahr wird er, wenn berühmte Autorität ihn in die Öffentlichkeit trägt und andere das Prüfen ersetzen lässt.","beleg":"Werkstück F.1.6 (Der Kipppunkt)","status":"entwurf","scenario":"Eine für ihren scharfen Verstand berühmte Wissenschaftsjournalistin hat ihren Bruder verloren. Seitdem ist sie überzeugt, dass sich Verstorbene über ein bestimmtes Gerät melden, und ist dafür bisher keiner Prüfung begegnet, die sie nicht mit immer neuen Ausreden entkräftet hätte. Zunächst erzählt sie nur Freunden davon. Dann beginnt sie, das Gerät in einer reichweitenstarken Kolumne als gut belegt zu empfehlen.","kurz":"Der Glaube selbst bleibt derselbe; neu ist, dass ihr Ruf nun als Bürgschaft dient. Wer ihrem Namen vertraut, übernimmt die Behauptung, statt sie zu prüfen, und genau so wirkt der Appell an die falsche Autorität.","prueffrage":"Was an ihrer Überzeugung und an ihrem Umgang mit Prüfungen ist vor und nach dem Wechsel gleich geblieben?","rueckmeldung":[{"option":1,"text":"Dieses Ausweichen vor Prüfungen ist auffällig, kam aber schon vor der Kolumne vor. Es erklärt ihren Glauben, nicht, was sich ändert, wenn sie ihn mit großer Reichweite vor anderen vertritt."},{"option":2,"text":"Trauer kann das Urteil trüben, das wirkte aber schon im Freundeskreis. Neu ist nicht ihr Zustand, sondern dass durch die Reichweite viele Menschen dieser Behauptung vertrauen könnten."},{"option":3,"text":"Ob sie Zufälliges als Botschaft deutet, betrifft ihren eigenen Glauben und wäre im Freundeskreis nicht anders. Am Wechsel zur Kolumne ändert sich etwas anderes: die Wirkung auf Menschen, die ihr vertrauen."}],"familie":"ergaenzen-oder-ersetzen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Internet Encyclopedia of Philosophy: Fallacies, Art. „Appeal to Authority“","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"url","kurz":"University of Leeds Library, Special Collections: Katalogeintrag Cottingley Fairies (Veröffentlichung im Strand Magazine 1920/1921, Papierfiguren mit Hutnadeln, Geständnis 1983)","oeffentlich":true,"url":"https://explore.library.leeds.ac.uk/special-collections-explore/8705","abruf":"2026-10-12"},{"typ":"url","kurz":"Doyle, A. C. (1922): The Coming of the Fairies (Project Gutenberg Nr. 47506)","oeffentlich":true,"url":"https://www.gutenberg.org/files/47506/47506-0.txt","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"2f1c9471829b1063"}},{"id":"qx-f-031","clusterId":"F","werkstueckRef":"F.1.6","stufe":4,"question":"Wie gehst du mit ihr am sinnvollsten um?","scenario":"Eine kluge Bekannte vertraut seit dem Tod ihres Mannes den Botschaften eines Mediums. Wenn du Widersprüche ansprichst, findet sie jedes Mal eine neue, geschickte Begründung, warum die Botschaften trotzdem stimmen. Du möchtest ihr helfen und dabei nicht überheblich wirken.","options":["Weitere Widersprüche sammeln und ihr gebündelt vorlegen, denn je mehr Belege zusammenkommen, desto schwerer lässt sich der Glaube halten.","Gemeinsam mit anderen Angehörigen deutlich machen, dass sie sich irrt, denn mehrere Stimmen überzeugen eher als ein einzelner Einwand.","Nach dem Bedürfnis fragen, das der Glaube für sie erfüllt, denn Intelligenz schützt nicht vor Selbsttäuschung, wenn ein Wunsch im Spiel ist.","Das Thema künftig meiden und nichts mehr hinterfragen, denn Trauer macht Kritik an einer Überzeugung in aller Regel unpassend."],"correctIndex":2,"explanation":"Intelligenz ist kein Gütesiegel für einzelne Behauptungen, und wer in einem Gebiet brillant ist, kann in einem anderen völlig danebenliegen (Appell an die falsche Autorität). Kein Mensch ist immun gegen Selbsttäuschung, egal wie intelligent oder skeptisch er sonst ist. Auffällig ist hier das Muster: Eine intelligente Person verteidigt eine unbewiesene Behauptung, die ein tiefes persönliches Bedürfnis berührt, wendet ihre kritischen Fähigkeiten nicht auf die eigene, liebgewonnene Überzeugung an und erfindet für widersprüchliche Beweise immer neue Rationalisierungen. Der Schlüssel liegt also im Bedürfnis dahinter (Trost, Hoffnung, Sinn). Die Frage, welches tiefe emotionale Bedürfnis dieser Glaube für sie erfüllt, nimmt sie ernst und zeigt, warum die Prüfung bei ihr aussetzt. Das schafft die Grundlage für ein Gespräch. Weitere Widersprüche vorzulegen hat bisher nicht gewirkt, denn sie fand für jeden eine neue Begründung. Mehrere Angehörige zu versammeln erzeugt genau die Überheblichkeit, die du vermeiden willst. Und das Thema zu meiden mag rücksichtsvoll wirken, verzichtet aber auf jede Hilfe.","coreRule":"⚡ Erst fragen, was ein Glaube leistet, dann prüfen, was er behauptet.","beleg":"Werkstück F.1.6 (Das Härten im Feuer: Schmiede-Übung; Anwendung & Relevanz: Lektion in Demut; Red Flags)","status":"entwurf","kurz":"Weil ihre Klugheit sie nicht davor schützt, dort zu täuschen, wo ein tiefer Wunsch im Spiel ist, hilft die Frage nach dem Bedürfnis hinter dem Glauben mehr als jeder weitere Einwand. Sie nimmt sie ernst und macht ein Gespräch möglich.","prueffrage":"Wendet sie ihre kritische Schärfe, die sie sonst zeigt, auch auf die Botschaften des Mediums an?","rueckmeldung":[{"option":0,"text":"Widersprüche zu sammeln wirkt gründlich, und Belege zählen. Bisher fand sie aber für jeden Widerspruch eine neue Begründung; ein größerer Stapel ändert dieses Muster kaum und kann sich wie ein Angriff anfühlen."},{"option":1,"text":"Mehrere Stimmen haben oft Gewicht, und gemeinsam wirkt der Einwand stärker. Hier setzt es sie aber unter Druck und erzeugt genau die Überheblichkeit, die du vermeiden willst, ohne ihr Bedürfnis zu berühren."},{"option":3,"text":"Rücksicht auf ihre Trauer ist wichtig, und das Meiden kann deshalb behutsam wirken. Es gibt aber jede Hilfe auf. Kritik ist in der Trauer nicht grundsätzlich fehl am Platz, es kommt auf die Art an, wie du das Gespräch beginnst."}],"familie":"wohlwollend-verstehen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Internet Encyclopedia of Philosophy: Fallacies, Art. „Appeal to Authority“","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"url","kurz":"Kahan, D. M. u. a. (2013): Motivated Numeracy and Enlightened Self-Government (Working Paper)","oeffentlich":true,"url":"https://scholarsbank.uoregon.edu/items/e034d504-ed17-4e0c-a713-ac3f85a8187a/full","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"528ae7fbdeed99cb"}},{"id":"qx-f-032","clusterId":"F","werkstueckRef":"F.1.7","stufe":1,"question":"In einer Diskussion sagt jemand: „Eine Taschenuhr hat offensichtlich einen Uhrmacher. Lebewesen sind noch viel komplexer, also muss es auch für sie einen Designer geben.“ Welcher Einwand trifft den Schwachpunkt dieses Vergleichs am besten?","options":["Eine Uhr wird in einer einzigen Herstellungsphase fertig gebaut, Lebewesen entstehen dagegen über lange Zeiträume schrittweise durch Variation und Selektion; der Vergleich überträgt also die Entstehungsweise eines Objekts auf einen ganz anders ablaufenden Prozess.","Eine Uhr besteht aus Metall, Lebewesen bestehen dagegen aus organischen Stoffen; wer beide vergleicht, mischt also zwei Materialklassen, die sich grundsätzlich nicht gegenüberstellen lassen.","Eine Uhr erfüllt erkennbar einen Zweck, Lebewesen dagegen nicht; wer ihnen eine Funktion zuschreibt, deutet also menschliche Absichten in die Natur hinein, die dort gar nicht vorkommen.","Eine Uhr braucht einen Hersteller, weil sie eine Ursache haben muss; Lebewesen sind dagegen unverursacht und entstehen aus reinem Zufall, ohne dass irgendein Mechanismus wirkt."],"correctIndex":0,"explanation":"Eine Analogie trägt nur so weit, wie die verglichenen Dinge in dem Punkt übereinstimmen, auf den der Schluss sich stützt. Hier ist der entscheidende Punkt die Entstehungsweise: Eine Taschenuhr könnte in ihrer heutigen Form nicht aus winzigen, funktionsfähigen Vorformen herauswachsen, sie wird in einer Herstellungsphase fertig gebaut. Lebewesen entstehen dagegen über viele Generationen, weil zufällige Mutationen auftreten und die Selektion nicht-zufällig diejenigen bevorzugt, die sich besser fortpflanzen. Teilstrukturen können dabei zunächst andere Vorteile bieten und später in neue Funktionen eingebunden werden (Exaptation). Der Uhrmacher-Schluss setzt also stillschweigend voraus, dass Komplexität nur durch fertige Planung entsteht, und genau das ist der unbelegte Schritt. Die anderen Einwände greifen daneben: Der Materialunterschied ist für den Schluss unerheblich, Funktionen lassen sich an Organen sehr wohl feststellen, und Evolution ist gerade nicht reiner Zufall, denn Selektion ist nicht zufällig.","coreRule":"⚡ Prüfe bei jeder Analogie, ob die verglichenen Dinge in dem Punkt übereinstimmen, auf den der Schluss sich stützt.","beleg":"Werkstück F.1.7 (Kontext & Tiefe, Punkt 4; Abschnitt „Die Uhr im Garten“); Fn. gl-f-8 nur für Paleys Uhr-Analogie (Paley 1802, Kap. 1 und 3)","status":"entwurf","scenario":"","kurz":"Der Vergleich trägt nur, wenn Uhr und Lebewesen auf gleiche Weise entstehen: Eine Uhr wird fertig gebaut, Lebewesen haben sich über viele Generationen schrittweise entwickelt. Dass Komplexität nur durch Planung entstehen kann, setzt der Schluss stillschweigend voraus.","prueffrage":"Woran erkennt man bei einer Taschenuhr, dass ein Uhrmacher sie gebaut hat, und trifft dasselbe auf eine Katze zu?","rueckmeldung":[{"option":1,"text":"Metall und organische Stoffe unterscheiden sich tatsächlich, nur hängt der Schluss nicht am Material. Entscheidend ist, wie etwas entsteht, und dazu sagt der Stoffunterschied nichts. Verglichen werden kann auch über Materialgrenzen hinweg."},{"option":2,"text":"Wer Funktionen in der Natur sieht, deutet leicht Absichten hinein, das ist eine bekannte Gefahr. Die Funktion eines Organs lässt sich aber feststellen, und die Selektion erklärt sie ohne Absicht. Das Problem des Vergleichs liegt woanders."},{"option":3,"text":"Mutationen sind zwar zufällig, die Selektion ist es nicht: Sie bevorzugt, wer sich besser fortpflanzt. Von „unverursacht“ kann also keine Rede sein. Der Vergleich scheitert nicht an fehlender Ursache, sondern an der Art der Entstehung."}],"familie":"schluss-pruefen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Kitzmiller v. Dover Area School District, Memorandum Opinion vom 20.12.2005","oeffentlich":true,"url":"https://www.pamd.uscourts.gov/sites/pamd/files/opinions/04v2688d.pdf","seite":"S. 74–75, 80–81","abruf":"2026-10-12"},{"typ":"url","kurz":"University of California Museum of Paleontology: Understanding Evolution, „Misconceptions about evolution“","oeffentlich":true,"url":"https://evolution.berkeley.edu/teach-evolution/misconceptions-about-evolution/","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"cdefbcd858d890be"}},{"id":"qx-f-033","clusterId":"F","werkstueckRef":"F.1.7","stufe":2,"question":"Was ist an der Aussage sachlich falsch?","scenario":"Ein Mitschüler behauptet im Biologieunterricht: „Evolution ist doch reiner Zufall. So etwas Komplexes wie ein Auge kann nicht zufällig entstehen.“ Du willst herausfinden, ob die Behauptung überhaupt auf den tatsächlichen Mechanismus zielt.","options":["Er verwechselt Evolution mit der Entstehung des ersten Lebens: Wie die erste Zelle entstand, ist eine andere Frage als die Entwicklung der Arten danach.","Er verwechselt Evolution mit der Entwicklung einzelner Lebewesen: Nicht einzelne Individuen entwickeln sich im evolutionären Sinn, sondern Populationen über viele Generationen.","Er setzt Evolution mit Zufall gleich: Zufällige Mutationen treffen auf eine nicht-zufällige Auslese, die vorteilhafte Veränderungen anhäuft.","Er verwechselt Evolution mit einem Wettlauf zu immer größerer Komplexität: Die Auslese begünstigt, was in der jeweiligen Umwelt besser zurechtkommt."],"correctIndex":2,"explanation":"Der Fehler liegt in der Gleichsetzung von „Evolution“ mit „Zufall“. Der Prozess kombiniert zwei Teile: zufällige Mutation und nicht-zufällige Selektion. Natürliche Selektion filtert aus unzähligen Mutationen beständig diejenigen heraus, die den Fortpflanzungserfolg steigern. Über Millionen von Generationen entstehen so komplexe Anpassungen, ohne dass ein bewusster Designer nötig wäre. Biologische Systeme entstehen über lange Zeiträume und vielfältige Zwischenstufen, nicht in einem einzigen Schritt. Wer die Frage stellt, wie wahrscheinlich es ist, dass ein Auge rein zufällig entsteht, bekämpft daher ein Zerrbild der Evolution. Die Entstehung des ersten Lebens ist eine andere Frage, von der der Mitschüler gar nicht spricht. Dass sich Populationen und nicht einzelne Lebewesen entwickeln, stimmt, ändert aber nichts an seinem Denkfehler. Von einem Wettlauf zu mehr Komplexität ist ebenfalls keine Rede: Er behauptet Zufall, kein Ziel.","coreRule":"⚡ Mutation würfelt, Selektion sortiert: Das Ergebnis ist alles andere als Zufall.","beleg":"Werkstück F.1.7 (Kontext & Tiefe, Punkt 2: Zufällige Mutation, nicht-zufällige Selektion)","status":"entwurf","kurz":"Evolution ist nicht reiner Zufall: Zufällige Mutationen werden von einer nicht-zufälligen Auslese gefiltert, und über viele Generationen und Zwischenstufen häufen sich Anpassungen an. Wer fragt, wie wahrscheinlich ein Auge „per Zufall“ ist, bekämpft ein Zerrbild.","prueffrage":"Hat ein Tier mit einer schädlichen Veränderung dieselben Chancen auf Nachwuchs wie eines mit einer nützlichen?","rueckmeldung":[{"option":0,"text":"Die Entstehung des ersten Lebens ist tatsächlich eine eigene Frage. Der Mitschüler redet aber über die Entstehung eines Organs wie des Auges, also über die Zeit danach, und vermischt hier nichts."},{"option":1,"text":"Daran stimmt: Populationen entwickeln sich, nicht einzelne Lebewesen. Sein Einwand handelt aber gar nicht von Individuen, sondern von der angeblichen Zufälligkeit der Entstehung eines Auges. Der Fehler liegt woanders."},{"option":3,"text":"Daran stimmt: Selektion belohnt, was in der jeweiligen Umwelt besser zurechtkommt, und kein Ziel „mehr Komplexität“. Der Mitschüler unterstellt aber kein Ziel, er behauptet Zufall. Sein Denkfehler ist ein anderer."}],"familie":"auslese-statt-plan","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"University of California Museum of Paleontology: Understanding Evolution, „Misconceptions about evolution“ (Abschnitt „Evolution happens by chance“)","oeffentlich":true,"url":"https://evolution.berkeley.edu/teach-evolution/misconceptions-about-evolution/","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"bf986ffacae1a634"}},{"id":"qx-f-034","clusterId":"F","werkstueckRef":"F.1.7","stufe":3,"question":"Ein Podiumsredner sagt: „Wissenschaftliche Methodik hin oder her – ob eine Idee in den Biologieunterricht gehört, ist reine Geschmacksfrage. Wir stellen einfach beide Erklärungen gleichwertig nebeneinander und lassen die Schüler entscheiden.“ Die Idee, um die es geht: Bestimmte Strukturen seien so komplex, dass ein bewusster Designer sie geplant haben müsse. Welche Prüffrage trifft den Kern, ob die Idee als gleichwertige wissenschaftliche Alternative in den Lehrplan gehört?","options":["Lässt sich die Idee prüfen: Sagt sie etwas voraus, das sich beobachten oder widerlegen lässt, und wurden ihre prüfbaren Teilbehauptungen getestet?","Wer finanziert die Verbreitung der Idee, und welche Interessen verfolgen die Geldgeber damit, dass sie an Schulen vorkommt?","Fördert das Nebeneinander zweier Erklärungen im Unterricht das selbstständige Urteilen der Schüler besser als eine einzige Erklärung?","Lässt sich die Idee Schülern in einer Unterrichtsstunde verständlich und anschaulich erklären, ohne dass sie überfordert sind?"],"correctIndex":0,"explanation":"Ob etwas gleichwertige Wissenschaft ist, entscheidet die Prüfbarkeit. Eine Hypothese, die jeden Befund als weiteren Beleg deutet, ist nicht falsifizierbar, und die Beweislast liegt bei dem, der sie vorbringt. Prüfbar ist beim Designer-Argument nur die Teilbehauptung, bestimmte Strukturen seien „irreduzibel komplex“, also ohne jedes einzelne Teil nutzlos – und sie wurde geprüft: Beim bakteriellen Flagellum entspricht ein Teil der Bauteile denen des Typ-III-Sekretionssystems, das für sich allein voll funktionsfähig ist. Ein US-Bundesgericht urteilte 2005 im Fall Dover: Intelligent Design sei keine Wissenschaft und lasse sich von seinen kreationistischen Wurzeln nicht trennen; der Schulbezirk durfte es deshalb nicht im Biologieunterricht vorstellen lassen. Maßgeblich ist, ob die Idee prüfbar und damit wissenschaftlich ist. Wer die Verbreitung finanziert, zeigt Interessen, aber nicht, ob sich die Idee prüfen lässt. Ob ein Nebeneinander das Urteilen fördert, ist eine pädagogische Frage, die erst nach der Klärung des wissenschaftlichen Status zählt. Wie anschaulich sich die Idee erklären lässt, sagt nichts darüber, ob sie sich testen lässt.","coreRule":"⚡ Ob eine Idee als Wissenschaft gleichwertig neben anderen steht, entscheidet ihre Prüfbarkeit – nicht Beliebtheit, Weltbild-Verträglichkeit oder Lautstärke ihrer Vertreter.","beleg":"Werkstück F.1.7 (Anwendung & aktuelle Bedeutung, Wissenschaftspolitik; Der Kipppunkt); Fn. gl-f-kitzmiller (Kitzmiller v. Dover, 20.12.2005, S. 28 f., 64 und 136)","status":"entwurf","scenario":"","kurz":"Ob etwas als gleichwertige Wissenschaft gelten kann, hängt an der Prüfbarkeit. Naheliegend ist, nach Geschmack, Geldgebern oder Verständlichkeit zu fragen. Doch nur die Prüfbarkeit klärt, ob die Idee ins Fach gehört; die behauptete „Unreduzierbarkeit“ wurde getestet.","prueffrage":"Woran sollen die Schüler nach dem Vorschlag des Redners erkennen, welche der beiden Erklärungen zutrifft?","rueckmeldung":[{"option":1,"text":"Wer Interessen und Geldgeber betrachtet, wird zu Recht misstrauisch. Diese Frage sagt aber nur etwas über die Herkunft der Idee, nicht darüber, ob sie sich testen lässt; auch eine gut geprüfte Idee kann Geldgeber haben."},{"option":2,"text":"Selbstständiges Urteilen zu fördern ist ein gutes Ziel. Dieses Argument setzt aber schon voraus, dass beide Erklärungen wissenschaftlich gleichwertig sind, und genau das ist die offene Frage. Erst danach kommt die Pädagogik."},{"option":3,"text":"Verständlichkeit zählt im Unterricht durchaus. Eine Idee kann sich aber sehr anschaulich erklären lassen und trotzdem nicht prüfbar sein; ob sie wissenschaftlich ist, sagt das nicht."}],"familie":"wissenschaft-abgrenzen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Kitzmiller v. Dover Area School District, Memorandum Opinion vom 20.12.2005","oeffentlich":true,"url":"https://www.pamd.uscourts.gov/sites/pamd/files/opinions/04v2688d.pdf","seite":"S. 64, 76–77, 136","abruf":"2026-10-12"},{"typ":"url","kurz":"Thornton, S.: Karl Popper, Stanford Encyclopedia of Philosophy (Abschn. 2–3, Falsifizierbarkeit)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/popper/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"fb614ed747c76263"}},{"id":"qx-f-035","clusterId":"F","werkstueckRef":"F.1.7","stufe":4,"question":"Eine Verteidigerin einer Theorie sagt: „Findet man in den Gesteinsschichten eine Zwischenform, ist das ein Beleg für meine Theorie; findet man keine, ist es ebenfalls ein Beleg.“ Wo liegt das methodische Problem?","options":["Die Verteidigerin zählt nur die Funde, die zur Theorie passen, und lässt widersprechende Funde unerwähnt (Rosinenpickerei).","Die Verteidigerin beruft sich auf das Ansehen ihrer Theorie und deren Vertreter statt auf Befunde und begeht damit ein Autoritätsargument.","Die Verteidigerin stellt die Einwände der Gegenseite verzerrt dar, um sie leichter widerlegen zu können (Strohmann-Argument).","Die Verteidigerin legt die Theorie so aus, dass jeder denkbare Befund passt; sie sagt nichts voraus und kann deshalb nie scheitern."],"correctIndex":3,"explanation":"Eine Theorie, die sowohl den Fund als auch das Ausbleiben des Funds als Bestätigung verbucht, schließt keinen denkbaren Befund aus. Damit kann nichts sie widerlegen, und gerade deshalb prüft nichts sie. Wissenschaftliche Modelle sagen dagegen etwas voraus, das auch scheitern könnte: „Wenn die Theorie stimmt, dürfen wir X nicht finden.“ Wer jeden Ausgang als Treffer wertet, erklärt scheinbar alles, in Wahrheit aber nichts. Das Gegenmittel ist die Frage: „Welcher Befund würde dich umstimmen?“ Gibt es keinen, ist die Behauptung nicht prüfbar. Rosinenpickerei liegt hier nicht vor, denn sie wertet ja beide Ausgänge, nicht nur die passenden. Ein Autoritätsargument ist es auch nicht, da sie sich auf Funde bezieht und nicht auf Ansehen. Und von der Gegenseite ist im Satz gar keine Rede, sodass nichts verzerrt dargestellt wird.","coreRule":"⚡ Wer jeden Befund erklären kann, erklärt nichts: Ein prüfbares Modell muss etwas ausschließen.","beleg":"Werkstück F.1.7 (Kontext & Tiefe, Punkt 3: Beweislast und Falsifizierbarkeit; Red Flags)","status":"entwurf","scenario":"","kurz":"Wer Fund und Nichtfund gleichermaßen als Bestätigung verbucht, schließt keinen Befund aus und kann nie scheitern. So eine Theorie erklärt scheinbar alles, prüfbar wird sie erst durch eine Voraussage, die auch falsch sein könnte.","prueffrage":"Was weißt du nach ihrer Aussage über die Gesteinsschichten, das du vorher noch nicht wusstest?","rueckmeldung":[{"option":0,"text":"Rosinenpickerei liegt nahe, weil die Aussage einseitig klingt. Die Verteidigerin wertet aber beide Ausgänge, Fund wie Nichtfund, als Beleg; nichts bleibt unerwähnt. Das Problem liegt in der Auslegung, nicht in der Auswahl."},{"option":1,"text":"Das Beharren auf der eigenen Theorie erinnert an einen Verweis auf Autorität. Im Satz geht es aber ausdrücklich um Funde in den Gesteinsschichten, nicht um Ansehen. Die Schwäche liegt darin, dass jeder Befund passend gemacht wird."},{"option":2,"text":"Ein Strohmann setzt voraus, dass Einwände der Gegenseite verzerrt wiedergegeben werden. Im Satz kommt die Gegenseite gar nicht vor, es gibt also nichts, was verzerrt würde. Auffällig ist vielmehr, dass nichts die Theorie je widerlegen könnte."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Karl Popper (Abschn. 2 „Backdrop to Popper's Thought“, Abschn. 3 „The Problem of Demarcation“)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/popper/","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"a7582c821ecaa7ff"}},{"id":"qx-f-036","clusterId":"F","werkstueckRef":"F.2.1","stufe":1,"question":"Welche Prüfung zeigt am besten, ob die Aussage wirklich etwas Besonderes über deine Freundin verrät?","scenario":"Eine Freundin liest dir aus ihrem Tageshoroskop vor: „Du hast ein kreatives Potenzial, das noch nicht voll ausgeschöpft ist.“ Sie ist begeistert: „Das trifft genau auf mich zu! Das kann doch kein Zufall sein.“ Du willst herausfinden, ob die Aussage wirklich etwas über sie verrät.","options":["Fragen, ob dieselbe Aussage auch auf andere Menschen zutreffen würde, etwa auf ihre Kollegen und Nachbarn.","Prüfen, ob das Horoskop aus einer seriösen Quelle stammt und seine Autoren und Methoden offenlegt.","Klären, ob sie sich nur an die Treffer früherer Horoskope erinnert und die Fehlschläge längst vergessen hat.","Klären, ob deine Freundin ohnehin an Horoskope glaubt und deshalb eher einen Treffer in der Aussage sieht."],"correctIndex":0,"explanation":"Eine Aussage verrät nur dann etwas über eine bestimmte Person, wenn sie auf diese Person besser passt als auf andere. „Du hast ein kreatives Potenzial, das noch nicht voll ausgeschöpft ist“ ist eine typische Barnum-Aussage: vage, schmeichelhaft und universell genug, dass jeder sich darin wiedererkennt. Solche Sätze fühlen sich persönlich an, sind es aber nicht. Das Gefühl der Treffsicherheit ist deshalb kein Beleg. Entscheidend ist, ob die Aussage auch auf andere zutrifft. Die Herkunft des Horoskops ist eine berechtigte Frage der Quellenkritik, sagt aber nichts darüber, ob dieser eine Satz auf deine Freundin besser passt als auf andere. Die Erinnerung an frühere Treffer ist ein bekannter Fehler, betrifft hier aber nicht die vorgelesene Aussage, die sie gerade zum ersten Mal hört. Dass sie an Horoskope glaubt, erklärt ihre Begeisterung, zeigt aber nicht, ob die Aussage etwas über sie verrät.","coreRule":"⚡ Passt eine Aussage auf alle, sagt sie über niemanden etwas: Prüfe, ob sie auch auf andere zutreffen würde.","beleg":"Werkstück F.2.1 (Die Anatomie der Täuschung: Barnum-Effekt, B.10)","status":"entwurf","kurz":"Der Satz sagt nur dann etwas über deine Freundin, wenn er auf sie besser passt als auf andere. Er ist vage und schmeichelhaft genug, dass sich fast jeder darin wiedererkennt, und das Gefühl, er treffe genau, ist deshalb kein Beleg.","prueffrage":"Wer in deinem Bekanntenkreis würde von sich sagen, sein kreatives Potenzial sei schon voll ausgeschöpft?","rueckmeldung":[{"option":1,"text":"Nach der Herkunft zu fragen ist eine berechtigte Frage der Quellenkritik. Sie klärt aber nur, wer den Satz geschrieben hat, nicht, ob er auf deine Freundin besser passt als auf andere."},{"option":2,"text":"Selektive Erinnerung an Treffer ist ein bekannter Fehler und kann bei Horoskopen eine Rolle spielen. Hier geht es aber um einen Satz, den sie gerade zum ersten Mal hört, nicht um frühere Vorhersagen."},{"option":3,"text":"Ein Glaube an Horoskope könnte ihre Begeisterung erklären, denn wer etwas erwartet, sieht eher einen Treffer. Ob der Satz selbst etwas über sie verrät, bleibt damit aber offen: Das zeigt nur der Vergleich mit anderen."}],"familie":"passt-auf-jeden","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Carroll, R. T.: The Skeptic's Dictionary, Art. „Forer effect“","oeffentlich":true,"url":"https://skepdic.com/forer.html","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Forer, B. R. (1949): The fallacy of personal validation: a classroom demonstration of gullibility. Journal of Abnormal and Social Psychology 44(1), S. 118 ff.","oeffentlich":false}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"e317ea40c7d2582b"}},{"id":"qx-f-037","clusterId":"F","werkstueckRef":"F.2.1","stufe":2,"question":"Ein Astrologe behauptet: „Die Schwerkraft der Planeten prägt den Charakter eines Menschen bei der Geburt.“ Welcher Einwand trifft diese Behauptung am stärksten?","options":["Ein Körper im selben Raum, etwa der Geburtshelfer, zieht das Neugeborene ähnlich stark oder stärker an als der Mars. Wäre Schwerkraft der Mechanismus, bestimmte der Geburtshelfer das Horoskop mit.","Das Licht der Fixsterne ist bei der Geburt viel zu schwach, um messbar auf ein Neugeborenes zu wirken. Eine Prägung des Charakters durch Sternenstrahlung ist deshalb nicht plausibel.","Die Sternbilder des Tierkreises haben sich seit der Antike durch die Präzession verschoben. Die heutigen Tierkreiszeichen passen deshalb nicht mehr zu den Sternbildern am Himmel.","Die Sterne eines Sternbilds liegen weit auseinander und gehören nur aus Sicht der Erde zusammen. Ein Sternbild bildet deshalb keine reale Einheit, die einen Charakter prägen könnte."],"correctIndex":0,"explanation":"Der Einwand prüft, ob die behauptete Ursache überhaupt ausreicht: Die Anziehung des Geburtshelfers neben der Mutter liegt je nach Marsstellung und Abstand in derselben Größenordnung wie die des Planeten oder deutlich darüber, und seine Gezeitenwirkung übertrifft die des Mars um viele Größenordnungen. Wäre Schwerkraft der Mechanismus, müsste das Horoskop also mindestens ebenso vom Geburtshelfer abhängen wie vom Planeten. Das ist offensichtlich nicht gemeint, also taugt die Schwerkraft nicht als Erklärung. Das schwache Licht der Fixsterne ist zutreffend, betrifft aber nicht die Schwerkraft der Planeten, auf die sich der Astrologe beruft. Die Verschiebung der Sternbilder ist real, betrifft aber die Zuordnung der Zeichen und nicht die Frage, ob Schwerkraft als Ursache reicht. Dass die Sterne eines Sternbilds nur scheinbar zusammengehören, ist eine berechtigte Kritik an den Sternbildern, sagt aber nichts über die Schwerkraft der Planeten.","coreRule":"⚡ Eine behauptete Ursache muss stärker sein als naheliegende Alternativen im selben Raum. Sonst taugt sie nicht als Erklärung.","beleg":"Werkstück F.2.1 (Die Konfrontation mit der Realität: Verletzung der Physik)","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Wenn Schwerkraft der Mechanismus wäre, müsste der Geburtshelfer im Raum das Horoskop mindestens ebenso mitbestimmen wie der ferne Mars. Das ist offensichtlich nicht gemeint, also reicht die behauptete Ursache nicht aus. Die Stärke der Wirkung wird gar nicht geprüft.","prueffrage":"Wovon hängt ab, wie stark ein Körper ein Neugeborenes anzieht, und wie ändert sich das mit der Entfernung?","rueckmeldung":[{"option":1,"text":"Dass Fixsternlicht bei der Geburt kaum etwas bewirkt, stimmt. Die Behauptung beruft sich aber auf die Schwerkraft der Planeten, nicht auf Sternenlicht. Der Einwand trifft also einen anderen Mechanismus als den genannten."},{"option":2,"text":"Die Verschiebung der Sternbilder durch die Präzession ist real, betrifft aber die Zuordnung der Zeichen zu den Sternbildern. Ob Schwerkraft überhaupt als Ursache ausreicht, bleibt dabei unberührt."},{"option":3,"text":"Die Sterne eines Sternbilds gehören tatsächlich nur aus Sicht der Erde zusammen, das ist eine berechtigte Kritik an Sternbildern. Die Behauptung spricht aber von den Planeten und ihrer Schwerkraft, nicht von Sternbildern."}],"familie":"sparsamste-erklaerung","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Universe Today: „Debunking Astrology: Mars Can't Influence You“","oeffentlich":true,"url":"https://universetoday.com/articles/debunking-astrology-mars-cant-influence-you","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"71c48305a236ec8f"}},{"id":"qx-f-038","clusterId":"F","werkstueckRef":"F.2.1","stufe":3,"question":"Du kritisierst: „Wegen der Präzession passt dein Sternzeichen nicht mehr zu dem Sternbild, in dem die Sonne bei deiner Geburt tatsächlich stand.“ Ein Astrologe entgegnet: „Mein Tierkreis richtet sich bewusst nach den Jahreszeiten, gezählt ab dem Frühlingsanfang, nicht nach den Sternbildern.“ Wie bewertest du diese Antwort?","options":["Sie beantwortet den Einwand, aber dann deutet die Astrologie streng genommen nicht mehr die Sterne, sondern den Kalender.","Sie ist ein Zirkelschluss, denn sie begründet den Tierkreis mit genau der Wirkung, die erst bewiesen werden müsste.","Sie ist ein bloßes Autoritätsargument, denn sie beruft sich auf das Alter der Astrologie statt auf Gründe.","Sie bestreitet die Präzession, obwohl diese astronomisch gesichert ist, und scheitert deshalb an den Tatsachen."],"correctIndex":0,"explanation":"Die Verteidigung ist in sich stimmig: Ein tropischer Tierkreis wird von Frühlingspunkt zu Frühlingspunkt gezählt und ist damit an die Jahreszeiten gebunden, nicht an die Sternbilder. Der Einwand der Präzession trifft ihn deshalb nicht. Aber die Antwort hat einen Preis: Wenn sich die Zeichen nach dem Kalender richten, ordnet die Astrologie Menschen nach dem Datum und nicht nach der Stellung der Himmelskörper. Damit fällt auch die Behauptung, die Sterne selbst hätten einen Einfluss. Eine Verteidigung, die den ursprünglichen Gegenstand aufgibt, hat den Streitpunkt nicht gewonnen, sondern verlagert. Die Antwort setzt keine Wirkung voraus, die erst zu beweisen wäre, sie legt nur fest, woran der Tierkreis gebunden ist; ein Zirkelschluss liegt also nicht vor. Sie beruft sich auch nicht auf Alter oder Tradition, sondern nennt eine bestimmte Zählweise. Und sie leugnet die Präzession nicht, sondern nimmt sie auf.","coreRule":"⚡ Wer den Himmel gegen den Kalender tauscht, hat die Sterne aus der Astrologie gestrichen.","beleg":"Werkstück F.2.1 (Verletzung der Astronomie); Fn. gl-f-tropisch (Carroll 2003, Skeptic's Dictionary, Art. astrology)","status":"entwurf","scenario":"Du diskutierst mit einem Astrologen über die Verschiebung der Sternbilder seit der Antike.","quote":"","quoteLabel":"","kurz":"Der Astrologe weicht dem Einwand stimmig aus, denn ein an den Frühlingspunkt gebundener Tierkreis wird von der Präzession nicht berührt. Der Preis: Dann ordnet er Menschen nach dem Datum, nicht nach den Sternen, und der Gegenstand ist verlagert statt verteidigt.","prueffrage":"Welches Zeichen hätte nach diesem Tierkreis jemand, der heute am selben Kalendertag geboren wird wie jemand vor 2000 Jahren?","rueckmeldung":[{"option":1,"text":"Ein Zirkelschluss würde die Wirkung schon voraussetzen, um sie zu belegen. Der Astrologe legt aber nur fest, woran sein Tierkreis gebunden ist. Ob die Zeichen etwas bewirken, bleibt offen, das ist jedoch eine andere Frage als die nach der Form dieser Antwort."},{"option":2,"text":"Bei Astrologie liegt der Verdacht auf „Das war schon immer so“ nahe. Hier wird aber weder Alter noch Tradition angeführt, sondern eine konkrete Zählweise genannt: vom Frühlingspunkt aus, gebunden an die Jahreszeiten. Das ist ein Grund, auch wenn er seinen eigenen Preis hat."},{"option":3,"text":"Die Präzession ist astronomisch gesichert, das stimmt. Der Astrologe leugnet sie aber nicht, er nimmt sie auf, indem er den Tierkreis an die Jahreszeiten statt an die Sternbilder bindet. Daran scheitert die Antwort nicht, ihr Problem liegt an anderer Stelle."}],"familie":"mechanismus-verlangen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Carroll, R. T.: The Skeptic's Dictionary, Art. „astrology“","oeffentlich":true,"url":"https://skepdic.com/astrology.html","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"c511ebb2bd64ff11"}},{"id":"qx-f-039","clusterId":"F","werkstueckRef":"F.2.1","stufe":4,"question":"Welche Testanordnung prüft die Behauptung der Astrologin am fairsten?","options":["Die Astrologin führt vorab mit jeder Person ein kurzes Gespräch, um sie besser einzuschätzen, und ordnet danach Horoskop und Charakterbild zu.","Die Astrologin ordnet Horoskope den Persönlichkeitsprofilen zu, und was als Treffer zählt, legt man erst nach Sicht der Ergebnisse gemeinsam mit ihr fest.","Die Astrologin deutet Horoskope von zufällig ausgewählten Freiwilligen, und diese bewerten anonym auf einer Skala, wie gut die Deutung zu ihnen passt.","Die Astrologin ordnet Horoskope den passenden Persönlichkeitsprofilen zu, und weder sie noch die Testleitung wissen währenddessen, welche Zuordnung richtig ist."],"correctIndex":3,"explanation":"Ein fairer Test muss ausschließen, dass etwas anderes als das Horoskop die Treffer erzeugt. Im Doppelblindtest kennt niemand die Lösung, sodass Erwartung und Vorwissen ausscheiden und nur zählt, ob mehr als der Zufall herauskommt. Genau so ein Test fand statt: Carlson ließ Astrologen Horoskope den passenden Persönlichkeitsprofilen zuordnen, und die Trefferquote betrug 0,34 bei einer Zufallsquote von 0,33. Ein anderer Test mit „Zeitzwillingen“ (gut 2.000 Londoner, geboren im März 1958) zeigte ebenfalls keine Ähnlichkeit über den Zufall hinaus: Sie ähnelten ihren Zeitzwillingen in Intelligenz, Verhalten und Körpermerkmalen nicht stärker als beliebigen anderen Menschen. Eine Bewertung durch die Gedeuteten klingt fair, lässt aber den Barnum-Effekt zu: Vage Aussagen passen fast immer. Ein Gespräch vorab liefert Hinweise auf den Charakter und prüft damit nicht das Horoskop. Treffer erst nach Sicht der Ergebnisse festzulegen begünstigt den Bestätigungsfehler.","coreRule":"⚡ Fair testen heißt blind testen: Wer Vorwissen oder Bewertung in der Hand hat, misst seine Erwartung, nicht die Behauptung.","beleg":"Werkstück F.2.1 (Das Zwillings-Problem); Fn. gl-f-astrotests (Carlson 1985, Nature 318, S. 419--425; Dean, Kelly 2003)","status":"entwurf","scenario":"Eine Astrologin behauptet: „Ich erkenne den Charakter eines Menschen an seinem Horoskop, auch wenn ich ihn nie getroffen habe.“ Ein Skeptiker will das prüfen, ohne dass das Ergebnis durch Erwartungen, Vorwissen oder Wohlwollen verzerrt wird. Er schlägt vier Testanordnungen vor.","kurz":"Fair ist der Test, wenn niemand die Lösung kennt: Dann scheiden Erwartung und Vorwissen aus, und es zählt nur, ob mehr als der Zufall herauskommt. Der naheliegende Fehler ist, einen Test schon für fair zu halten, weil er neutral wirkt.","prueffrage":"Woher könnte in jeder der vier Anordnungen ein Treffer kommen, wenn Horoskope gar nichts über den Charakter verraten?","rueckmeldung":[{"option":0,"text":"Ein Gespräch macht die Zuordnung leichter, aber nicht deshalb, weil das Horoskop etwas verrät. Treffer könnten aus dem stammen, was man im Gespräch bemerkt, und die Behauptung, den Charakter ohne Treffen zu erkennen, bliebe ungeprüft."},{"option":1,"text":"Dass die Astrologin bei der Auswertung mitredet, wirkt fair. Wird aber erst nach Sicht der Ergebnisse festgelegt, was als Treffer zählt, lässt sich fast jedes Ergebnis passend deuten. Das begünstigt den Bestätigungsfehler."},{"option":2,"text":"Eine anonyme Bewertung durch die Gedeuteten klingt unparteiisch. Vage Aussagen passen aber fast immer zu jedem, auch zu Fremden (Barnum-Effekt), und ohne Zufallsvergleich sagt eine hohe Passung wenig."}],"familie":"fair-testen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Carlson, S. (1985): A double-blind test of astrology. Nature 318, S. 419–425","oeffentlich":false,"doi":"10.1038/318419a0"},{"typ":"url","kurz":"Dean, G.; Kelly, I. W. (2003): Is Astrology Relevant to Consciousness and Psi? (Webfassung)","oeffentlich":true,"url":"https://www.astrology-and-science.com/D-psia2.htm","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"66cddd1ecaf87901"}},{"id":"qx-f-040","clusterId":"F","werkstueckRef":"F.2.2","stufe":1,"question":"Welche Frage prüft die Behauptung „Je stärker verdünnt und geschüttelt, desto stärker die Wirkung“ am besten auf Plausibilität?","options":["Wie viel von der Ausgangssubstanz steckt bei dieser Verdünnung noch im Fläschchen, und wodurch soll dann eine Wirkung entstehen?","Wer stellt das Mittel her, und hat der Hersteller ein wirtschaftliches Interesse daran, dass möglichst viele Menschen es kaufen?","Ist das Fläschchen vorschriftsmäßig beschriftet, und stimmen Chargennummer und Haltbarkeitsdatum mit den Angaben des Herstellers überein?","Welche Nebenwirkungen sind bei dem Mittel bekannt, und für welche Personengruppen wäre die Einnahme gefährlich oder ungeeignet?"],"correctIndex":0,"explanation":"Eine Wirkbehauptung prüft man zuerst an ihrem Mechanismus: Soll eine Substanz wirken, muss sie in der Lösung auch vorhanden sein. Bei C30 beträgt der Verdünnungsfaktor 10^60; statistisch ist kein einziges Molekül der Ausgangssubstanz mehr zu erwarten, schon ab etwa C12 ist die Avogadro-Grenze überschritten. Außerdem beruht die Pharmakologie auf der Dosis-Wirkungs-Beziehung: Mehr Wirkstoff bewirkt mehr Wirkung (bis zu einem Sättigungs- oder Giftigkeitspunkt), nicht weniger. „Mehr Verdünnung, mehr Wirkung“ widerspricht dem und kommt ohne plausiblen Mechanismus aus. Wer das Mittel herstellt und was er daran verdient, ist eine berechtigte Frage der Quellenkritik, klärt aber nicht, ob eine Wirkung möglich ist. Beschriftung, Chargennummer und Haltbarkeit zeigen Produktqualität, nicht Wirksamkeit. Bekannte Nebenwirkungen betreffen die Sicherheit und sagen nichts darüber, ob die Behauptung physikalisch plausibel ist.","coreRule":"⚡ Prüfe bei jeder Wirkbehauptung zuerst den Mechanismus: Ist der behauptete Wirkstoff überhaupt vorhanden, und passt die Behauptung zur Dosis-Wirkungs-Beziehung?","beleg":"Werkstück F.2.2 (Die Kern-Behauptung); Fn. gl-f-9 (Hahnemann 1796, Hufelands Journal Bd. 2, S. 433)","status":"entwurf","scenario":"Ein Bekannter schwärmt von seinem Globuli-Fläschchen mit der Aufschrift C30. Er sagt: „Je mehr das Mittel verdünnt und geschüttelt wird, desto stärker wirkt es.“","kurz":"Wenn die Wirkung von der Substanz kommen soll, muss sie im Fläschchen vorhanden sein. Bei C30 ist statistisch kein Molekül mehr zu erwarten. „Mehr Verdünnung, mehr Wirkung“ kehrt zudem die Dosis-Wirkungs-Beziehung um.","prueffrage":"Was würde mit der Wirkung einer Kopfschmerztablette geschehen, wenn man sie immer weiter mit Wasser verdünnt?","rueckmeldung":[{"option":1,"text":"Wer ein Mittel verkauft, hat meist ein Interesse am Absatz, und diese Quellenkritik ist berechtigt. Sie sagt aber nur, wem man misstrauen könnte, nicht, ob eine Wirkung überhaupt möglich ist."},{"option":2,"text":"Ordentliche Beschriftung, Chargennummer und Haltbarkeit zeigen, wie sorgfältig produziert wurde. Ob die Behauptung stimmt, sagen sie nicht, denn ein tadellos etikettiertes Fläschchen kann trotzdem wirkungslos sein."},{"option":3,"text":"Nebenwirkungen und ungeeignete Personengruppen sind für die Sicherheit wichtig. Die Behauptung handelt aber von der Stärke der Wirkung, und die Frage lässt offen, ob so ein Mittel überhaupt etwas bewirken kann."}],"familie":"verduennung-nachrechnen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"apotheken.de (Deutscher Apotheker Verlag): „Grundlagen der Homöopathie“ (nach Renz-Polster/Escher, Gesundheit heute)","oeffentlich":true,"url":"https://www.apotheken.de/sondertext/33c22-potenzierung","abruf":"2026-10-12"},{"typ":"doi","kurz":"Rademacher, P. (2013): Die Mär vom Wasser mit Gedächtnis. Chemie in unserer Zeit 47(1), S. 24–31","oeffentlich":false,"doi":"10.1002/ciuz.201300580"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"fef0ce56d5649dee"}},{"id":"qx-f-041","clusterId":"F","werkstueckRef":"F.2.2","stufe":2,"question":"Was kannst du der Freundin aus chemischer Sicht zum Inhalt des Fläschchens sagen?","scenario":"Eine Freundin schwärmt von ihren Globuli: „Auf dem Fläschchen steht C30, das sind hochwirksame Spuren des Heilstoffs, nur eben sehr fein dosiert.“ Du erinnerst dich: Eine Verdünnung um den Faktor 10 hoch 60 ist weit jenseits der Grenze, ab der in einer Lösung statistisch kein einziges Molekül des Ausgangsstoffs mehr zu erwarten ist (Avogadro-Konstante, Größenordnung C12).","options":["Es sind noch winzige, kaum messbare Spuren der Ursubstanz enthalten, weil bei jeder Verdünnung ein kleiner Rest im Wasser zurückbleibt.","Es ist genau ein Molekül der Ursubstanz enthalten, weil die Bezeichnung C30 für ein Verhältnis von einem Teil auf dreißig Teile steht.","Es ist statistisch kein Molekül der Ursubstanz mehr enthalten, weil die Verdünnung weit über die Grenze hinausgeht, ab der ein Molekül je Fläschchen zu erwarten wäre.","Es ist mehr Wirkstoff enthalten als bei einer Verdünnung um C12, weil die Konzentration beim Schütteln mit jedem Schritt wieder ansteigt."],"correctIndex":2,"explanation":"Eine C30-Verdünnung bedeutet einen Verdünnungsfaktor von 100^30 = 10^60, nicht „eins zu dreißig“. Die Avogadro-Grenze liegt bei D24 bzw. C12: Ab dort ist statistisch kein Molekül der Ausgangssubstanz mehr zu erwarten (rechnerisch 0,6 Moleküle je Mol Endprodukt). C30 liegt weit jenseits dieser Grenze. Niedrigpotenzen wie D6 bis D12 enthalten noch Spuren des Ausgangsstoffs, Hochpotenzen wie C30 statistisch keines mehr. Dass die Konzentration beim Verdünnen und Schütteln wieder ansteigt, widerspricht der Arithmetik: Potenzieren bedeutet schrittweises Verdünnen, nicht Aufkonzentrieren. Chemisch ist das Fläschchen Zucker und Wasser (Rademacher 2013).","coreRule":"⚡ Ab etwa C12 ist statistisch kein Wirkstoffmolekül mehr zu erwarten: Rechne die Verdünnung in Teilchen um, bevor du von „Spuren“ sprichst.","beleg":"Werkstück F.2.2 (Verletzung der Chemie); Fn. gl-f-tiefpotenzen (Rademacher 2013, S. 25--26); Fn. gl-f-10","status":"entwurf","kurz":"Eine C30-Verdünnung heißt 100^30 = 10^60, weit jenseits der Grenze von etwa C12, ab der statistisch kein einziges Molekül des Ausgangsstoffs mehr zu erwarten ist. „Hochwirksam“ klingt nach Stärke, bedeutet hier aber rechnerisch: nichts mehr drin.","prueffrage":"Welche Zahl steht hinter „C30“, und wie viele Moleküle des Ausgangsstoffs ergäbe das in einem Fläschchen?","rueckmeldung":[{"option":0,"text":"Bei Niedrigpotenzen wie D6 bis D12 bleiben tatsächlich noch Spuren zurück. Bei C30 wurde aber dreißigmal hintereinander hundertfach verdünnt; der „kleine Rest“ schrumpft dabei jedes Mal und liegt rechnerisch weit unter einem Molekül."},{"option":1,"text":"Die Bezeichnung klingt nach „eins zu dreißig“, steht aber für dreißig Verdünnungsschritte von je 1 zu 100, zusammen 1 zu 10^60. Selbst aus einem ganzen Mol Ausgangsstoff bliebe rechnerisch weit weniger als ein Molekül übrig."},{"option":3,"text":"Beim Schütteln wird nur durchmischt, nichts aufkonzentriert. Jeder Schritt verdünnt weiter, deshalb enthält C30 weniger Ausgangsstoff als C12, nicht mehr; „potenziert“ heißt hier schrittweise verdünnt, nicht verstärkt."}],"familie":"verduennung-nachrechnen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"apotheken.de (Deutscher Apotheker Verlag): „Grundlagen der Homöopathie“","oeffentlich":true,"url":"https://www.apotheken.de/sondertext/33c22-potenzierung","abruf":"2026-10-12"},{"typ":"doi","kurz":"Rademacher, P. (2013): Die Mär vom Wasser mit Gedächtnis. Chemie in unserer Zeit 47(1), S. 24–31","oeffentlich":false,"doi":"10.1002/ciuz.201300580"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"0ea8e12ba536db00"}},{"id":"qx-f-042","clusterId":"F","werkstueckRef":"F.2.2","stufe":3,"question":"Was folgt aus diesem Muster am ehesten?","options":["Der Nutzen zeigt sich nur in den weniger sauberen Studien. Das spricht dafür, dass die positiven Ergebnisse auf Verzerrung beruhen und nicht auf einer echten Wirkung.","Alle Studien untersuchten nur Kinder, nicht Erwachsene. Das spricht dafür, dass die Ergebnisse nur für Kinder gelten und das Muster eine Besonderheit dieser Altersgruppe ist.","Ein nachweisbarer Unterschied muss nicht bedeutsam sein. Das spricht dafür, dass die positiven Studien zwar eine Wirkung zeigen, diese für Kinder aber kaum praktische Bedeutung hat.","Mit 1.813 Kindern ist die Datenbasis zu klein für gesicherte Aussagen. Das spricht dafür, dass das Muster erst mit deutlich mehr Studien belastbar wird."],"correctIndex":0,"explanation":"Entscheidend ist das Muster: Die Studien mit geringem Verzerrungsrisiko finden keinen Nutzen, positive Ergebnisse stammen ausschließlich aus Studien mit unklarem oder hohem Risiko. Genau das erwartet man, wenn es keine echte Wirkung gibt. Positive Ergebnisse entstehen dann durch Verzerrung im Studienaufbau, etwa durch fehlende Verblindung oder unsaubere Zuteilung, oder durch Zufall. Gäbe es eine echte Wirkung, müsste sie sich auch in den sauber durchgeführten Studien zeigen. Dieser Befund ist ein Beispiel dafür, wie man bei einem Evidenzkörper nicht nur zählt, wie viele Studien positiv ausfallen, sondern auch fragt, wie belastbar sie sind. Er gilt für diese Altersgruppe und diese Beschwerden und ersetzt keine ärztliche Beratung. Dass alle Studien Kinder betrafen, begrenzt, auf wen man das Ergebnis übertragen kann, erklärt aber nicht, warum die Ergebnisse nach Studienqualität und nicht nach Alter variieren. Ob ein Unterschied bedeutsam wäre, ist eine andere Frage; hier verschwindet der Nutzen bei sauberer Messung ganz. Zur Datenmenge sagt das Muster nichts: Es ergibt sich aus der Sortierung nach Studienqualität, nicht aus der Zahl der Kinder.","coreRule":"⚡ Wenn der Nutzen mit der Studienqualität verschwindet, spricht das gegen eine echte Wirkung.","beleg":"Werkstück F.2.2 (Abschluss-Diagnose); Fn. gl-f-homoeopathie-evidenz (Hawke u. a. 2022, Cochrane CD005974)","status":"entwurf","scenario":"Eine Übersichtsarbeit fasst elf Studien mit insgesamt 1.813 Kindern zusammen, die ein homöopathisches Mittel gegen akute Atemwegsinfekte testen. Die Autoren sortieren die Studien danach, wie anfällig ihr Aufbau für Verzerrungen ist (z. B. fehlende Verblindung oder unsaubere Zuteilung der Kinder auf die Gruppen). Dabei zeigt sich ein Muster: Alle Studien mit sauberem Aufbau finden keinen Nutzen. Positive Ergebnisse stammen ausschließlich aus Studien mit unklarem oder hohem Verzerrungsrisiko.","kurz":"Wenn der Nutzen nur dort auftaucht, wo der Aufbau Verzerrung zulässt, und bei sauberer Messung verschwindet, passt das zu einer Scheinwirkung. Eine echte Wirkung müsste sich auch in den sauberen Studien zeigen.","prueffrage":"Wie fallen die Ergebnisse aus, wenn du die Studien nach der Sauberkeit ihres Aufbaus ordnest, statt sie nur zu zählen?","rueckmeldung":[{"option":1,"text":"Dass alle Studien nur Kinder betrafen, begrenzt tatsächlich, auf wen sich das Ergebnis übertragen lässt. Das Muster verläuft aber nach Studienqualität, nicht nach Alter: Alle Studien hatten dieselbe Altersgruppe und trotzdem unterschiedliche Ergebnisse."},{"option":2,"text":"Ob ein Unterschied praktisch bedeutsam ist, ist eine berechtigte Frage, aber erst, wenn es einen echten Unterschied gibt. Hier verschwindet der Nutzen in den sauberen Studien ganz, die Wirkung ist also gar nicht belegt."},{"option":3,"text":"Eine kleine Datenbasis kann Aussagen tatsächlich unsicher machen. Das Muster hier ergibt sich aber aus der Sortierung nach Studienqualität, nicht aus der Zahl der Kinder. Mehr unsaubere Studien würden daran nichts ändern."}],"familie":"studie-genau-lesen","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Hawke, K.; King, D.; van Driel, M. L.; McGuire, T. M. (2022): Homeopathic medicinal products for preventing and treating acute respiratory tract infections in children. Cochrane Database of Systematic Reviews, CD005974.pub6 (frei in PMC9746041)","oeffentlich":true,"doi":"10.1002/14651858.CD005974.pub6","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC9746041/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"c62808be4eb6b80f"}},{"id":"qx-f-043","clusterId":"F","werkstueckRef":"F.2.2","stufe":4,"question":"Was ist an der Argumentation des Verkäufers der rhetorische Kniff?","scenario":"Ein Verkäufer sagt: „Dieses C200-Globuli heilt deine Lungenentzündung.“ Eine Ärztin wendet ein, dass in C200-Globuli kein einziges Molekül des Wirkstoffs mehr enthalten ist und es keinen Wirksamkeitsnachweis gibt. Der Verkäufer antwortet: „Naja, Homöopathie ist eben ganzheitlich und regt die Selbstheilungskräfte an.“","options":["Er begründet die Wirkung der Globuli mit der Wirkung der Globuli und setzt damit voraus, was er zeigen will.","Er unterstellt der Ärztin eine Behauptung, die sie nie aufgestellt hat, und widerlegt dann diese.","Er zieht sich unter Kritik von der kühnen Heilbehauptung auf eine bescheidene, kaum widerlegbare Aussage zurück.","Er greift die Person der Ärztin an, statt auf ihre sachlichen Einwände einzugehen."],"correctIndex":2,"explanation":"Zuerst steht eine mutige, überprüfbare Behauptung im Raum: Die Globuli heilen eine Lungenentzündung. Sobald Kritik kommt, wechselt der Verkäufer zu einer weichen Aussage („ganzheitlich“, „regt Selbstheilungskräfte an“), die so vage ist, dass sie sich kaum widerlegen lässt. Die Kritik der Ärztin zielte aber auf die erste Behauptung, und die bleibt unbeantwortet. Ein Zirkelschluss liegt nicht vor, denn er begründet nichts mit sich selbst. Ein Strohmann scheidet aus, weil er der Ärztin nichts Falsches in den Mund legt. Ein Angriff auf die Person fehlt ebenfalls. Entscheidend ist der Rückzug von der kühnen auf die bescheidene Behauptung, die man auch „Motte-and-Bailey“ nennt: Hinter dem Rückzug steht die Hoffnung, dass das Publikum später wieder die große Behauptung im Kopf hat.","coreRule":"⚡ Erst die große Behauptung, bei Gegenwind der Rückzug auf eine bescheidene, kaum angreifbare Aussage.","beleg":"Werkstück F.2.2 (Die Anatomie der Täuschung: Motte-and-Bailey)","status":"entwurf","kurz":"Aus der kühnen, prüfbaren Heilbehauptung wird unter Kritik eine vage Aussage, die kaum zu widerlegen ist. Der Einwand der Ärztin zielte auf die erste Behauptung, und genau die bleibt unbeantwortet.","prueffrage":"Auf welche Behauptung bezog sich der Einwand der Ärztin, und beantwortet die Reaktion des Verkäufers genau diese?","rueckmeldung":[{"option":0,"text":"„Ganzheitlich“ und „Selbstheilungskräfte“ klingen, als würde die Wirkung nur mit anderen Worten wiederholt. Der Verkäufer begründet aber nichts mit sich selbst, er weicht auf eine vagere Aussage aus; eine Begründung, die im Kreis läuft, fehlt."},{"option":1,"text":"Ein Strohmann braucht eine verzerrte Fassung dessen, was die andere Seite gesagt hat. Die Ärztin wird aber weder falsch wiedergegeben noch widerlegt. Ihr Einwand wird schlicht übergangen."},{"option":3,"text":"Den Einwand zu übergehen, ist noch kein Angriff auf die Person. Der Verkäufer wertet die Ärztin weder ab noch greift er ihre Kompetenz oder ihre Motive an. Er wechselt das Thema und lässt die Sachfrage offen."}],"familie":"rueckzug-auf-harmloses","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Shackel, N. (2014): „Motte and Bailey Doctrines“. Practical Ethics, Oxford Uehiro Centre, 05.09.2014","oeffentlich":true,"url":"https://blog.uehiro.ox.ac.uk/2014/09/motte-and-bailey-doctrines/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Shackel, N. (2005): The Vacuity of Postmodernist Methodology. Metaphilosophy 36(3)","oeffentlich":false}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"a368fbee9daa085f"}},{"id":"qx-f-044","clusterId":"F","werkstueckRef":"F.2.3","stufe":1,"question":"Ein Forscherteam will ein Tier aufspüren, dessen Existenz bisher unbelegt ist. Welches Vorhaben ist ein seriöser Versuch der Entdeckung und keine bloße Monsterjagd?","options":["Ein Team untersucht in einem kaum erforschten Waldgebiet Hinweise auf ein unbekanntes Tier und will das Tier selbst oder eindeutiges Probenmaterial beschaffen.","Ein Team reist in ein kaum erforschtes Waldgebiet und will aus übereinstimmenden Berichten von Dorfbewohnern auf die Existenz eines Tieres schließen.","Ein Team stellt in einem kaum erforschten Tal Kamerafallen für ein tonnenschweres Raubtier auf, dessen Bestand die dortige Beute nie ernähren könnte.","Ein Team sucht in einem gut erforschten Schutzgebiet mit dichtem Kameranetz seit Jahren nach einem großen Raubtier und rechnet fest mit Belegen."],"correctIndex":0,"explanation":"Dass Gorilla, Okapi und Riesenkalmar einst als Legenden galten, zeigt nur, dass die Welt früher weniger erforscht war. Es sagt nichts darüber, ob ein bestimmtes Tier heute existiert. Entscheidend sind zwei Fragen: Wie plausibel ist die Behauptung nach dem bekannten biologischen Wissen, und wie gut sind die Beweise? Ein Vorhaben ist seriös, wenn es in wirklich unerforschtem Gebiet nach einem Tier mit plausiblen Hinweisen sucht und handfeste, prüfbare Belege anstrebt, etwa einen Kadaver, DNA oder klare Filmaufnahmen. In gut erforschten Gebieten ist eine unbemerkte, überlebensfähige Population eines großen Tieres ohne jede eindeutige Spur äußerst unwahrscheinlich. Berichte von Einheimischen sind ein guter Anfang, ersetzen aber nie handfeste Belege. Kamerafallen sind ein sinnvolles Werkzeug, helfen aber nicht bei einem Tier, das dort biologisch gar nicht überleben könnte. Ein dichtes Kameranetz, das seit Jahren nichts zeigt, spricht eher dagegen, dass dort noch etwas zu finden ist.","coreRule":"⚡ Nicht die Seltsamkeit des Tieres, sondern Plausibilität und Beweisqualität trennen Suche von Jagd.","beleg":"Werkstück F.2.3 (Die Konfrontation mit der Realität: Die legitime Grenzwissenschaft); Fn. gl-f-okapi, gl-f-kalmar","status":"entwurf","scenario":"Vier Teams planen Expeditionen. Alle berufen sich darauf, dass Gorilla, Okapi und Riesenkalmar einst als Legenden galten und später doch wissenschaftlich beschrieben wurden. Du sollst einschätzen, welches der Vorhaben auf dieser Grundlage tatsächlich eine Entdeckung erwarten lässt.","kurz":"Die früheren Legenden zeigen nur, dass die Welt weniger erforscht war, nicht, dass ein bestimmtes Tier existiert. Seriös ist, wo es wirklich unerforscht ist und plausible Hinweise vorliegen und handfeste, prüfbare Belege angestrebt werden.","prueffrage":"Welche Spuren müsste ein großes Tier über Jahrzehnte hinterlassen, und wo hätte man sie längst finden müssen?","rueckmeldung":[{"option":1,"text":"Berichte von Dorfbewohnern sind ein guter Anfang für eine Suche. Als Grundlage für die Existenz taugen sie aber nicht, denn Erzählungen lassen sich nicht nachprüfen. Nötig wären handfeste Belege wie ein Kadaver, DNA oder klare Aufnahmen."},{"option":2,"text":"Kamerafallen sind ein sinnvolles Werkzeug, und das Tal ist wirklich kaum erforscht. Doch ein Raubtier dieser Größe könnte dort nach bekanntem biologischem Wissen nicht überleben, weil die Beute fehlt. Dem Tier fehlt die Plausibilität, da hilft auch die beste Technik nicht."},{"option":3,"text":"Beharrliches Suchen wirkt gründlich, doch in einem gut erforschten Gebiet ist ein unbemerkter Bestand eines großen Tieres äußerst unwahrscheinlich. Jahre ohne jede Spur trotz dichtem Kameranetz sprechen eher dagegen, dass dort noch etwas zu finden ist."}],"familie":"wissenschaft-abgrenzen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Tetrapod Zoology (tetzoo.com): „The Discovery of the Okapi, Part 1“ (2023)","oeffentlich":true,"url":"https://tetzoo.com/blog/2023/4/11/the-discovery-of-the-okapi-part-1","abruf":"2026-10-12"},{"typ":"doi","kurz":"Sykes, B. C. u. a. (2014): Genetic analysis of hair samples attributed to yeti, bigfoot and other anomalous primates. Proc. R. Soc. B 281, 20140161","oeffentlich":true,"doi":"10.1098/rspb.2014.0161","abruf":"2026-10-12"},{"typ":"url","kurz":"Traill, L. W. u. a. (2007): Minimum viable population size (Autorenfassung)","oeffentlich":true,"doi":"10.1016/j.biocon.2007.06.011","url":"https://conservationbytes.com/wp-content/uploads/2011/03/traill-et-al-2007-biol-conserv.pdf","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"fcfb518881c29010"}},{"id":"qx-f-045","clusterId":"F","werkstueckRef":"F.2.3","stufe":2,"question":"Jemand behauptet, im Loch Ness lebe eine Population riesiger Reptilien, die sich dort seit Generationen hält. Welche Überlegung spricht am stärksten dagegen?","options":["Als grobe Faustregel wiegen Räuber zusammen höchstens etwa ein Zehntel ihrer Beute; auf eine überlebensfähige Gruppe verteilt, wäre jedes Tier viel zu klein.","Viele Sichtungen lassen sich durch Wellen, Treibholz und Wasservögel erklären; Augenzeugenberichte sind deshalb als Beleg für große Tiere wenig wert.","Die Beweislast liegt bei dem, der eine außergewöhnliche Behauptung aufstellt; solange kein Belegtier vorliegt, ist die Behauptung nicht gestützt.","Dass nie ein Tier gefangen oder tot gefunden wurde, ist noch kein Gegenbeweis; fehlende Funde schließen eine verborgene Population nicht aus."],"correctIndex":0,"explanation":"Die Behauptung lässt sich mit einer einfachen Bilanz prüfen: Akustische Schätzungen (Shine 1993) und Probennahmen ergaben rund 17 bis 24 Tonnen Fisch im freien Wasser des Sees. Nach einer ökologischen Faustregel macht die Masse aller Räuber zusammen davon meist höchstens etwa ein Zehntel aus, also rund zwei Tonnen. Eine Art braucht aber eine Mindestzahl von Tieren, um nicht auszusterben; bei etwa zehn Tieren käme jedes auf höchstens rund 200 Kilogramm Körpermasse, viel zu wenig für riesige Reptilien. Einschränkung: Die Faustregel gilt nur näherungsweise, und die Zahl gilt nur für das freie Wasser, Uferzone, Bodenfische und Wanderfische sind nicht erfasst; sie ist eine Größenordnung, kein exakter Wert. Dass sich Sichtungen oft durch Wellen oder Treibholz erklären lassen, entkräftet Zeugenberichte, rechnet aber nicht nach, ob der See solche Tiere ernähren könnte. Die Beweislast beim Behauptenden zu sehen ist richtig, liefert aber noch kein Argument aus den Zahlen des Sees. Dass nie ein Tier gefunden wurde, ist kein Gegenbeweis, und auch das Fehlen von Funden sagt nichts über die Ernährungsmöglichkeiten des Sees.","coreRule":"⚡ Prüfe Existenzbehauptungen mit einer Bilanz: Reicht die Nahrung für eine überlebensfähige Population?","beleg":"Werkstück F.2.3 (Verletzung der Ökologie & des Energiebedarfs); Fn. gl-f-nessie (Shine 1993, S. 271 f.; auch Loxton, Prothero 2013, S. 158 f.)","status":"entwurf","scenario":"In einem Gespräch über Loch Ness sagt jemand: „Der See ist riesig und tief, da kann sich locker eine Gruppe großer Reptilien verstecken.“ Du weißt: Im freien Wasser des Sees schwimmen nach Sonarzählungen und Probennahmen nur rund 17 bis 24 Tonnen Fisch.","quote":"","quoteLabel":"","kurz":"Der See gibt nach der Fischbilanz nur etwa zwei Tonnen Räubermasse her. Auf eine überlebensfähige Gruppe verteilt, bliebe für jedes Tier viel zu wenig für riesige Reptilien. Die Faustregel gilt nur näherungsweise, die Größenordnung genügt aber.","prueffrage":"Welche Zahl über den See ist bekannt, und was lässt sich mit ihr nachrechnen?","rueckmeldung":[{"option":1,"text":"Dass Wellen, Treibholz und Vögel viele Sichtungen erklären, stimmt, und es schwächt Zeugenberichte. Es rechnet aber nicht nach, ob der See solche Tiere überhaupt ernähren könnte; dieses Argument greift die Behauptung selbst an."},{"option":2,"text":"Die Beweislast beim Behauptenden zu sehen ist richtig. Sie sagt aber nur, dass die Behauptung unbelegt ist, und liefert kein Argument aus den Gegebenheiten des Sees, das gegen die Population spricht."},{"option":3,"text":"Fehlende Funde sind tatsächlich kein Gegenbeweis. Das spricht aber eher für die Möglichkeit einer verborgenen Population, als gegen sie, und sagt nichts darüber, ob der See genug Nahrung für sie hätte."}],"familie":"population-und-spuren","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Shine, A. J. (1993): Postscript: Surgeon or Sturgeon? Scottish Naturalist 105, S. 271–282 (Webfassung des Loch Ness Project)","oeffentlich":true,"url":"https://lochnessproject.org/ARCHIVE%20ROOM/papershtml/loch_ness_surgeon_sturgeon.htm","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"3d8dc4067f8403c3"}},{"id":"qx-f-046","clusterId":"F","werkstueckRef":"F.2.3","stufe":3,"question":"Ein Forscherteam sammelt Haarproben, die Yeti, Bigfoot und ähnlichen Wesen zugeschrieben wurden, und analysiert sie genetisch. Von den Proben mit auswertbarer DNA stammt keine einzige von einem unbekannten Primaten; gefunden werden unter anderem Bär, Pferd, Kuh, Hund, Wolf, Kojote und ein Mensch. Ein Freund sagt: „Das ist der Beweis, dass es diese Wesen nicht gibt.“ Wie ordnest du das Ergebnis richtig ein?","options":["Die Studie spricht klar gegen die Wesen, denn nach dem Sparsamkeitsprinzip gilt die einfachste Erklärung, hier die Nichtexistenz, als bewiesen.","Die Studie lässt die Existenz offen, denn eine Suche ohne Fund beweist keine Nichtexistenz, liefert aber auch keinen Beleg für die Behauptung.","Die Studie entlarvt alle Sichtungen als Irrtum, denn jede Probe, die einem Wesen zugeschrieben wurde, stammte von einem bekannten Tier.","Die Studie ändert nichts, denn die Beweislast liegt bei den Skeptikern, und ohne Widerlegung der Behauptung gilt sie als belegt."],"correctIndex":1,"explanation":"Von den Proben mit auswertbarer DNA stammte keine von einem unbekannten Primaten. Das Ergebnis zeigt: Die untersuchten Haare, die Yetis oder Bigfoots zugeschrieben wurden, stammten von bekannten Tieren und einem Menschen. Eine endgültige Widerlegung ist das nicht, denn ein einzelnes Nichtfinden kann nie beweisen, dass etwas nirgends existiert; die Autoren der Studie sagten selbst, sie könne die Existenz unbekannter Primaten weder widerlegen noch belegen. Umgekehrt trägt die Behauptung die Beweislast, und bisher fehlt jeder tragfähige Beleg. Wer „kein Fund“ als „Beweis des Gegenteils“ liest, macht denselben Fehler wie jemand, der „nicht widerlegt“ als „bewiesen“ liest. Das Sparsamkeitsprinzip bevorzugt einfache Erklärungen, beweist aber nichts. Aus den untersuchten Proben lässt sich nicht auf alle Sichtungen schließen. Und wer die Beweislast auf die Zweifler abwälzt, kehrt sie um, statt sie dort zu lassen, wo etwas behauptet wird.","coreRule":"⚡ Gezielt gesucht, nichts gefunden: Das ist kein Beweis der Nichtexistenz, aber ein weiterer Mangel an Belegen für die Behauptung.","beleg":"Werkstück F.2.3 (Verletzung der Populationsbiologie); Fn. gl-f-sykes (Sykes u. a. 2014, Proc. R. Soc. B 281, S. 1--3)","status":"entwurf","scenario":"","kurz":"Ein Suchergebnis ohne Fund lässt offen, ob etwas irgendwo existiert, und belegt es ebenso wenig. Der naheliegende Fehler ist, „nichts gefunden“ als „Gegenteil bewiesen“ zu lesen, obwohl bisher auch jeder tragfähige Beleg für die Wesen fehlt.","prueffrage":"Was genau wurde untersucht, und was fand sich in den Proben mit auswertbarer DNA?","rueckmeldung":[{"option":0,"text":"Die einfachste Erklärung für diese Haarproben ist tatsächlich, dass sie von bekannten Tieren stammen. Das Sparsamkeitsprinzip wählt aber nur die plausiblere Hypothese aus und beweist nichts; ein Nichtfinden kann Nichtexistenz nie endgültig belegen."},{"option":2,"text":"Alle untersuchten Proben mit auswertbarer DNA stammten von bekannten Tieren, das ist ein starkes Ergebnis. Es betrifft aber nur diese Proben und sagt nichts über alle Sichtungen, die niemand als Haarprobe eingereicht hat."},{"option":3,"text":"Wer etwas behauptet, muss es belegen; fehlende Widerlegung ersetzt keinen Beleg. Die Beweislast bei den Zweiflern abzuladen, kehrt das Prinzip um. Außerdem ändert die Studie durchaus etwas: Sie hat konkrete Proben geprüft und keinen Beleg gefunden."}],"familie":"unwissen-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Sykes, B. C.; Mullis, R. A.; Hagenmuller, C.; Melton, T. W.; Sartori, M. (2014): Genetic analysis of hair samples attributed to yeti, bigfoot and other anomalous primates. Proc. R. Soc. B 281(1789), 20140161 (CC BY, PMC4100498)","oeffentlich":true,"doi":"10.1098/rspb.2014.0161","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"fa142c1d02cb5fbd"}},{"id":"qx-f-047","clusterId":"F","werkstueckRef":"F.2.3","stufe":4,"question":"Ein Bigfoot-Fan sagt: „Der Gorilla galt lange als Mythos und existiert doch. Also kann es auch Bigfoot geben.“ Welche Antwort trifft den Denkfehler am besten?","options":["Der Gorilla-Fall zeigt nur, dass Entdeckungen möglich sind. Für das jetzt behauptete Tier liefert er keinen einzigen Beleg.","Der Fan verwechselt Zusammenhang mit Ursache. Dass beide in Legenden vorkamen, zeigt nicht, dass das eine das andere verursacht.","Der Fan argumentiert im Kreis. Er setzt voraus, dass Bigfoot existiert, und nimmt genau das als Grund dafür, dass er existieren kann.","Der Fan stellt eine falsche Alternative auf. Er tut so, als sei jede Legende entweder ganz wahr oder ganz erfunden, dazwischen gebe es nichts."],"correctIndex":0,"explanation":"Der Fan schließt von „es gab Fälle, in denen eine Legende wahr war“ auf „also ist diese Legende wahr“. Das ist kein Beleg, sondern ein Präzedenzfall: Er zeigt nur, dass Entdeckungen möglich sind. Die Welt war damals unerforschter, und für das Okapi (1901 anhand von Fellstreifen beschrieben) und den Riesenkalmar (1857 anhand von Funden beschrieben) folgten handfeste Belege. Für Bigfoot fehlen solche Belege; gezielte DNA-Analysen angeblicher Haarproben ergaben 2014 nur bekannte Tiere, darunter Bären, Pferde, Kühe, Hunde und einen Menschen. Dazu kommt: Eine verborgene Population riesiger Primaten bräuchte Tausende Tiere, die in einer von Satelliten und Smartphones kartierten Welt keine eindeutigen Spuren hinterlassen. Dass früher manches unerforscht war, macht die Behauptung heute nicht wahrscheinlicher. Der Fan behauptet keine Wirkung zwischen zwei Dingen, deshalb liegt auch keine Verwechslung von Zusammenhang und Ursache vor. Er setzt Bigfoots Existenz nicht schon voraus, sondern zieht einen anderen Fall heran, also argumentiert er auch nicht im Kreis. Eine Entweder-oder-Alternative stellt er ebenfalls nicht auf; sein Fehler ist der Sprung vom Möglichen zum Belegten.","coreRule":"⚡ „Früher galt es auch als Mythos“ ersetzt keinen Beleg für das jetzt behauptete Tier.","beleg":"Werkstück F.2.3 (Abschluss-Diagnose des Pathologen)","status":"entwurf","scenario":"","kurz":"Der Gorilla zeigt nur, dass Legenden manchmal wahr sind. Das ist ein Präzedenzfall, kein Beleg für Bigfoot. Der Fehler liegt im Sprung vom Möglichen zum Belegten: Für Bigfoot fehlen bis heute handfeste Belege.","prueffrage":"Was hat Fachleute am Ende vom Gorilla überzeugt, und gibt es für Bigfoot etwas Vergleichbares?","rueckmeldung":[{"option":1,"text":"Dass beide in Legenden vorkamen, stimmt, und das wirkt wie ein Zusammenhang. Der Fan behauptet aber gar nicht, das eine bewirke das andere. Sein Fehler liegt woanders: Er schließt aus einem einzelnen Fall auf einen anderen."},{"option":2,"text":"Ein Zirkelschluss klingt plausibel, weil der Schluss unbegründet wirkt. Der Fan setzt Bigfoots Existenz aber nicht schon voraus, sondern stützt sich auf einen anderen Fall, den Gorilla. Seine Folgerung bleibt zudem vorsichtig: Er sagt nur „kann es geben“."},{"option":3,"text":"Eine Alternative nach dem Muster „ganz wahr oder ganz erfunden“ wird hier nicht aufgestellt. Der Fan sagt nur, dass es manchmal wahr war, und überträgt das auf Bigfoot. Es fehlt der Beleg, nicht eine Zwischenstufe."}],"familie":"ablehnung-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Tetrapod Zoology (tetzoo.com): „The Discovery of the Okapi, Part 1“ (2023)","oeffentlich":true,"url":"https://tetzoo.com/blog/2023/4/11/the-discovery-of-the-okapi-part-1","abruf":"2026-10-12"},{"typ":"doi","kurz":"Kubodera, T.; Mori, K. (2005): First-ever observations of a live giant squid in the wild. Proc. R. Soc. B 272(1581), S. 2583–2586 (PMC1559985)","oeffentlich":true,"doi":"10.1098/rspb.2005.3158","abruf":"2026-10-12"},{"typ":"doi","kurz":"Sykes, B. C. u. a. (2014): Genetic analysis of hair samples attributed to yeti, bigfoot and other anomalous primates. Proc. R. Soc. B 281, 20140161","oeffentlich":true,"doi":"10.1098/rspb.2014.0161","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"380fcbd9ab6a4d1c"}},{"id":"qx-f-048","clusterId":"F","werkstueckRef":"F.2.4","stufe":1,"question":"Eine Werbung für ein neues Buch lautet: „Millionen Leser können sich nicht irren – dieses Buch beweist, dass Außerirdische die Pyramiden gebaut haben!“ Was ist an dieser Argumentation fehlerhaft?","options":["Sie folgert aus der großen Verbreitung eines Buches, dass seine Behauptung belegt ist, obwohl Verkaufszahlen nichts über die Beweislage aussagen.","Sie verlangt, dass die Behauptung schon deshalb richtig sein muss, weil bisher niemand den Beweis erbracht hat, dass die Pyramiden von Menschen gebaut wurden.","Sie stützt sich auf ein einziges Buch als Quelle; würden mehrere Bücher dieselbe These vertreten, wäre die Behauptung damit belegt.","Sie schließt aus einem sehr alten Bauwerk, dass die damaligen Menschen es nicht errichtet haben können, weil ihnen die nötige Technik gefehlt habe."],"correctIndex":0,"explanation":"Verkaufszahlen messen Neugier, Marketing und Unterhaltungswert, nicht Wahrheit. Erich von Däniken etwa trug die Alien-Idee 1968 mit „Erinnerungen an die Zukunft“ zu einem Millionenpublikum (die englische Ausgabe verkaufte sich über sieben Millionen Mal), obwohl die Idee älter war und dadurch nicht besser belegt wurde. Ob eine Behauptung stimmt, entscheiden Belege und Methoden, nicht die Zahl derer, die sie gekauft, gehört oder geglaubt haben. Prüfe deshalb immer: Welche Beweise werden vorgelegt, und nicht: Wie viele glauben es?","coreRule":"⚡ Bekannt gemacht ist nicht bewiesen: Die Popularität einer Idee ist kein Beleg.","beleg":"Werkstück F.2.4 (Die Autopsie-Akte); Fn. gl-f-daeniken (Inselmann 2026, Skeptiker 1/2026, S. 25 und 27)","status":"entwurf","scenario":"","kurz":"Millionen Käufer zeigen nur, dass ein Buch Neugier weckt und sich gut verkauft, nicht dass seine These stimmt. Der Fehler liegt im Schluss von „viele glauben es“ auf „es ist belegt“: Ob etwas stimmt, entscheiden Belege und Methoden.","prueffrage":"Welche Belege nennt die Werbung selbst, und was davon sagt etwas über die Pyramiden?","rueckmeldung":[{"option":1,"text":"Die Beweislast so umzudrehen, wäre tatsächlich ein klassischer Fehlschluss. Die Werbung tut das aber nicht, sie beruft sich auf die Leserzahl. Außerdem ist der Bau der Pyramiden durch Menschen gut belegt."},{"option":2,"text":"Die Zahl der Quellen ist nicht der Kern: Auch viele Bücher mit derselben These belegen nichts, solange keines Beweise vorlegt. Die Werbung macht einen anderen Fehler, sie beruft sich auf die Zahl der Leser statt auf Belege."},{"option":3,"text":"Das „Es fehlte die Technik“-Argument kommt in Alien-Theorien oft vor, steht aber nicht in dieser Werbung, und es stimmt auch nicht: Die Ägypter besaßen die nötigen Werkzeuge und Organisation. Diese Werbung setzt auf Verkaufszahlen."}],"familie":"mehrheit-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Internet Encyclopedia of Philosophy: Fallacies, Art. „Appeal to the People“/„Bandwagon“","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"url","kurz":"Associated Press via NBC News (11.01.2026): „Erich von Däniken, Swiss writer who spawned alien archaeology, dies at 90“","oeffentlich":true,"url":"https://www.nbcnews.com/news/obituaries/erich-von-daniken-swiss-writer-spawned-alien-archaeology-dies-90-rcna253448","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Inselmann, L. (2026): Zurück zu den Sternen. Ein skeptischer Nachruf auf Erich von Däniken. Skeptiker 1/2026, S. 25–35","oeffentlich":false,"seite":"S. 27"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"6964cbf8fd894a43"}},{"id":"qx-f-049","clusterId":"F","werkstueckRef":"F.2.4","stufe":2,"question":"Welche Frage prüft die Deutung des Sprechers am besten?","scenario":"In einer Dokumentation wird eine Höhlenmalerei gezeigt: eine stilisierte Figur mit großem Kopfschmuck. Der Sprecher sagt: „Das ist ein Wesen im Raumanzug, kein Zweifel.“ Erhalten sind weder Beschriftungen noch Beigaben, die die Figur erklären.","options":["Mit welchen Farbstoffen und welcher Technik wurde das Bild hergestellt, und wie gut hat es sich erhalten?","Welche Kopfbedeckungen und rituellen Gewänder gab es in der Kultur, die das Bild gemalt hat, und passt die Figur dazu?","Was verrät die Beschriftung neben der Figur über ihre Bedeutung, und von wem wurde sie ursprünglich angebracht?","Wie lässt sich ausschließen, dass die Malerei eine spätere Fälschung ist, und wer hat sie zuerst untersucht?"],"correctIndex":1,"explanation":"Der Sprecher liest ein sehr altes Bild durch die Brille der Gegenwart: Weil wir Raumanzüge kennen, sehen wir sie auch dort, wo ein Kopfschmuck zu sehen ist. Das ist Präsentismus. Die Deutung gewinnt nicht dadurch an Gewicht, dass sie dem heutigen Auge naheliegt. Entscheidend ist, was für die Entstehungszeit und den kulturellen Rahmen des Bildes belegt ist. In vielen frühen Kulturen gehören Kopfschmuck und Masken zu Ritualen, und eine Figur mit auffälligem Kopfschmuck passt deshalb wahrscheinlich zu einer Person in ritueller Kleidung, etwa einem Schamanen. Die beste Prüffrage fragt daher nach dem Kontext des Bildes. Farbstoffe und Technik sind für Restauratoren wichtig, sagen aber nichts darüber, was die Figur darstellt. Eine Fälschungsprüfung ist sinnvoll, wenn die Echtheit zweifelhaft ist, davon ist hier nicht die Rede. Eine Beschriftung, die man befragen könnte, ist nach dem Szenario gar nicht erhalten.","coreRule":"⚡ Wer ein altes Bild deuten will, fragt zuerst nach dem Kontext seiner Zeit, nicht nach der Ähnlichkeit zu heutiger Technik.","beleg":"Werkstück F.2.4 (Verletzung der Kunstgeschichte & Religionswissenschaft)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Entscheidend ist, was in der Entstehungszeit und Kultur des Bildes belegt ist, nicht was dem heutigen Auge naheliegt. Wir kennen Raumanzüge und sehen sie deshalb in einem Kopfschmuck; in vielen frühen Kulturen gehörte er aber wohl zu Ritualen.","prueffrage":"Was ist von dem Bild selbst erhalten, und was fügt der Sprecher aus eigenem Wissen hinzu?","rueckmeldung":[{"option":0,"text":"Farbstoffe und Technik helfen bei Datierung und Restaurierung, und das ist wertvolle Arbeit. Was die Figur darstellen soll, bleibt damit aber offen, und genau das behauptet der Sprecher."},{"option":2,"text":"Eine Beschriftung wäre tatsächlich ein starker Hinweis auf die Bedeutung. Nach dem Szenario ist aber keine erhalten, die Frage hätte also nichts, woran sie ansetzen könnte."},{"option":3,"text":"Echtheitsprüfungen sind sinnvoll, wenn Zweifel an der Herkunft bestehen, hier ist davon aber keine Rede. Selbst ein echtes Bild verriete noch nicht, was die Figur zeigt, und wer es zuerst untersuchte, ändert daran nichts."}],"familie":"aus-ihrer-lage-urteilen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Colavito, J.: „Faking Ancient Art in Uzbekistan“ (jasoncolavito.com)","oeffentlich":true,"url":"https://www.jasoncolavito.com/faking-ancient-art-in-uzbekistan.html","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"d14e1886fe2df1b1"}},{"id":"qx-f-050","clusterId":"F","werkstueckRef":"F.2.4","stufe":3,"question":"Eine Doku-Reihe fragt in jeder Folge neu: „Was, wenn die Götter in Wahrheit Astronauten waren?“ Eine Zuschauerin sagt: „Die behaupten ja gar nichts, die fragen nur. Da kann man ihnen nichts vorwerfen.“ Was ist an dieser Verteidigung fehlerhaft?","options":["Wer nur fragt, legt eine Antwort nahe, ohne sie zu behaupten, und umgeht so die Pflicht, sie zu belegen.","Eine offene Frage lässt jedem Zuschauer die Prüfung selbst und ist deshalb die sauberste Form einer Hypothese.","Wer nichts behauptet, kann auch nichts Falsches sagen, und deshalb bleibt eine Frage immer frei von Fehlschlüssen.","Eine Frage verlagert die Beweislast auf die Kritiker, weil diese das Gegenteil zeigen müssen, um sie zu entkräften."],"correctIndex":0,"explanation":"Eine Suggestivfrage wie „Was, wenn die Götter in Wahrheit Astronauten waren?“ stellt keine beweisbare Behauptung auf, legt aber eine bestimmte Antwort nahe. Das erzeugt ein Gefühl des Mysteriums, und weil nichts Konkretes behauptet wird, muss auch nichts belegt werden. Die Beweislast liegt jedoch bei dem, der eine außergewöhnliche Deutung nahelegt, nicht bei denen, die sie bezweifeln. Wer nur fragt, entzieht sich der Prüfung und bekommt trotzdem die Wirkung einer Behauptung. Ein Test: Formuliere die Frage als Aussage um („Die Götter waren Astronauten“). Wenn du dann Belege verlangen würdest, gilt das auch für die Frageform.","coreRule":"⚡ Wer nur fragt, scheint nichts zu behaupten und umgeht so die Beweislast: Das ist die Wirkung der Suggestivfrage.","beleg":"Werkstück F.2.4 (Die Anatomie der Täuschung: „Ich stelle ja nur Fragen“)","status":"entwurf","scenario":"","kurz":"Eine Suggestivfrage behauptet nichts Konkretes und legt trotzdem eine bestimmte Antwort nahe. So entsteht die Wirkung einer Behauptung, ohne dass jemand Belege liefern muss. Der Fehler liegt darin, dass die Frageform vor der Prüfung schützt.","prueffrage":"Welchen Eindruck hinterlässt die Frage bei dir, und was bliebe von ihr übrig, wenn du sie als bloße Aussage lesen würdest?","rueckmeldung":[{"option":1,"text":"Eine echte Hypothese ist so formuliert, dass man sie prüfen kann. Die Frage hier lenkt dagegen auf eine bestimmte Antwort, ohne sich festzulegen, und entgeht damit genau der Prüfung, die eine Hypothese braucht."},{"option":2,"text":"Wer nichts behauptet, sagt in der Tat nichts Falsches. Doch die Suggestivfrage erzielt die Wirkung einer Behauptung und umgeht den Beleg. Deshalb bleibt sie keineswegs immer frei von Fehlschlüssen."},{"option":3,"text":"Wer eine Frage nicht widerlegen kann, scheint im Nachteil. Die Beweislast trägt aber, wer eine außergewöhnliche Deutung nahelegt; Kritiker müssen das Gegenteil nicht zeigen, um die Deutung anzuzweifeln."}],"familie":"beweislast-klaeren","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Internet Encyclopedia of Philosophy: Fallacies, Art. „Loaded Question“, „Complex Question“ und „Burden of Proof“","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"f41319df7fffa842"}},{"id":"qx-f-051","clusterId":"F","werkstueckRef":"F.3.1","stufe":1,"question":"Der Heilpraktiker sagt: „Krebs ist keine Fehlfunktion des Körpers, sondern ein sinnvolles Programm, das durch einen seelischen Schock ausgelöst wird. Eine Chemotherapie stört diesen Heilungsprozess und ist die eigentliche Todesursache.“ Welcher Einwand trifft den Kern dieser Behauptung am besten?","options":["Krebs entsteht aus mutierten körpereigenen Zellen, die unkontrolliert wachsen und ohne Behandlung zum Tod führen können.","Ein Heilpraktiker hat keine ärztliche Zulassung, und was ein Nichtarzt über Krebs sagt, kann schon deshalb nicht stimmen.","Wer an Behandlungen verdienen könnte, hat ein Eigeninteresse, und deshalb muss seine Behauptung falsch sein.","Die Behauptung unterstellt der Medizin böse Absicht, und Verschwörungsannahmen ohne Beleg sind kein Argument."],"correctIndex":0,"explanation":"Die Behauptung deutet eine zerstörerische Krankheit in einen „sinnvollen“ Vorgang um, ohne einen zellbiologischen Mechanismus anzugeben. Krebs ist unkontrolliertes Wachstum mutierter körpereigener Zellen, das Gewebe zerstört und den Organismus ohne Behandlung töten kann. Dass ein Tumor „Sinn“ hätte, ist eine Zuschreibung, kein Befund. Dazu kommt: Wird die Behandlung für den Tod verantwortlich gemacht, kann die Aussage nie scheitern. Wer geheilt wird, bestätigt sie; wer stirbt, hat den „Konflikt nicht gelöst“, einen „Folgekonflikt“ erlitten oder wurde durch die „panikmachende Schulmedizin“ getötet. Eine Aussage, die durch kein denkbares Ergebnis widerlegt werden kann, sagt nichts über die Welt aus. Dass ein Heilpraktiker keine ärztliche Zulassung hat, stimmt zwar, widerlegt aber keine Behauptung. Ein möglicher Eigennutz ist ein Warnsignal, entscheidet aber nicht über richtig oder falsch. Von einer unterstellten bösen Absicht ist im Szenario keine Rede.","coreRule":"⚡ Wer eine tödliche Krankheit zum „sinnvollen Programm“ erklärt, braucht einen prüfbaren Mechanismus; ohne ihn ist es eine Umdeutung, keine Erklärung.","beleg":"Werkstück F.3.1 (Die Kern-Behauptung; Verletzung der Onkologie & Zellbiologie; Falsifizierbarkeit)","status":"entwurf","scenario":"Eine Bekannte erzählt dir, ihr Onkel habe eine Krebsdiagnose bekommen. Er wolle die Operation absagen, weil ihm ein Heilpraktiker eine ungewöhnliche Erklärung gegeben habe.","kurz":"Krebs ist unkontrolliertes Wachstum mutierter körpereigener Zellen, das ohne Behandlung töten kann; ein „Sinn“ ist nur zugeschrieben, kein Befund. Und weil jeder Ausgang als Bestätigung gedeutet werden kann, lässt sich die Behauptung nie widerlegen.","prueffrage":"Woran sterben Menschen mit Krebs, die nie eine Chemotherapie bekommen haben?","rueckmeldung":[{"option":1,"text":"Dass ein Heilpraktiker keine ärztliche Zulassung hat, stimmt und darf zur Vorsicht mahnen. Es widerlegt die Behauptung aber nicht, denn sie muss an ihrem Inhalt geprüft werden: Wer etwas sagt, entscheidet nicht darüber, ob es stimmt."},{"option":2,"text":"Ein mögliches Eigeninteresse ist ein berechtigtes Warnsignal, mehr aber nicht. Auch wer von etwas profitiert, kann recht haben, und ob die Behauptung stimmt, zeigt sich an ihr selbst. Von einem Verdienst ist im Fall zudem gar nicht die Rede."},{"option":3,"text":"Belegloses Raunen über böse Absichten ist tatsächlich kein Argument. Der Heilpraktiker unterstellt hier aber keine Verschwörung; er deutet die Krankheit um und macht die Behandlung für den Tod verantwortlich. Der Einwand geht an dieser Behauptung vorbei."}],"familie":"mechanismus-verlangen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"National Cancer Institute: „What Is Cancer?“","oeffentlich":true,"url":"https://www.cancer.gov/about-cancer/understanding/what-is-cancer","abruf":"2026-10-12"},{"typ":"url","kurz":"AG Prävention und Integrative Onkologie (PRiO) in der Deutschen Krebsgesellschaft: Stellungnahme „Germanische Neue Medizin® nach Dr. Hamer“, Stand 30.04.2026","oeffentlich":true,"url":"https://prio-dkg.de/stellungnahmen/germanische-neue-medizin/","abruf":"2026-10-12"},{"typ":"url","kurz":"Psiram: Art. „Germanische Neue Medizin“","oeffentlich":true,"url":"https://www.psiram.com/de/index.php/Germanische_Neue_Medizin","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"1f88f59a7ad8b510"}},{"id":"qx-f-052","clusterId":"F","werkstueckRef":"F.3.1","stufe":2,"question":"Was ist an dieser Argumentation der entscheidende Fehler?","options":["Jedes denkbare Ergebnis wird zugunsten der Lehre gedeutet, daher kann nichts sie widerlegen und sie ist nicht prüfbar.","Die Verbreitung der Lehre gilt als Beweis ihrer Wahrheit, daher überzeugt das Argument nur, weil viele Menschen ihr folgen.","Das Argument beruft sich auf einen berühmten Fachmann, daher gilt die Lehre als belegt, ohne dass seine Aussagen geprüft werden.","Das Argument wirbt mit dem Mitleid für Schwerkranke, daher wird die Lehre nach Gefühl statt nach Belegen beurteilt."],"correctIndex":0,"explanation":"Eine Aussage ist nur dann prüfbar, wenn es ein denkbares Ergebnis gibt, das sie widerlegen würde. Hier wird jeder Ausgang eingebaut: Heilung bestätigt die Lehre, Tod wird dem Patienten („Konflikt nicht gelöst“, „Folgekonflikt“) oder der Schulmedizin („von der Schulmedizin getötet“) angelastet. Ein solches System kann nie scheitern, und gerade deshalb sagt es nichts darüber, ob es stimmt. Im Ernstfall ist das gefährlich, denn bei ernsten Erkrankungen wie Krebs bedeutet der Verzicht auf wirksame Behandlung ein hohes Todesrisiko. Wer prüfen will, fragt: „Welches Ergebnis würde dich überzeugen, dass die Lehre falsch ist?“ Kommt darauf keine Antwort, ist die Lehre keine Erkenntnis, sondern ein Glaubenssystem. Dass viele einer Lehre folgen, sagt nichts über ihre Wahrheit, doch auf Verbreitung beruft sich der Bekannte gar nicht. Ein berühmter Fachmann wird nirgends angeführt. Auch Mitleid mit Kranken spielt in seinem Argument keine Rolle.","coreRule":"⚡ Wenn jeder Ausgang die Lehre bestätigt, ist sie nicht prüfbar, und im Ernstfall gefährlich.","beleg":"Werkstück F.3.1 (Die Konfrontation mit der Realität: Falsifizierbarkeit)","status":"entwurf","scenario":"Ein Bekannter will einer todkranken Verwandten eine „Konflikt-Heillehre“ empfehlen und verteidigt sie so: „Wenn jemand nach der Behandlung gesund wird, beweist das die Lehre. Stirbt jemand, hat er seinen Konflikt nicht gelöst, einen Folgekonflikt erlitten oder wurde von der Schulmedizin getötet. Die Lehre irrt also nie.“","kurz":"Wenn Heilung die Lehre bestätigt und Tod ebenfalls (Patient oder Schulmedizin schuld), kann kein Ausgang sie widerlegen. Eine Aussage, die nie scheitern kann, sagt nichts darüber, ob sie stimmt.","prueffrage":"Wie erklärt die Argumentation die Todesfälle, und wem gibt sie dabei jeweils die Schuld?","rueckmeldung":[{"option":1,"text":"Viele Anhänger sind ein bekanntes Scheinargument, und dass Verbreitung nichts über Wahrheit sagt, stimmt auch. Der Bekannte verweist aber gar nicht auf die Zahl der Anhänger. Sein Fehler liegt in der Deutung der Ausgänge."},{"option":2,"text":"Ein Fachmann als bloße Autorität wäre tatsächlich ein schwacher Beleg. Im Argument des Bekannten taucht aber niemand auf, auf den er sich beruft. Er stützt sich nur auf seine eigene Deutung von Heilung und Tod."},{"option":3,"text":"Gefühle können Urteile verzerren, und die Lage einer Todkranken ist bedrückend. Der Bekannte wirbt aber nicht mit ihrem Leid, er rechtfertigt seine Lehre mit der Deutung der möglichen Ausgänge. Dort liegt der Fehler, nicht beim Mitleid."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Karl Popper (Abschn. 2)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/popper/","abruf":"2026-10-12"},{"typ":"url","kurz":"Psiram: Art. „Germanische Neue Medizin“","oeffentlich":true,"url":"https://www.psiram.com/de/index.php/Germanische_Neue_Medizin","abruf":"2026-10-12"},{"typ":"url","kurz":"AG PRiO in der Deutschen Krebsgesellschaft: Stellungnahme „Germanische Neue Medizin® nach Dr. Hamer“, Stand 30.04.2026","oeffentlich":true,"url":"https://prio-dkg.de/stellungnahmen/germanische-neue-medizin/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"3ab4eec6777078fa"}},{"id":"qx-f-053","clusterId":"F","werkstueckRef":"F.3.1","stufe":3,"question":"Was sind die Ringe, und was folgt daraus für die Behauptung des Heilers?","options":["Sie sind echte Veränderungen im Gehirn, die keinen Rückschluss auf den Ort des Tumors erlauben, und damit ist die Behauptung widerlegt.","Sie sind echte Veränderungen im Gehirn, deren Deutung unter Fachleuten offen ist, und damit bleibt die Behauptung eine ernst zu nehmende Möglichkeit.","Sie sind Zeichen früherer Entzündungen im Gehirn, die der Heiler fälschlich als Konfliktspuren deutet, und damit ist die Behauptung widerlegt.","Sie sind Artefakte der Aufnahmetechnik, die das CT-Gerät selbst erzeugt, und damit trägt ihr bloßes Sichtbarsein die Behauptung nicht."],"correctIndex":3,"explanation":"Dass etwas auf einem Bild sichtbar ist, heißt noch nicht, dass es eine Eigenschaft des Patienten abbildet. Bildgebende Verfahren können selbst Strukturen erzeugen, die es im Körper gar nicht gibt. Bei diesen Ringen ist das der Fall: Radiologen kennen sie seit Langem als Ringartefakte, die die Computertomographie selbst erzeugt und die keine medizinische Bedeutung haben (so beschreibt es etwa Prang 2014). Wer aus ihnen Konflikttyp und Tumorort ablesen will, schließt aus einem Fehler der Technik auf eine Eigenschaft des Patienten. Die richtige Prüffrage lautet deshalb, ob die Struktur überhaupt eine Eigenschaft des Patienten zeigt oder eine des Messgeräts, und nicht, ob sie echt aussieht. Die anderen Antworten erfinden Befunde im Gehirn (Veränderungen, frühere Entzündungen) oder behaupten eine offene Deutung, während die Ringe von der CT-Technik selbst erzeugt werden und keine medizinische Bedeutung haben.","coreRule":"⚡ Was auf dem Bild wie ein Befund aussieht, kann ein Artefakt der Technik sein.","beleg":"Werkstück F.3.1 (Verletzung der Neurologie); Fn. gl-f-hamerherde (Prang 2014, Kap. „Germanische Neue Medizin“)","status":"entwurf","scenario":"Ein Heiler behauptet, er könne auf Gehirn-CT-Bildern an ringförmigen Strukturen („Herden“) erkennen, welchen seelischen Konflikt ein Patient hatte und wo im Körper sein Tumor sitzt. Als Beleg zeigt er dir mehrere Bilder, auf denen solche Ringe deutlich zu sehen sind. Die Ringe selbst sind unstrittig vorhanden.","kurz":"Dass etwas auf einem Bild sichtbar ist, zeigt noch nicht, dass es zum Patienten gehört. Die Ringe erzeugt die CT-Technik selbst, als Ringartefakte ohne medizinische Bedeutung, daher lässt sich aus ihnen weder Konflikt noch Tumorort ablesen.","prueffrage":"Wofür halten Fachleute, die täglich CT-Bilder auswerten, solche Ringe?","rueckmeldung":[{"option":0,"text":"Dass die Ringe nichts über den Tumorort verraten, ist richtig. Sie sind aber keine Veränderungen im Gehirn, sondern entstehen durch die Aufnahmetechnik. Eine Behauptung ist außerdem nicht schon deshalb widerlegt, weil ihr Beleg nicht trägt."},{"option":1,"text":"Ein deutlich sichtbarer Befund wirkt, als müsse er etwas bedeuten, und eine offene Fachfrage klingt vorsichtig. Hier gibt es aber keine: Die Ringe stammen vom CT-Gerät selbst und gelten unter Radiologen seit Langem als bedeutungslos."},{"option":2,"text":"Die Ringe wirken wie Spuren im Gehirn, weil man Strukturen auf Bildern gern als Befund liest. Sie entstehen aber durch die CT-Technik: Der Heiler deutet sie falsch, doch der Grund liegt im Gerät, nicht in früheren Entzündungen."}],"familie":"bild-und-video-pruefen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Dawes, L.; Ismail, M.; Murphy, A. u. a.: „Ring artifact“. Radiopaedia.org (rID 1988)","oeffentlich":true,"url":"https://radiopaedia.org/articles/ring-artifact","abruf":"2026-10-12"},{"typ":"url","kurz":"Psiram: Art. „Germanische Neue Medizin“ (Abschnitt Hamer-Herde)","oeffentlich":true,"url":"https://www.psiram.com/de/index.php/Germanische_Neue_Medizin","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Prang, M. (2014): Alternativmedizin: Was sie leistet. Wann sie schadet. München: C. H. Beck, Kap. „Germanische Neue Medizin“","oeffentlich":false}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"a089f537c063adb9"}},{"id":"qx-f-054","clusterId":"F","werkstueckRef":"F.3.1","stufe":4,"question":"Ein Anbieter wirbt für die „5 Biologischen Naturgesetze“ und versichert: „Mit der Germanischen Neuen Medizin hat das nichts zu tun.“ Auf Nachfrage zählt er als „Gesetze“ dieselben Behauptungen auf wie die Germanische Neue Medizin: Jede Krankheit gehe auf einen seelischen Schock-Konflikt zurück, Tumore seien „sinnvolle Programme“, Chemotherapie störe die Heilung. Was folgt daraus für die Beurteilung des Angebots?","options":["Die Lehre ist inhaltlich dieselbe geblieben, denn dieselben Behauptungen unter neuem Namen sind weiterhin dieselbe Lehre mit denselben Problemen.","Die Distanzierung des Anbieters ist glaubwürdig, denn wer sich ausdrücklich von einer Lehre abgrenzt, hat sich damit auch inhaltlich von ihr gelöst.","Die Lehre ist gut belegt, denn Naturgesetze gelten ausnahmslos, und wer sich auf sie beruft, stützt sich damit auf gesichertes Wissen.","Die Verbindung zur früheren Lehre ist nicht erwiesen, denn nach der Unschuldsvermutung gilt seine Aussage, bis das Gegenteil bewiesen ist."],"correctIndex":0,"explanation":"Ob eine Behauptung stimmt, hängt von ihrem Inhalt und ihren Belegen ab, nicht von ihrem Etikett. Wer dieselben Kernthesen unter neuem Namen anbietet, bietet dieselbe Lehre an. Hamers Lehre wird seit seinem Tod (2017) unter mehreren Namen weitergeführt, etwa als „5 Biologische Naturgesetze“ oder in der „Meta-Medizin“, die Hamers fünf „Gesetze“ übernimmt. Die Bezeichnung „5 Biologische Naturgesetze“ vermeidet dabei gerade den belasteten Begriff „Germanisch“. Die Lehre wurde also weitergeführt, nicht korrigiert: Die Kernthesen bleiben dieselben, also bleiben auch die Probleme. Sie kursiert weiter über Messenger und soziale Medien. Der richtige Prüfschritt ist deshalb, die Inhalte mit der bekannten Lehre zu vergleichen und nach unabhängigen Belegen zu fragen, nicht dem Namen zu glauben. Eine Abgrenzung im Wort ist noch keine inhaltliche Änderung, und das Wort „Naturgesetze“ ist ein Etikett, das nichts belegt. Die Unschuldsvermutung gilt vor Gericht für Personen, nicht für Behauptungen, und der Zusammenhang liegt hier durch die identische Aufzählung ohnehin offen zutage.","coreRule":"⚡ Prüfe die Lehre, nicht das Etikett: Umbenennen ersetzt keine Belege.","beleg":"Werkstück F.3.1 (Die Autopsie-Akte); Fn. gl-f-14 (Psiram; Apotheken Umschau, abgerufen 23.09.2026)","status":"entwurf","scenario":"Du stößt in einer Messenger-Gruppe auf einen Anbieter, der „5 Biologische Naturgesetze“ als neue Heilmethode bewirbt. Der Name klingt neutral. Auf die Frage nach dem Ursprung sagt er nur, mit der Germanischen Neuen Medizin habe das nichts zu tun.","kurz":"Ob Behauptungen stimmen, hängt an Inhalt und Belegen, nicht am Namen. Wer dieselben Kernthesen unter neuem Etikett anbietet, bietet dieselbe Lehre an; ein Name ohne „Germanisch“ ändert nichts an ihren Problemen.","prueffrage":"Welche Behauptungen stehen hinter dem Namen, und wo hast du sie schon einmal gelesen?","rueckmeldung":[{"option":1,"text":"Eine ausdrückliche Abgrenzung betrifft zunächst nur den Namen. Inhaltlich löst sie nichts, solange der Anbieter dieselben Kernthesen aufzählt; eine Lösung von der Lehre müsste sich an den Inhalten zeigen."},{"option":2,"text":"Echte Naturgesetze gelten tatsächlich ausnahmslos, aber ein Anspruch wird nicht dadurch gesichert, dass er „Naturgesetz“ heißt. Das Wort ist hier ein Etikett; gesichertes Wissen braucht unabhängige Belege."},{"option":3,"text":"Die Unschuldsvermutung ist ein wichtiges Prinzip, gilt aber vor Gericht für Personen, nicht für Behauptungen. Hier geht es auch nicht um Schuld, sondern um einen Inhaltsvergleich, und der fällt durch die identische Aufzählung eindeutig aus."}],"familie":"wertende-woerter-abziehen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Psiram: Art. „Germanische Neue Medizin“ (Synonyme „fünf biologische Naturgesetze (5bn/5BN)“, „Germanische Heilkunde“)","oeffentlich":true,"url":"https://www.psiram.com/de/index.php/Germanische_Neue_Medizin","abruf":"2026-10-12"},{"typ":"url","kurz":"Psiram: Art. „Metamedizin“","oeffentlich":true,"url":"https://www.psiram.com/de/index.php/Metamedizin","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"c0c88492ee35b94b"}},{"id":"qx-f-055","clusterId":"F","werkstueckRef":"F.4.1","stufe":1,"question":"Eine Freundin erzählt: „Ich glaube an Karma und Reinkarnation, lege aber auch meine Tarotkarten, trage Heilsteine, meditiere zum ‚inneren Kind‘ und glaube an die Kraft der Schwingungen. Eine feste Gemeinschaft oder verbindliche Regeln brauche ich nicht.“ Welche Schlussfolgerung zieht man daraus am sinnvollsten?","options":["Ihre Weltanschauung ist eine selbst zusammengestellte Mischung aus Versatzstücken verschiedener Quellen und Traditionen.","Ihre Weltanschauung ist im Kern hinduistisch oder buddhistisch, weil Karma und Reinkarnation deren zentrale Lehren sind.","Ihre Weltanschauung ist psychologisch fundiert, weil das Konzept des „inneren Kindes“ aus der Psychologie stammt.","Ihre Weltanschauung ist eine bewusste Gegenposition zur Wissenschaft, die deren Ergebnisse ausdrücklich zurückweist."],"correctIndex":0,"explanation":"Karma und Reinkarnation stammen aus indischen Religionen wie Hinduismus und Buddhismus, das „innere Kind“ aus der Psychologie, Kristallheilung (Heilsteine) gehört zu den Pseudowissenschaften. Die Freundin kombiniert solche Versatzstücke nach eigenem Geschmack, ohne feste Dogmen, ohne Gemeinschaft und ohne verbindliche Regeln – ein Baukasten, aus dem man sich wie in einem Supermarkt bedient. Die Elemente werden dabei häufig aus ihrem ursprünglichen Zusammenhang gelöst: Karma etwa gehört in diesen Religionen in einen strengen ethischen Zusammenhang, der hier wegfällt. In solchen selbst zusammengestellten Weltanschauungen gilt oft das eigene Erleben als Maßstab, nicht überprüfbare Evidenz. Dass sich etwas stimmig anfühlt, ist aber kein Test, ob es stimmt. Dass Karma und Reinkarnation aus indischen Religionen stammen, macht sie nicht zur Anhängerin dieser Religionen, denn sie übernimmt nur einzelne Teile. Ein Element aus der Psychologie macht das Ganze nicht psychologisch fundiert. Von einer Ablehnung der Wissenschaft sagt sie nichts.","coreRule":"⚡ Wer sich seine Weltanschauung aus Fertigteilen zusammenbaut, entscheidet nach Gefühl und Geschmack. Dass die Teile zusammenpassen, heißt nicht, dass sie stimmen.","beleg":"Werkstück F.4.1 (Die Anatomie der Lehre: Das Baukasten-Prinzip)","status":"entwurf","scenario":"","kurz":"Sie kombiniert einzelne Elemente aus verschiedenen Quellen nach eigenem Geschmack, ohne Lehre, Gemeinschaft oder feste Regeln. Der naheliegende Fehler ist, vom Ursprung eines Teils auf das Ganze zu schließen, obwohl hier nur Versatzstücke übernommen werden.","prueffrage":"Was sagt die Freundin über Regeln und Gemeinschaft, und was verbindet Tarot, Heilsteine und Karma miteinander?","rueckmeldung":[{"option":1,"text":"Karma und Reinkarnation stammen tatsächlich aus indischen Religionen. Sie übernimmt aber nur einzelne Teile, ohne deren Lehre und den strengen ethischen Zusammenhang, in den Karma dort gehört. Das macht sie nicht zur Anhängerin."},{"option":2,"text":"Das „innere Kind“ kommt wirklich aus der Psychologie. Ein einzelnes Element macht das Ganze aber nicht fundiert, zumal Heilsteine und Schwingungen zu den Pseudowissenschaften gehören."},{"option":3,"text":"Eine Gegenposition zur Wissenschaft liegt nahe, wenn vieles Unbelegte zusammenkommt. Die Freundin sagt aber nichts über Wissenschaft und weist keine Ergebnisse zurück; das wäre eine Unterstellung."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Universität Münster, Exzellenzcluster Religion und Politik (2012): Pressemitteilung „Wenn Familien zweimal Weihnachten feiern – Mehr als ein Fünftel der Deutschen pflegen Patchwork-Religiosität“ (Christel Gärtner)","oeffentlich":true,"url":"https://www.uni-muenster.de/imperia/md/content/religion_und_politik/aktuelles/2012/12_2012/pm_patchwork-religiositaet.pdf","abruf":"2026-10-12"},{"typ":"url","kurz":"Hansson, S. O. (2008/2025): „Science and Pseudo-Science“, Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschnitt 1, 4.3","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"a9031b9c3f9f935b"}},{"id":"qx-f-056","clusterId":"F","werkstueckRef":"F.4.1","stufe":2,"question":"Ein Verkäufer entgegnet auf Kritik an seinen Heilsteinen: „Das ist nur deine materialistische Sichtweise, du bist für höhere Wahrheiten nicht offen.“ Was bewirkt diese Antwort für die Prüfbarkeit seiner Behauptung?","scenario":"Du äußerst an einem Stand auf einer Esoterikmesse Zweifel an der Wirkung von Heilsteinen.","options":["Sie macht die Behauptung vorsichtiger, weil der Verkäufer einräumt, dass die Wirkung noch nicht bewiesen ist.","Sie macht die Behauptung unangreifbar, weil jede Kritik als mangelnde Offenheit abgetan werden kann.","Sie macht die Behauptung prüfbarer, weil der Verkäufer benennt, welches Ergebnis ihn widerlegen würde.","Sie stützt die Behauptung, weil der Verkäufer Messergebnisse anführt, die die Wirkung seiner Steine belegen."],"correctIndex":1,"explanation":"Der Verkäufer behauptet, Heilsteine wirkten. Auf die Kritik antwortet er nicht mit einem Beleg, sondern mit einem Urteil über den Kritiker: Wer zweifelt, sei „nicht offen“. So lässt sich jede wissenschaftliche Kritik abwehren; die Behauptung wird unangreifbar und unfalsifizierbar. Entscheidend ist hier nur der Mechanismus: Kritik wird durch Immunisierung statt durch Belege beantwortet. Eine vorsichtigere Aussage oder eine genannte Bedingung, unter der er sich widerlegt sähe, würden die Prüfbarkeit verbessern, kommen in seiner Antwort aber nicht vor. Auch führt er keinerlei Ergebnisse an, die seine Steine belegen.","coreRule":"⚡ Wenn nur das eigene Gefühl zählt, kann kein Gegenbeweis zählen.","beleg":"Werkstück F.4.1 (Die epistemologische Grundlage: Absolute Subjektivität)","status":"entwurf","kurz":"Wer Zweifel als „mangelnde Offenheit“ abtut, beantwortet Kritik mit einem Urteil über den Kritiker statt mit einem Beleg. So lässt sich jeder Einwand abwehren, und die Behauptung wird unangreifbar, weil nichts sie mehr widerlegen kann.","prueffrage":"Worüber spricht der Verkäufer in seiner Antwort: über die Steine oder über die Person, die zweifelt?","rueckmeldung":[{"option":0,"text":"Die Antwort klingt nach Bescheidenheit, weil sie von „höheren Wahrheiten“ spricht. Der Verkäufer räumt aber nichts ein: Er hält an der Wirkung fest und kehrt den Vorwurf gegen den Kritiker. Vorsichtiger wird die Behauptung dadurch nicht."},{"option":2,"text":"Prüfbarer würde eine Behauptung, wenn jemand sagt, was ihn widerlegen würde. Der Verkäufer nennt aber keine solche Bedingung. Er erklärt jeden Zweifel von vornherein für unbegründet, damit wird die Behauptung weniger prüfbar, nicht mehr."},{"option":3,"text":"Eine Behauptung wäre gestützt, wenn Ergebnisse vorlägen. Der Verkäufer legt aber weder Messungen noch andere Belege vor, sondern urteilt nur über die Haltung des Kritikers. Ein Urteil über eine Person ersetzt keinen Beleg für die Wirkung."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Hansson, S. O. (2008/2025): „Science and Pseudo-Science“, Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschnitt 1, 4.3, 5.1","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"89997d203d4e0915"}},{"id":"qx-f-057","clusterId":"F","werkstueckRef":"F.4.1","stufe":3,"question":"Eine Bekannte erzählt dir, ihre Schwester habe ihre Krebstherapie abgebrochen und setze nun nur noch auf Energiearbeit und Kristalle. Die Bekannte meint: „Esoterik ist doch eine harmlose Quelle von Trost, jeder darf glauben, was er will.“ Was ist an dieser Einschätzung für den vorliegenden Fall am ehesten falsch?","options":["Sie übersieht, dass der Schaden entsteht, wenn ein Heilversprechen eine wirksame Behandlung ersetzt, nicht schon durch den Trost selbst.","Sie übersieht, dass die Verbreitung eines Glaubens nichts über seine Richtigkeit sagt, auch wenn viele Menschen ihn teilen und er ihnen hilft.","Sie übersieht, dass jeder, der etwas glaubt, es auch belegen muss, bevor er es für sich selbst in Anspruch nehmen oder anderen empfehlen darf.","Sie übersieht, dass viele esoterische Praktiken aus fremden Kulturen stammen und ihre Übernahme ohne Kenntnis des Ursprungs respektlos ist."],"correctIndex":0,"explanation":"Trost und Inspiration können für viele Menschen harmlos sein. Problematisch wird es dort, wo ein unbelegtes Heilversprechen eine nachweislich wirksame Behandlung verdrängt: Dann steht die Gesundheit auf dem Spiel, und die Berufung auf „jeder darf glauben, was er will“ geht am Kern vorbei. Ähnlich bedenklich ist es, wenn die ständige Selbst-Fokussierung („Du erschaffst deine eigene Realität“) dazu führt, dass Verantwortung für andere aus dem Blick gerät. Entscheidend sind die Folgen für konkrete Menschen. Dass viele einen Glauben teilen, sagt zwar nichts über seine Richtigkeit, ist aber nicht das, worauf sich die Bekannte stützt. Eine Pflicht zum Beleg gilt für das, was man anderen als Heilmittel anbietet, nicht für privaten Trost. Die Herkunft einzelner Praktiken ist ein anderes Thema und ändert an der Gefahr für die Schwester nichts.","coreRule":"⚡ Gefährlich wird eine Weltanschauung nicht durch ihren Trost, sondern dort, wo sie wirksame Behandlung ersetzt oder Mitmenschen aus dem Blick verliert.","beleg":"Werkstück F.4.1 (Abschluss-Diagnose des Pathologen)","status":"entwurf","scenario":"","kurz":"Der Schaden liegt nicht im Trost, sondern darin, dass ein unbelegtes Heilversprechen eine wirksame Krebsbehandlung verdrängt. „Jeder darf glauben, was er will“ geht daran vorbei: Entscheidend sind die Folgen für die Schwester, nicht die Freiheit zu glauben.","prueffrage":"Was hat die Schwester konkret aufgegeben, und was kann das bei einer Krebserkrankung bedeuten?","rueckmeldung":[{"option":1,"text":"Dass Verbreitung und Nutzen eines Glaubens nichts über seine Richtigkeit sagen, stimmt. Die Bekannte beruft sich darauf aber gar nicht: Sie hält Esoterik für harmlos, und genau dort liegt der Fehler, nicht in einem Schluss von der Verbreitung auf die Wahrheit."},{"option":2,"text":"Eine Pflicht, alles Geglaubte zu belegen, geht zu weit. Privater Trost braucht keinen Beleg. Belege braucht, wer anderen etwas als Heilmittel anbietet oder dafür eine wirksame Behandlung aufgibt, und darum geht es hier."},{"option":3,"text":"Ob Praktiken aus anderen Kulturen respektvoll übernommen werden, ist eine eigene Frage. Für die Schwester ändert sie nichts: Das Szenario nennt keine solche Herkunft, und die Gefahr entsteht dadurch, dass die Therapie abgebrochen wurde."}],"familie":"ergaenzen-oder-ersetzen","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Johnson, S. B.; Park, H. S.; Gross, C. P.; Yu, J. B. (2018): „Use of Alternative Medicine for Cancer and Its Impact on Survival“, J Natl Cancer Inst 110(1), S. 121–124 (Abstract öffentlich, PMID 28922780)","oeffentlich":true,"doi":"10.1093/jnci/djx145","abruf":"2026-10-12"},{"typ":"doi","kurz":"Asser, S. M.; Swan, R. (1998): „Child fatalities from religion-motivated medical neglect“, Pediatrics 101(4), S. 625–629 (Abstract öffentlich, PMID 9521945)","oeffentlich":true,"doi":"10.1542/peds.101.4.625","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"5891f44c7c3f3007"}},{"id":"qx-f-058","clusterId":"F","werkstueckRef":"F.4.1","stufe":4,"question":"Ein Freund erklärt: „Ich glaube an Astrologie, Kristallheilung, Reinkarnation und an die Kraft positiven Denkens. Das passt alles zusammen, weil für mich zählt, was sich richtig anfühlt.“ Warum kann ein solches Weltbild praktisch jede unbelegte Behauptung problemlos aufnehmen?","options":["Weil ein Lehrer oder Meister jede neue Behauptung vorab prüft und freigibt, sodass er sie nicht selbst prüfen muss.","Weil seine Gemeinschaft Zweifel nicht duldet und Mitglieder, die neue Behauptungen ablehnen, aus der Gruppe ausschließt.","Weil Angst vor Krankheit und Tod ihn so verletzlich macht, dass er jedes Heilversprechen annimmt, das Hoffnung verspricht.","Weil sein Weltbild keine feste Lehre und keinen Prüfmaßstab außer dem eigenen Gefühl kennt und deshalb alles einbauen kann."],"correctIndex":3,"explanation":"Ein Weltbild, das sich aus frei gewählten Bausteinen zusammensetzt und als einzigen Maßstab das eigene Gefühl akzeptiert, kennt kein Kriterium, das etwas ausschließen könnte. Wo nichts geprüft wird, kann auch nichts durchfallen: Astrologie, Kristallheilung und Reinkarnation lassen sich daher widerspruchslos nebeneinander einbauen, auch wenn keine davon belegt ist. Hinzu kommt: Kritik lässt sich mit Sätzen wie „Das ist nur deine materialistische Sichtweise“ abwehren, das System ist also nicht widerlegbar (unfalsifizierbar). Ein festes Lehrgebäude hätte dagegen Regeln, die manches ausschließen würden. Die Esoterik ersetzt überprüfbare Evidenz durch subjektive innere Erfahrung und macht sich dadurch immun gegen Kritik. Ein Meister, der Behauptungen freigibt, oder eine Gruppe, die Zweifel unterdrückt, kennzeichnen andere Weltbilder; hier ist von beidem keine Rede. Angst vor Krankheit mag Menschen empfänglich machen, erklärt aber nicht, warum das Weltbild selbst alles aufnehmen kann.","coreRule":"⚡ Wo nur das eigene Gefühl zählt, kann jedes Modul rein, auch das unbelegte: Ein Weltbild, das nichts ausschließt, belegt nichts.","beleg":"Werkstück F.4.1 (Die Esoterik als Wurzel und Nährboden; Abschluss-Diagnose des Pathologen)","status":"entwurf","scenario":"Gespräch mit einem Freund über sein persönliches Weltbild.","kurz":"Wenn das eigene Gefühl der einzige Maßstab ist, gibt es kein Kriterium, an dem etwas durchfallen könnte, und jede Behauptung passt hinein. Der naheliegende Fehler ist, die Ursache bei Gruppen, Meistern oder Ängsten zu suchen statt im Weltbild selbst.","prueffrage":"Hat der Freund je eine Überzeugung wieder aufgegeben, und was hätte ihn dazu bringen können?","rueckmeldung":[{"option":0,"text":"Ein Meister, der jede Behauptung freigibt, würde ein Weltbild tatsächlich offen für vieles machen, wäre aber selbst schon ein Maßstab. Im Gespräch kommt kein Lehrer vor: Der Freund wählt seine Bausteine selbst und prüft sie nach Gefühl."},{"option":1,"text":"Gruppen, die Zweifel unterdrücken, gibt es und sie prägen manche Weltbilder. Eine Gemeinschaft wird hier aber gar nicht erwähnt, und eine Gruppe, die Ablehnung bestraft, hätte Regeln, die manches ausschließen. Das erklärt nicht, warum hier alles hineinpasst."},{"option":2,"text":"Ängste können Menschen empfänglich für Heilversprechen machen. Das erklärt aber nur, warum jemand zugreift, nicht warum das Weltbild selbst alles aufnehmen kann. Von Angst steht im Gespräch ohnehin nichts; gefragt ist nach der Bauweise des Weltbilds."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Hansson, S. O. (2008/2025): „Science and Pseudo-Science“, Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschnitt 1, 4.3","abruf":"2026-10-12"},{"typ":"url","kurz":"Universität Münster, Exzellenzcluster Religion und Politik (2012): Pressemitteilung zur Patchwork-Religiosität (Christel Gärtner)","oeffentlich":true,"url":"https://www.uni-muenster.de/imperia/md/content/religion_und_politik/aktuelles/2012/12_2012/pm_patchwork-religiositaet.pdf","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"305b54cf8ec92152"}},{"id":"qx-f-059","clusterId":"F","werkstueckRef":"F.4.2","stufe":1,"question":"Auf welche Art von Rechtfertigung stützt sich deine Freundin damit?","options":["Auf Autorität: Die Behauptung gilt als wahr, weil eine Schrift und eine Lehrinstanz sie bestätigen, nicht weil sie geprüft wurde.","Auf Experiment: Die Behauptung wurde unter kontrollierten Bedingungen getestet und hat sich dabei bewährt.","Auf Mehrheit: Die Behauptung gilt als wahr, weil die meisten Menschen auf der Welt sie unabhängig voneinander für richtig halten.","Auf persönliche Erfahrung: Die Behauptung gilt als wahr, weil sie selbst sie erlebt und für sich überprüft hat."],"correctIndex":0,"explanation":"Wer sich auf eine heilige Schrift und eine Lehrinstanz beruft, stützt sich auf Autorität: Die Wahrheit wird in diesem Rahmen nicht durch empirische Experimente entdeckt, sondern durch göttliche Offenbarung empfangen. Über Fragen von Sinn und Ethik hat die Wissenschaft nicht zu entscheiden. Bei überprüfbaren Tatsachenbehauptungen wie dem Alter der Erde betreten Glaubenslehren dagegen das Feld empirischer Prüfung, und Konflikte mit den Befunden sind deshalb angelegt. Dass eine Schrift und eine Gemeinde etwas lehren, ersetzt keine Prüfung.","coreRule":"⚡ Autorität ist keine Prüfung: Eine Aussage gilt nicht schon deshalb als belegt, weil eine Schrift oder Institution sie verkündet.","beleg":"Werkstück F.4.2 (Die epistemologische Grundlage: Offenbarung vs. Realität)","status":"entwurf","scenario":"Du diskutierst mit einer Freundin über die Frage, ob die Erde nur 6.000 Jahre alt ist. Sie entgegnet: „Ich glaube das, weil es in unserer heiligen Schrift steht und unsere Gemeinde es seit Jahrhunderten so lehrt.“","quote":"","quoteLabel":"","kurz":"Die Freundin beruft sich auf Schrift und Gemeindelehre, also auf Autorität. Eine Lehre ersetzt aber keine Prüfung, so alt sie auch ist, besonders bei Tatsachenfragen wie dem Alter der Erde.","prueffrage":"Was hat die Freundin selbst beobachtet oder gemessen, und was hat sie von anderen übernommen?","rueckmeldung":[{"option":1,"text":"Ein Experiment würde etwas Überprüfbares voraussetzen, das irgendwo kontrolliert getestet wurde. Genannt werden aber nur Schrift und Gemeindelehre. Beim Alter der Erde gibt es zwar empirische Befunde, doch auf die stützt sie sich nicht."},{"option":2,"text":"Eine lange Tradition kann nach breiter Zustimmung klingen. Gemeint ist aber nur die eigene Gemeinde, nicht die Mehrheit der Menschen, und deren Lehre wird weitergegeben, nicht von vielen unabhängig gewonnen."},{"option":3,"text":"Ihr Glaube kann sich für sie persönlich echt anfühlen. Als Grund nennt sie aber Schrift und Lehre, kein eigenes Erlebnis oder eine eigene Prüfung. Das Alter der Erde lässt sich ohnehin nicht durch bloßes Erleben überprüfen."}],"familie":"autoritaet-pruefen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"„Religion and Science“, Stanford Encyclopedia of Philosophy (2017, rev. 2022)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/religion-science/","seite":"Abschnitt 1.3, 2.1, 3.1","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"09e31fd6f405c16b"}},{"id":"qx-f-060","clusterId":"F","werkstueckRef":"F.4.2","stufe":3,"question":"Worin liegt der entscheidende Unterschied zwischen dem Gespräch, das du als gefährlich einstufen würdest, und den harmlosen?","options":["Gefährlich ist D, weil dort eine überprüfbare Behauptung gegen Belege abgeschirmt und Zweifel als Sünde gebrandmarkt wird.","Gefährlich ist B, weil feste Schriften und eine verbindliche Auslegung durch die Gemeinde das Nachfragen stark erschweren.","Gefährlich ist C, weil große Reichweite und viel Einfluss in einer Stadt eine Gemeinschaft oft zur Bedrohung machen.","Gefährlich ist A, weil Aussagen über Sinn und Lebensführung der Wissenschaft entzogen sind und sich nicht prüfen lassen."],"correctIndex":0,"explanation":"Entscheidend ist, ob eine Aussage prüfbar ist und trotzdem gegen Belege geschützt wird. Ob Gebet eine medizinische Behandlung ersetzt, ist eine überprüfbare Behauptung über die Welt, und ein Irrtum kann hier das Leben des Kindes gefährden. Wird diese Frage zusätzlich mit „Sünde“ belegt, ist Zweifel nicht mehr erlaubt. Sinn, Trost und Gemeinschaft (A) sind keine Tatsachenbehauptungen, über die Belege entscheiden könnten, und feste Schriften (B) oder Einfluss (C) schirmen für sich genommen noch keine prüfbare Behauptung ab. Gefährlich wird es dort, wo prüfbare Behauptungen gegen Belege immunisiert werden, Zweifel als Sünde sanktioniert wird oder Ausgrenzung, Zwang oder Gewalt gerechtfertigt werden.","coreRule":"⚡ Sinn und Moral sind nicht das Problem; prüfbare Behauptungen, die Belege abwehren, sind es.","beleg":"Werkstück F.4.2 (Der Kipppunkt; Red Flags)","status":"entwurf","scenario":"Vier Gespräche über Glauben:\\n\\nA: Eine Frau sagt: „Mein Glaube gibt meinem Leben Sinn und der Gemeinde Halt.“\\nB: Ein Mann sagt: „Meine Religion hat feste Schriften, und unsere Gemeinde legt sie verbindlich aus.“\\nC: Eine Gemeinde unterstützt ihre Mitglieder stark und hat dadurch großen Einfluss in ihrer Stadt.\\nD: Ein Vater sagt: „Unser Sohn braucht keine Antibiotika, Beten heilt ihn. Wer daran zweifelt, versündigt sich.“","kurz":"Entscheidend ist, ob eine prüfbare Behauptung gegen Belege geschützt wird. Ob Beten Antibiotika ersetzt, lässt sich klären; wer Zweifel dazu als Sünde brandmarkt, verbietet die Prüfung. Sinn, Halt und Gemeinschaft stellen gar keine solche Behauptung auf.","prueffrage":"Was stünde in jedem der vier Gespräche auf dem Spiel, wenn sich die Beteiligten irren?","rueckmeldung":[{"option":1,"text":"Feste Schriften und verbindliche Auslegung können Nachfragen erschweren, das ist ein berechtigter Gedanke. Für sich genommen schützen sie aber noch keine prüfbare Behauptung gegen Belege und bestrafen keinen Zweifel; das fehlt in Gespräch B."},{"option":2,"text":"Große Reichweite und viel Einfluss wirken schnell bedrohlich. Sie sagen aber nichts darüber, ob etwas gegen Belege abgeschirmt wird; hier unterstützt die Gemeinde zunächst ihre Mitglieder, und Größe allein ist kein Gefahrenzeichen."},{"option":3,"text":"Dass Sinn und Lebensführung sich nicht wissenschaftlich prüfen lassen, stimmt. Genau deshalb steht dort nichts im Konflikt mit Belegen: Es wird keine Tatsache behauptet, über die Daten entscheiden könnten, also auch nichts gegen Belege geschützt."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Asser, S. M.; Swan, R. (1998): „Child fatalities from religion-motivated medical neglect“, Pediatrics 101(4), S. 625–629 (Abstract öffentlich, PMID 9521945)","oeffentlich":true,"doi":"10.1542/peds.101.4.625","abruf":"2026-10-12"},{"typ":"url","kurz":"Hansson, S. O. (2008/2025): „Science and Pseudo-Science“, Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschnitt 1","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"bd8d973a94b8ce5e"}},{"id":"qx-f-061","clusterId":"F","werkstueckRef":"F.4.2","stufe":2,"question":"Welche Entgegnung auf diesen Satz ist am stärksten?","options":["Religiöse Menschen handeln im Alltag nachweislich etwas moralischer; trotzdem lässt sich Moral auch säkular begründen.","Nichtreligiöse Menschen handeln im Alltag nachweislich etwas moralischer; trotzdem lässt sich Moral auch säkular begründen.","Moral endet bei jedem Menschen, sobald Geld ins Spiel kommt; trotzdem lässt sich Moral auch säkular begründen.","Moralisches Handeln im Alltag lässt sich schwer erfassen; trotzdem lässt sich Moral auch säkular begründen."],"correctIndex":3,"explanation":"Die Behauptung unterstellt zweierlei: dass es ohne Religion an Moral mangelt und dass es ohne sie keinen verlässlichen Maßstab gibt. Ob religiöse oder nichtreligiöse Menschen im Alltag moralischer handeln, lässt sich nur schwer erfassen, weil Selbstauskünfte ihre Grenzen haben; ein Vorsprung einer der beiden Gruppen ist deshalb nicht belegt (eine große Befragung im Alltag, Hofmann u. a. 2014 in Science, fand keinen Unterschied in den selbst berichteten Handlungen). Begründen lässt sich Moral außerdem auch säkular, etwa über Empathie, Vernunft und den Gesellschaftsvertrag, und selbst die Naturrechtstradition des Thomas von Aquin hält Moralgrundsätze für mit der Vernunft erkennbar. Wer eine Behauptung prüfen will, fragt also: Was würde sie im Alltag vorhersagen, und lässt sich das überhaupt zuverlässig feststellen?","coreRule":"⚡ Wer behauptet, etwas sei die Voraussetzung für Moral, muss zeigen, dass es ohne sie weniger Moral gibt.","beleg":"Werkstück F.4.2 (Ethik und funktionierendes Zusammenleben); Fn. gl-f-hofmann (Hofmann u. a. 2014, Science 345, S. 1340--1343); Fn. gl-f-naturrecht Am 14.10.2026 nach Sturms Urteil umgebaut: Die Studie (Hofmann u. a. 2014) steht nur noch in der Erklärung und in den Quellen, nicht mehr als Voraussetzung einer Option; Option 3 abgeschwächt („schwer erfassen“) und richtig, die frühere richtige Option 2 durch eine unpassende ersetzt.","status":"entwurf","scenario":"Im Gespräch über Werte und Erziehung fällt der Satz: „Ohne Religion gibt es keinen verlässlichen Maßstab für Moral.“ Du willst die Behauptung prüfen, statt sie nur zu glauben oder abzulehnen.","kurz":"Ob religiöse oder nichtreligiöse Menschen im Alltag moralischer handeln, lässt sich schwer erfassen; ein Vorsprung einer Gruppe ist nicht belegt. Und Moral lässt sich auch säkular begründen. Beides spricht gegen den „fehlenden Maßstab“.","prueffrage":"Was müsste man im Alltag religiöser und nichtreligiöser Menschen beobachten, wenn die Behauptung stimmt?","rueckmeldung":[{"option":0,"text":"Der zweite Teil stimmt: Moral lässt sich auch säkular begründen. Ein Vorsprung der Religiösen im Alltag ist aber nicht belegt; eine große Alltagsstudie fand in den selbst berichteten Handlungen beider Gruppen keinen Unterschied."},{"option":1,"text":"Dass sich Moral säkular begründen lässt, stimmt. Ein Vorsprung der Nichtreligiösen ist aber ebenso unbelegt wie die Ausgangsbehauptung, denn die Alltagsdaten zeigen keinen Unterschied zwischen den Gruppen."},{"option":2,"text":"Dass Geld Menschen in Versuchung führen kann, ist eine Beobachtung, aber keine Regel für jeden Menschen. Der Satz sagt nichts darüber, ob Religiöse oder Nichtreligiöse moralischer handeln, und ersetzt weder die Prüfung noch die säkulare Begründung."}],"familie":"beweislast-klaeren","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Hofmann, W.; Wisneski, D. C.; Brandt, M. J.; Skitka, L. J. (2014): „Morality in everyday life“, Science 345(6202), S. 1340–1343 (Abstract öffentlich, PMID 25214626)","oeffentlich":true,"doi":"10.1126/science.1251560","abruf":"2026-10-12"},{"typ":"url","kurz":"Murphy, M. (2002/2025): „The Natural Law Tradition in Ethics“, Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/natural-law-ethics/","seite":"Abschnitt 1.2","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-f-062","clusterId":"F","werkstueckRef":"F.4.2","stufe":4,"question":"In einem Vortrag heißt es: „Im Mittelalter glaubten alle an eine flache Erde, und die Kirche bekämpfte die Wissenschaft von jeher.“ Welche Einschätzung trifft zu?","options":["Die flache Erde ist eine Legende des 19. Jahrhunderts, der „ewige Krieg“ ist übertrieben, echte Einzelkonflikte gab es dennoch.","Beides stimmt im Kern: Die Kirche lehrte die flache Erde und verurteilte deshalb Kopernikus und Galilei als Ketzer.","Beides ist erfunden: Zwischen Kirche und Wissenschaft gab es nie einen nennenswerten Konflikt, auch nicht um Galilei.","Die flache Erde ist belegt, der Konflikt dagegen erfunden: Kirche und Wissenschaft arbeiteten stets harmonisch zusammen."],"correctIndex":0,"explanation":"Gelehrte des Mittelalters wussten, dass die Erde eine Kugel ist. Die Legende von der flachen Erde stammt aus dem 19. Jahrhundert, als Kirchenkritiker sie als Waffe im angeblichen Krieg zwischen Wissenschaft und Religion nutzten. Dass dieser Krieg „ewig“ gewesen sei, ist ebenfalls überzeichnet. Echte Konflikte gab es trotzdem: 1616 kam das Buch des Kopernikus auf den Index (er selbst war schon 1543 gestorben und wurde nie verurteilt), Galilei wurde 1633 verurteilt, und kreationistische Strömungen in manchen Religionsgemeinschaften bestreiten bis heute die Evolutionslehre. Die Streitfälle betrafen also das Weltbild und die Evolution, nicht die Kugelgestalt der Erde.","coreRule":"⚡ Der Konflikt war real, aber nicht ewig und nicht um die Kugelgestalt der Erde.","beleg":"Werkstück F.4.2 (Die epistemologische Grundlage); Fn. gl-f-flacheerde (Garwood 2008; Leisman 2019); Fn. gl-f-konflikt (Numbers 2009, S. 1 und 6)","status":"entwurf","kurz":"Die flache Erde im Mittelalter ist eine Legende des 19. Jahrhunderts, und der „ewige Krieg“ ist überzeichnet. Echte Streitfälle gab es trotzdem, etwa um Kopernikus und Galilei, und solche Zuspitzungen verführen dazu, Pauschalurteile zu übernehmen.","prueffrage":"Was schrieben Gelehrte des Mittelalters selbst über die Gestalt der Erde, und welche Streitfälle zwischen Kirche und Forschung sind mit Anlass und Datum überliefert?","rueckmeldung":[{"option":1,"text":"Die Konflikte sind real: Das Buch des längst toten Kopernikus kam 1616 auf den Index, Galilei wurde 1633 verurteilt. Sie betrafen aber das Weltbild, nicht die Erdform: Gelehrte des Mittelalters wussten, dass die Erde eine Kugel ist."},{"option":2,"text":"Die flache Erde ist tatsächlich eine Legende, und der „ewige Krieg“ ist überzeichnet. Ein „nie“ geht aber zu weit: Die Indizierung des Kopernikus 1616, Galileis Verurteilung 1633 und der Streit um den Kreationismus sind echte Konflikte."},{"option":3,"text":"Dass der angebliche Dauerkrieg übertrieben ist, stimmt. Die flache Erde ist aber gerade nicht belegt, und „stets harmonisch“ blendet echte Konflikte wie den Fall Galilei aus."}],"familie":"lehrgeschichte-pruefen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Russell, J. B. (1997): „The Myth of the Flat Earth“, Vortrag, American Scientific Affiliation","oeffentlich":true,"url":"https://www.asa3.org/ASA/topics/history/1997Russell.html","abruf":"2026-10-12"},{"typ":"url","kurz":"Miller, D. M. (2005/2025): „Galileo Galilei“, Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/galileo/","seite":"Abschnitt 2 und 5","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Numbers, R. L. (Hg.) (2009): Galileo Goes to Jail and Other Myths about Science and Religion. Harvard University Press (Einleitung S. 1, 6; Cormack, Myth 3, S. 28–34)","oeffentlich":false}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"e44144f5f70db009"}},{"id":"qx-f-063","clusterId":"F","werkstueckRef":"F.4.3","stufe":1,"question":"Welche Frage prüft diese Behauptung am besten?","options":["Welche realen Ängste ihrer Entstehungszeit bündeln Zombiefilme, und was in Geschichte und Erzählung spricht dafür?","Wie viele Menschen haben Zombiefilme im Kino gesehen, und wie hoch waren die Einspielergebnisse im Vergleich zu anderen Genres?","Mit welchen Tricks und Maskentechniken werden Zombies im Film dargestellt, und wie haben sich diese über die Jahrzehnte verändert?","Aus welcher Tradition stammt das Wort Zombie ursprünglich, und was bedeutete es in der Volksüberlieferung Haitis?"],"correctIndex":0,"explanation":"Die Frage macht die Deutung prüfbar: Welche Ängste und Spannungen ihrer Entstehungszeit bündeln Zombiefilme, und was spricht dafür oder dagegen? Der moderne Zombie lässt sich etwa als Bild für die Angst vor dem Verlust der Individualität lesen, in einer Masse, die nur noch konsumiert oder sich ansteckt. Das ist eine Lesart, kein Nachweis, aber sie nimmt die Zufallsbehauptung ernst und lässt sich an Geschichte und Erzählung überprüfen. Zuschauerzahlen zeigen nur, dass Filme ankommen, nicht warum. Maskentechnik und Wortherkunft sind für sich interessante Fragen, erklären aber nicht, warum das Motiv gerade in bestimmten Zeiten Konjunktur hat. Beides sagt nichts darüber, ob die Beliebtheit ein Zufall ist.","coreRule":"⚡ Zeig mir dein Monster, und ich sage dir, wovor sich deine Zeit fürchtet.","beleg":"Werkstück F.4.3 (Kernidee; Die Autopsie der drei Archetypen; Red Flags)","status":"entwurf","scenario":"Eine Podcast-Hörerin sagt: „Zombiefilme sind doch nur Unterhaltung. Dass sie gerade in Zeiten von Massenkonsum und Pandemien so beliebt sind, ist Zufall.“","kurz":"Die Behauptung wird prüfbar, wenn man fragt, welche Ängste ihrer Zeit Zombiefilme bündeln und was in Geschichte und Erzählung dafür spricht. Zuschauerzahlen, Maskentechnik oder Wortherkunft sagen nichts darüber, warum das Motiv gerade dann Konjunktur hat.","prueffrage":"Gab es auch Jahrzehnte, in denen Zombiefilme beliebt waren, ohne dass Massenkonsum oder Seuchen die Menschen beschäftigten?","rueckmeldung":[{"option":1,"text":"Hohe Zuschauerzahlen und Einspielergebnisse zeigen, dass Zombiefilme ankommen. Warum sie gerade in bestimmten Zeiten so gefragt sind, erklären sie nicht und beantworten damit auch nicht, ob die Beliebtheit Zufall ist."},{"option":2,"text":"Wie Zombies geschminkt und getrickst werden, ist für sich eine spannende Frage. Sie sagt aber nichts darüber, warum das Motiv in bestimmten Zeiten Konjunktur hat, und lässt die Zufallsbehauptung unberührt."},{"option":3,"text":"Die Herkunft des Wortes in der haitianischen Volksüberlieferung ist historisch aufschlussreich. Warum der Zombie im Film gerade in bestimmten Zeiten so beliebt ist, lässt sich daraus aber nicht ableiten."}],"familie":"schluss-pruefen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Grupe, D. (2014): „Faszination Zombie“, Schwäbische Zeitung (schwaebische.de), mit Aussagen von Gudrun Rath, Universität Konstanz","oeffentlich":true,"url":"https://www.schwaebische.de/panorama/faszination-zombie-762677","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Ackermann, H.-W.; Gauthier, J. (1991): „The Ways and Nature of the Zombi“, Journal of American Folklore 104(414), S. 466–494","oeffentlich":false,"seite":"S. 467, 489"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"0a4cfbe6abd7a957"}},{"id":"qx-f-064","clusterId":"F","werkstueckRef":"F.4.3","stufe":2,"question":"Ein Vortrag sagt: „Die Vampirlegende zeigt die Angst der Bauern vor dem adeligen Ausbeuter, siehe die Fälle von 1725 und 1732.“ Was ist an dieser Begründung fehlerhaft?","options":["Die Fälle von 1725 und 1732 betrafen Adelige, die ihre Untertanen aussaugten; die Deutung ist daher durch sie gedeckt.","Der Vampir stand in jeder Epoche allein für Seuchen und nie für gesellschaftliche Ausbeutung; die Deutung ist daher grundsätzlich falsch.","Die Fälle von 1725 und 1732 betrafen tote Dorfbewohner; der adelige Vampir ist erst eine spätere literarische Erfindung.","Die Fälle von 1725 und 1732 sind erfunden; aus dieser Zeit gibt es keine Berichte über Vampire oder Wiedergänger."],"correctIndex":2,"explanation":"Die Belege tragen die Deutung nicht: Die Fälle von 1725 (Plogojowitz) und 1732 (Paole) sind durch zeitgenössische amtliche Berichte gut belegt, betrafen aber tote Dorfbewohner, die als Wiedergänger galten, keine Adeligen. Den adeligen Verführer erfand John Polidori erst 1819 mit „The Vampyre“, Bram Stoker gab ihm 1897 seine endgültige Gestalt. Die Deutung als Bild für Ausbeutung passt also auf die Literaturfigur, nicht auf die Fälle, die der Vortrag als Beleg anführt. Seuchenangst und tabuisierte Sexualität sind weitere Hintergründe des Vampirmotivs.","coreRule":"⚡ Prüfe, ob der angeführte Beleg die Deutung wirklich trägt: Die Metapher vom adeligen Parasiten passt zum literarischen Vampir, nicht zu den Fällen des 18. Jahrhunderts.","beleg":"Werkstück F.4.3 („Der Vampir (Der adelige Parasit)“); Fn. gl-f-vampir-adel (Flückinger 1732; Bunson 2000; Bane 2010; Bräunlein 2015; Bohn 2008)","status":"entwurf","kurz":"Die angeführten Fälle betrafen tote Dorfbewohner, keine Adeligen; der adelige Vampir kam erst 1819 in der Literatur auf. Wer eine Deutung durch Fälle belegt, muss prüfen, ob diese Fälle überhaupt zur Deutung passen.","prueffrage":"Wer genau waren die Betroffenen in den Fällen von 1725 und 1732, und was berichten die damaligen Akten über sie?","rueckmeldung":[{"option":0,"text":"Solange man die Fälle nicht nachschlägt, wirkt die Deutung gedeckt. In den Fällen von 1725 und 1732 ging es aber um tote Dorfbewohner, nicht um Adelige, die ihre Untertanen aussaugten."},{"option":1,"text":"Seuchenangst ist tatsächlich ein wichtiger Hintergrund des Vampirmotivs, aber nicht der einzige. Die Ausbeutungsdeutung ist nicht grundsätzlich falsch: Sie passt auf die adelige Literaturfigur, nur nicht auf die angeführten Fälle."},{"option":3,"text":"Zweifel an alten Quellen sind oft berechtigt. Über beide Fälle gibt es aber zeitgenössische amtliche Berichte. Der Fehler der Begründung liegt woanders: Die Betroffenen waren tote Dorfbewohner, keine Adeligen."}],"familie":"schluss-pruefen","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Bräunlein, P. J. (2015): „Furchterregende Randzonen der Aufklärung: Skandalon Vampirismus“, Zeitschrift für Anomalistik 15, S. 55–87 (Repositorium Univ. Tübingen)","oeffentlich":true,"doi":"10.15496/publikation-39362","seite":"S. 61, 63","abruf":"2026-10-12"},{"typ":"doi","kurz":"Schneider, N. (2024): „Virale Monster: Spuren infektiöser Krankheiten im Vampirismus & die Konstruktion ansteckender Identität“, Thewis 11, S. 92–113","oeffentlich":true,"doi":"10.21248/thewis.11.2024.139","seite":"S. 97, 99","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"0f08af5af013157c"}},{"id":"qx-f-065","clusterId":"F","werkstueckRef":"F.4.3","stufe":3,"question":"Eine Schlagzeile behauptet: „Wissenschaftler haben das Rätsel gelöst: Vampire gab es nie, es waren Menschen mit Porphyrie!“ Wie solltest du diese Aussage einordnen?","options":["Als zu starke Behauptung: Eine Krankheit kann zu einem Mythos beigetragen haben, aber eine Ähnlichkeit einzelner Symptome beweist noch nicht, dass sie ihn vollständig erklärt.","Als Berufung auf die Tradition: Die Schlagzeile hält eine Aussage für richtig, nur weil sie seit langer Zeit so überliefert wird, und überzeugt deshalb nicht.","Als Zirkelschluss: Die Schlagzeile setzt voraus, was sie erst belegen will, und dreht sich in ihrer Begründung deshalb im Kreis, sodass sie nichts erklärt.","Als Strohmann: Die Schlagzeile verzerrt eine Gegenposition zur Karikatur, damit sie sich leichter widerlegen lässt, und überzeugt deshalb nicht."],"correctIndex":0,"explanation":"Die Schlagzeile schließt von einer Ähnlichkeit einzelner Symptome auf eine vollständige Erklärung. Das trägt nicht: Die Porphyrie-These ist in der Fachwelt umstritten. Winkler und Anderson bezeichnen sie als eher Gerücht denn als wissenschaftliche Theorie, ihr Urheber Dolphin habe sie nie veröffentlicht. Für Blutdurst bei Porphyriekranken oder eine Linderung durch Bluttrinken gibt es keinen Beleg. Der Vampir des Volksglaubens ging zudem auch bei Tageslicht um, die Lichtscheu kam erst später durch Filme wie „Nosferatu“ (1922) ins Vampirbild. Dasselbe gilt für die Tollwut-These: Auch dort wird Tollwut nur als einer von mehreren möglichen Beiträgen zu Werwolf- und Vampirlegenden verstanden. Eine medizinische Parallele kann ein Echo sein. Ob sie eine Erklärung ist, zeigt erst ein Beleg dafür, dass die Krankheit die Geschichte tatsächlich hervorgebracht hat. Wer Ähnlichkeit mit Ursache gleichsetzt, ersetzt die Prüfung durch eine passende Geschichte. Eine Berufung auf die Tradition liegt nicht vor, denn die Schlagzeile stellt sich gegen die überlieferte Deutung, statt sich auf sie zu stützen. Ein Zirkelschluss lässt sich ebenfalls nicht erkennen, weil gar keine Begründung genannt wird, die ihre eigene Behauptung voraussetzt. Und ein Strohmann fehlt, denn es wird keine Gegenposition verzerrt wiedergegeben.","coreRule":"⚡ Eine Ähnlichkeit ist ein Hinweis, kein Beweis: Medizinische Parallelen liefern ein Echo, nicht automatisch die ganze Erklärung.","beleg":"Werkstück F.4.3 (Das medizinische Echo); Fn. gl-f-11 (Gómez-Alonso 1998; Wasik, Murphy 2012); Fn. gl-f-12 (Winkler, Anderson 1990)","status":"entwurf","scenario":"","kurz":"Eine Ähnlichkeit einzelner Symptome ist noch keine vollständige Erklärung. Eine Krankheit kann zum Vampirmythos beigetragen haben, doch dass sie ihn hervorgebracht hat, müsste erst belegt werden.","prueffrage":"Welche Merkmale des Vampirs im alten Volksglauben passen zu den Symptomen, und für welche gibt es überhaupt einen Beleg?","rueckmeldung":[{"option":1,"text":"Beim Thema Vampire liegt der Gedanke an Überlieferung nahe. Die Schlagzeile stützt sich aber nicht auf Tradition, sondern stellt sich gegen die überlieferte Deutung und beruft sich stattdessen auf „Wissenschaftler“."},{"option":2,"text":"Dass die Schlagzeile nichts wirklich belegt, ist richtig. Ein Kreis liegt aber nicht vor, denn es wird gar keine Begründung genannt, die ihre eigene Behauptung voraussetzt. Der Fehler ist der Sprung von Ähnlichkeit auf Erklärung."},{"option":3,"text":"Ein Strohmann bräuchte eine Gegenposition, die verzerrt wiedergegeben wird. In der Schlagzeile kommt keine vor; sie stellt nur eine Behauptung auf. Das Problem liegt in der zu starken Behauptung selbst."}],"familie":"schluss-pruefen","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Cox, A. M. (1995): „Porphyria and vampirism: another myth in the making“, Postgraduate Medical Journal 71(841), S. 643–644 (PMC2398345)","oeffentlich":true,"doi":"10.1136/pgmj.71.841.643-a","seite":"S. 643 f.","abruf":"2026-10-12"},{"typ":"doi","kurz":"Gómez-Alonso, J. (1998): „Rabies: a possible explanation for the vampire legend“, Neurology 51(3), S. 856–859 (Abstract öffentlich)","oeffentlich":true,"doi":"10.1212/wnl.51.3.856"},{"typ":"literatur","kurz":"Winkler, M. G.; Anderson, K. E. (1990): „Vampires, Porphyria, and the Media: Medicalization of a Myth“, Perspectives in Biology and Medicine 33(4), S. 598–611, DOI 10.1353/pbm.1990.0051","oeffentlich":false,"seite":"S. 598, 600, 606"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"d3d4a7312b9667b8"}},{"id":"qx-f-066","clusterId":"F","werkstueckRef":"F.4.3","stufe":4,"question":"Was ist an dieser Sprache problematisch, und woran erkennst du es?","scenario":"Ein Redner nennt eine Minderheit eine „Seuche“ und „Bestien“, vor denen man das Land schützen müsse.","options":["Die Bilder werden auf reale Menschen angewendet: Eine ganze Gruppe wird zum Monster erklärt und damit zur Zielscheibe, gegen die Hass und Gewalt gerechtfertigt erscheinen.","Die Sprache ist ein Euphemismus: Harte Tatsachen werden mit milden Wörtern umschrieben, sodass die Zuhörer die wahre Tragweite des Geschehens nicht erkennen.","Es liegt ein Strohmann vor: Die Haltung der Minderheit wird absichtlich verzerrt dargestellt, damit sie sich leichter angreifen lässt, ohne dass ihre tatsächliche Position geprüft wird.","Es liegt ein Dammbruchargument vor: Aus einem kleinen ersten Schritt wird ohne Beleg eine unaufhaltsame Kette immer schlimmerer Folgen abgeleitet."],"correctIndex":0,"explanation":"In Geschichten sind Monster Spiegel von Ängsten: Man projiziert die Furcht in eine erfundene Figur, bekämpft sie und erlebt eine symbolische Entlastung. Dabei trifft die Gewalt niemanden. Hier läuft es umgekehrt: Das Monster-Bild wird auf reale Menschen gelegt. Wer als „Bestie“ oder „Seuche“ gilt, wird entmenschlicht, und gegen eine Seuche darf man alles tun. So lenkt Propaganda reale Ängste auf ein Feindbild, und die Geschichte zeigt, dass entmenschlichende Propaganda Gewalt vorbereiten kann. Beschönigt wird hier nichts, die Wörter sind im Gegenteil drastisch, ein Euphemismus ist es also nicht. Einen Strohmann gibt es nicht, weil der Redner gar keine Position der Minderheit wiedergibt, die er verzerren könnte. Und ein Dammbruchargument fehlt, denn von einer Kette von Folgeschritten ist nirgends die Rede.","coreRule":"⚡ Monster in der Fiktion sind Spiegel; Monster-Sprache über Menschen ist Entmenschlichung.","beleg":"Werkstück F.4.3 (Anwendung & Relevanz: Im Verständnis von Propaganda; Der Kipppunkt)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Das Monster-Bild trifft hier reale Menschen: Wer als „Seuche“ oder „Bestie“ gilt, wird entmenschlicht, und gegen eine Seuche scheint alles erlaubt. Das ist kein Stilmittel, sondern bereitet Gewalt vor.","prueffrage":"Was bliebe von der Forderung des Redners übrig, wenn er dieselbe Gruppe in ruhigem Ton und mit Zahlen beschriebe?","rueckmeldung":[{"option":1,"text":"Ein Euphemismus verharmlost mit milden Wörtern. Hier ist es umgekehrt: „Seuche“ und „Bestien“ sind so drastisch wie möglich, und gerade das Drastische ist das Problem."},{"option":2,"text":"Ein Strohmann verzerrt eine Position, die jemand tatsächlich vertritt. Der Redner gibt aber gar keine Haltung der Minderheit wieder, er etikettiert die Menschen selbst, und das ist ein anderes Muster."},{"option":3,"text":"Ein Dammbruchargument behauptet eine Kette immer schlimmerer Folgen aus einem ersten Schritt. Davon steht im Beispiel nichts: Der Redner reiht keine Folgen aneinander, er macht Menschen zu Monstern."}],"familie":"wir-und-die-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"United States Holocaust Memorial Museum: „Nazi Propaganda“, Holocaust Encyclopedia","oeffentlich":true,"url":"https://encyclopedia.ushmm.org/content/en/article/nazi-propaganda","abruf":"2026-10-12"},{"typ":"doi","kurz":"Over, H. (2021): „Seven Challenges for the Dehumanization Hypothesis“, Perspectives on Psychological Science 16(1), S. 3–13 (PMC7809340)","oeffentlich":true,"doi":"10.1177/1745691620902133","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Haslam, N. (2006): „Dehumanization: An Integrative Review“, Personality and Social Psychology Review 10(3), S. 252–264, DOI 10.1207/s15327957pspr1003_4","oeffentlich":false}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"a6953d5d3a84bd00"}}]`);export{t as n,n as t};